quests[26500] = { id = 26500, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir sind umzingelt", description = "Unser Krieg tobte schon, bevor die Zeitrechnung Eures Volkes begann. Mal sehen, ob Ihr etwas verändern könnt, {race}.\n\nDie Steintroggs sind ein Fehler der Titanen. Auf Eurer Welt sind sie dem Fluch des Fleisches erlegen. Doch hier in Tiefenheim seht Ihr sie in ihrer wahren Gestalt.\n\nWir sind hier umzingelt. Warum geht Ihr nicht hinaus und zertrümmert ein paar Troggs für uns? Seht Euch an, was in ihnen steckt.", sourceObjective = "Tötet 12 Wegelagerer der Steintroggs.", completion = "Kein schlechter Anfang, aber Ihr werdet noch mehr töten müssen, wenn Ihr den Steinvater retten wollt.\n\nViel mehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[26501] = { id = 26501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versiegelung des Eingangs", description = "Den Steintroggs ist es gelungen, sich unter unseren Häusern nach oben zu graben!\n\nIch habe Geomanten ausgesandt, die alle Gebäude versiegeln sollen. Sie benötigen jedoch Reagenzien und genügend Zeit außerhalb des Kampfes, um ihre Felssturzrituale zu vollenden.\n\nMeldet Euch bei General Kies Langfels, wenn Ihr fertig seid. Ihr findet ihn gen Norden an der Zerrissenen Front.", sourceObjective = "Helft den Irdenen Geomanten, sich aus dem Kampfgeschehen auszuklinken und gebt ihnen dann die Felssturzreagenzien, damit sie das Rüstlager, das Gasthaus, die Baracken und den Schrein versiegeln können.", completion = "Das ist gut. Nun müssen wir uns keine Sorgen mehr über einen Angriff der Steintroggs aus dem Hinterhalt machen.\n\nMal sehen, wie Ihr uns an der Front von Nutzen sein könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26502] = { id = 26502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donnersteine", description = "Die Zerrissene Front liegt im Norden. Dort finden die schwersten Gefechte statt.\n\nBegebt Euch ins eigentliche Steinruh und besorgt so viele Donnersteine, wie Ihr könnt. Unsere Ingenieure benötigen sie für die Katapulte.\n\nBringt sie zu Klei Lehmachse, wenn Ihr genug gefunden habt. Stört Euch nicht an seinem Ton. Er ist alt und griesgrämig und hätte schon vor Tausenden von Jahren in die Erde zurückkehren sollen.", sourceObjective = "Besorgt 12 Donnersteine.", progress = "<Der ältere Irdene hat mehr Risse als alle anderen. Er ist offensichtlich uralt.>\n\nWas stellt Ihr denn dar? Eine Art fleischiger Fehler? Verflucht, das seid Ihr!\n\n<Klei spuckt Staub auf den Boden.>Macht Euch nützlich oder haut ab von meiner Front.", completion = "<Klei grummelt in sich hinein.>\n\nJa, die passen. Legt sie da hinten hin.\n\n<Der Irdene mustert Euch mit einem Auge und spuckt Staub auf den Boden.>\n\nIch werde gleich etwas für Euch zu tun haben. Vielleicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26503] = { id = 26503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weitere Einschätzung der Gefahr", description = "Diese verdammten, wertlosen Gnolle führen nichts Gutes im Schilde. Ich spüre es in meinen Knochen. Die Gnollaktivität hat sich in den letzten zwei Wochen verdreifacht. Ich befürchte, dass sie einen Angriff auf Seenhain vorbereiten.\n\nIch möchte, dass Ihr die Lager der Gnolle in dieser Gegend aufsucht und dort alle Informationen sammelt, die Ihr finden könnt. Durchsucht die Lager unmittelbar nördlich von hier, östlich von hier und südöstlich von hier. Bringt mit, was Ihr dort findet.", sourceObjective = "Stehlt die Schlachtpläne der Gnolle, die Befehle der Gnolle und den Strategieführer der Gnolle.", progress = "Habt Ihr die Pläne der Gnolle gefunden?", completion = "Ich wusste es! Anscheinend steckt Jauler hinter dem Aufstand - was unglaublich ist, da wir ständig Gnolle namens Jauler umbringen. Ich weiß nicht, wie viele Söhne der ursprüngliche Jauler hatte, aber es müssen an die hundert sein.\n\nSieht jedenfalls so aus, als hätten wir noch einen Jauler zu töten.\n\nMagistrat Solomon muss davon erfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[26504] = { id = 26504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Rotkammgnolle", description = "Auf Befehl der Königswache von Sturmwind sollen alle Gnolle in dem Drei Ecken genannten Gebiet in der südwestlichen Ecke des Rotkammgebirges getötet werden.\n\nWenn Ihr die Gnolle in dieser Gegend beseitigt habt, dann meldet Euren Sieg Wachhauptmann Parker an der Turmwacht.", sourceObjective = "Tötet 15 beliebige Rotkammgnolle in der Drei Ecken genannten Gegend des Rotkammgebirges.", completion = "Wer gute Arbeit leistet, verdient eine Belohnung, oder?\n\nGebt nicht alles an einem Ort aus, {class}. Verteilt es ordentlich, wenn Ihr versteht, was ich meine.", sourceObjectiveStatus = "unverified-source-field" }
quests[26505] = { id = 26505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Parkers Bericht", description = "<Wachhauptmann Parker händigt Euch einen Bericht aus.>\n\nHier ist er, {name}. Bringt meinen Bericht nach Seenhain nördlich dieses Turms und übergebt ihn Magistrat Solomon. Erklärt ihm, dass wir eine umfassendere Lösung für den Umgang mit den Gnollen benötigen. Schlagt Sprengstoff vor. Viel Sprengstoff.\n\nUnd bleibt auf der Straße, wenn Ihr wisst, was gut für Euch ist. Zu überleben ist gut für Euch, nebenbei bemerkt. Falls Ihr Euch gefragt hattet, was gut für Euch ist. Jetzt wisst Ihr es... Ach, vergesst es!", sourceObjective = "Bringt Parkers Bericht zu Magistrat Solomon nach Seenhain im Rotkammgebirge.", progress = "Wo habe ich mein Monokel nur hingelegt?! Conacher, seid Ihr das?", completion = "<Magistrat Solomon setzt sein Monokel auf.>\n\nOh, Ihr seid nicht Conacher. Was habt Ihr denn da?\n\n<Ihr gebt Magistrat Solomon Parkers Bericht.>\n\nDas kann doch nicht wahr sein. Jauler? SCHON WIEDER?", sourceObjectiveStatus = "unverified-source-field" }
quests[26506] = { id = 26506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Würstchen mit Bohnen", description = "Ich brauche Eure Hilfe, {race}! Unsere Rationen sind verbraucht und die Wachen werden hungrig. Sie sehnen sich nach meinen weltberühmten Würstchen mit Bohnen, aber mir fehlen die Zutaten. Seid ein Schatz und helft mir, bitte.\n\nIch brauche ein paar Greiferzahnnieren, Kondorinnereien und TarantelaugenI. Ihr findet Greiferzähne, Kondore und Taranteln nahe dieses Turms. Seht Euch nur um!", sourceObjective = "Besorgt 4 Tarantelaugen, 4 Kondorinnereien und 4 Greiferzahnnieren.", progress = "Habt Ihr meine Zutaten bekommen?", completion = "PERFEKT! Die kommen sofort in den Topf. Das Abendessen sollte in ein paar Stunden fertig sein.\n\nDanke, Herzchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26507] = { id = 26507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versteinerte Delikatessen", description = "Versteinerte Fledermäuse.\n\nElementare dieser Größe sind wählerisch. So leicht werdet Ihr nichts Besseres finden.\n\nIm Osten gibt es Basilisken. Sie lassen Steinfledermäuse zu Stein werden, die ihnen zu nahe kommen und essen sie als Zwischenmahlzeit. Ihr solltet Fledermäuse in ihrem Territorium finden.\n\nIch muss Euch jedoch warnen... wenn Ihr diesem kleinen Elementar zu viel Aufmerksamkeit schenkt, werdet Ihr ihn möglicherweise nie wieder los. Er kann sehr aufmerksamkeitsbedürftig sein.", sourceObjective = "Besorgt 12 erstarrte Steinfledermäuse für Kieselchen.", progress = "<Kieselchen sieht zu Euch auf. Seine Augen beginnen schwach zu leuchten, werden mit jeder Sekunde größer und größer.>", completion = "<Kieselchen springt auf den Haufen versteinerter Fledermäuse und wälzt sich darin, so als habe er vergessen, dass es Euch überhaupt gibt. Es wäre vielleicht das Beste, Kors Warnungen Glauben zu schenken.>", sourceObjectiveStatus = "unverified-source-field" }
quests[26508] = { id = 26508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nidas Halskette", description = "Meine Freundin Nida hat ihre Halskette verloren. Wir finden sie nicht mehr. Wir haben den ganzen Tag hier geangelt und auch schon die Umgebung abgesucht. Ich befürchte, dass sie in den See gefallen ist. Unsere Eltern wollen nicht, dass wir im See schwimmen gehen... meine Mama sagt, Unterwasser gäbe es fiese Wesen, aber Ihr seht nicht aus, als ob Ihr Angst vor fiesen Wesen hättet.\n\nKönntet Ihr die Kette für Nida finden, bitte?", sourceObjective = "Findet Nidas Halskette.", progress = "Hallo. Ich habe meine Halskette verloren. Mein Papa hat sie mir geschenkt. Papa sagt, dass es Ungeheuer im See gibt. Habt Ihr Ungeheuer verprügelt?", completion = "Danke, dass Ihr meine Halskette gefunden habt, ehrenwerter {class}... Ihr seid sehr nett! Mein Kätzchen dankt Euch auch - nicht wahr, Effsee?", sourceObjectiveStatus = "unverified-source-field" }
quests[26509] = { id = 26509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein ungebetener Gast", description = "Schon wieder wurde mein Garten zertrampelt und geplündert. Und ich weiß, welche Bestie das getan hat. Es ist dieser verdammte Eber, den Marschall Marris Stopfwanst nennt.\n\nDie Narzissen kann ich erst wieder zur nächsten Saatzeit pflanzen. Zerstört! Dieser bösartige Eber hat alles zerstört. Erledigt diesen Schädling! Zeigt mir seinen Hauer, dann werde ich Euch gern belohnen. Meistens sucht er auf dem Feld südwestlich von Seenhain nach Futter, aber manchmal verschlägt es ihn hierher in meinen Garten.", sourceObjective = "Tötet Stopfwanst und nehmt Stopfwansts Hauer an Euch.", progress = "Ist Stopfwanst noch da draußen oder habt Ihr Seenhain endgültig von diesem Schädling befreit?", completion = "Endlich ist diese Landplage vorbei! Danke, {name}, Ihr habt mir einen großen Dienst erwiesen. Der Garten wird zur Erntezeit in voller Blüte stehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26510] = { id = 26510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir müssen uns vorbereiten!", description = "Jeden Tag verschwinden weitere Bürger. Wir glauben, dass die Gnolle dafür verantwortlich sind, aber wir wissen nicht, wo sie unsere Bürger hinbringen! Wenn Ihr uns helfen wollt, die Gnolle zu besiegen und unsere Bürger zu finden, müsst Ihr ordentlich ausgerüstet sein. Leider haben wir keine Gnomcorder mehr. Ohne einen Gnomcorder können wir während Eures Einsatzes nicht mit Euch kommunizieren.\n\nUnseren letzten funktionstüchtigen Gnomcorder haben die Murlocs letzte Woche bei einem Überfall gestohlen. Begebt Euch östlich von hier zum Immerruhsee und bringt ihn an Euch!", sourceObjective = "Findet den Gnomcorder.", progress = "Habt Ihr den Gnomcorder gefunden?", completion = "Hervorragend! Ich ändere noch ein paar Einstellungen, dann können wir beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26511] = { id = 26511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Säuberung des Immerruhsees", description = "Auf dem Weg zum Immerruhsee? Es wird Euch sicher freuen, dass wir gerade eine Belohnung auf Murlocs ausgesetzt haben. Tötet so viele Ihr könnt, dann wird man Euch belohnen. Es ist egal, welche Murlocs. Tötet sie einfach wahllos.\n\nDer Immerruhsee liegt genau östlich von Seenhain. Es ist der See. Ist Wasser drin... Kommt Euch das bekannt vor?", sourceObjective = "Tötet 10 beliebige Murlocs im Immerruhsee.", completion = "Ihr habt den Murlocs eine Lektion erteilt. Hoffentlich überlegen sie es sich demnächst zweimal, ob sie unsere Stadt überfallen wollen.\n\nNein, ich glaube auch nicht daran.", sourceObjectiveStatus = "unverified-source-field" }
quests[26512] = { id = 26512, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einstellung des Gnomcorders", description = "Der Gnomcorder scheint zu funktionieren. Ich habe ihn Euch angelegt, aber wir müssen noch die Empfangsfrequenz einstellen.\n\nVerlasst Seenhain in Richtung Norden und folgt der Straße bis zum Friedhof. Wenn Ihr am Friedhof angekommen seid, versuche ich zu senden.", sourceObjective = "Geht zum Friedhof von Seenhain, um die Frequenz des Gnomcorders einzustellen.", completion = "<Der Gnomcorder knistert und kracht.>\n\nKönnt Ihr mich hören, {name}? Ist das Ding an? Ah ja, ich sehe Euch jetzt dort.\n\nWir können anfangen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26513] = { id = 26513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie ein Furz im Wind", description = "Wir wurden letzte Nacht überfallen oder war es die Nacht davor? Ich weiß es nicht mehr genau. Seit drei Tagen kriege ich kein Auge zu. Wahrscheinlich verliere ich schon den Verstand.\n\nGnolle haben unsere Vorratslager geplündert. Alles haben sie mitgenommen! Rein und raus, lautlos wie ein Furz im Wind! Meine Soldaten sahen sie zu den Schluchten nordwestlich von hier laufen. Bringt unsere Vorräte zurück, {class}!", sourceObjective = "Bergt 8 Vorratskisten des Rotkammgebirges.", progress = "Habt Ihr die Vorräte geborgen?", completion = "Danke, Bürger. Ohne Euch wären wir verhungert oder schlimmer noch, hätten dort draußen selbst nach Nahrung suchen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26514] = { id = 26514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schluchtenspringen", description = "<Der Gnomcorder summt.>\n\nAls erstes steht ein flotter Marsch durch die Rotkammschlucht direkt im Norden von Seenhain an. Tötet jeden Gnom, den Ihr seht... huch, habe ich Gnom gesagt? Ich meinte Gnoll. Tötet jeden GNOLL, den Ihr seht und nehmt ihnen zum Beweis Eurer Tat das Halsband ab.\n\nEine Warnung, {name}; hütet Euch dort draußen vor den Ettins. Meine Kundschafter haben in letzter Zeit riesige blutdürstige Ettins in den Schluchten gesehen. Geht ihnen aus dem Weg, wenn Ihr weiterleben wollt.\n\nSolomon Ende. Ich melde mich.", sourceObjective = "Sammelt 10 Halsbänder der Rotkammgnolle.", progress = "Habt Ihr die Halsbänder bekommen?", completion = "<Der Gnomcorder knistert und kracht.>\n\nGute Arbeit, {name}. Ich habe gerade wichtige Informationen erhalten. Anscheinend sind unsere verhasstesten Feinde, die Schwarzfelsorcs, schlauer geworden...\n\n\n\nIch habe Euch ein paar Silbermünzen für die getöteten Gnome... äh, Gnolle übermittelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26515] = { id = 26515, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ongo'longos Rache", description = "Ich hab vor, Troll auf Troll zu hetzen.\n\nDie Blutfratzen halten einen miesen, alten Terrortroll in einer Grube gefangen. Seine Ketten sehen nicht sehr stabil aus. Ich weiß, wie so ein Unhold kämpft. Sie werden ihn nicht halten können, wenn er richtig wütend wird und loslegt.\n\nFindet den Terrortroll und kämpft gegen ihn, {name}. Bringt ihn nicht um... schlagt nur ein wenig auf ihn ein, bis er rot sieht und ausbricht. Dann geht ihm aus dem Weg. Der wird den Blutfratzen ordentlich Beine machen.", sourceObjective = "Kämpft gegen Ongo'longo, bis er seine Ketten sprengt.", completion = "Was für ein Spaß! Ich wünschte, ich wäre dabei gewesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26516] = { id = 26516, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das gehört jetzt uns", description = "Nur die stärksten und bösartigsten Blutfratzen sind übrig geblieben. Die Seelenfresser und Bluttrinker, die verkommenen Anhänger des bösen Gottes Hakkar.\n\nDenkt daran, dass Ihr hier nicht nur gegen Trolle kämpft, {name}. Ihr kämpft gegen dunkle und böse Kräfte, die dieses Land zu Asche verbrennen werden, wenn wir sie leben lassen!\n\nZeigt keine Gnade!", sourceObjective = "Tötet 5 Bluttrinker der Blutfratzen und 5 Seelenfresser der Blutfratzen in Jintha'Alor.", completion = "Wir haben sie niedergemäht! Jintha'Alor ist so gut wie ausgelöscht!", sourceObjectiveStatus = "unverified-source-field" }
quests[26517] = { id = 26517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schicksalsgipfel", description = "Geht jetzt zum Gipfel, {name}. Unsere Krieger wagen sich nur bis zu den letzten Toren vor. Sie sagen, dort es sei still wie in einem Grab; kein Geräusch, kein Atemzug, nichts rührt sich.\n\nSie halten es für eine Falle, aber das, was Ihr mir gebracht habt, lässt mich befürchten, dass etwas weit Böseres dort lauert. Geht zum Altar, findet heraus, was geschehen ist... und bringt mir ALLE mystischen Gegenstände oder dunklen Götzen, die Ihr dort findet! Habt Ihr mich verstanden?", sourceObjective = "Sammelt 8 Spinnengötzen der Blutfratzen auf dem Gipfel von Jintha'Alor.", progress = "Was habt Ihr gefunden?", completion = "Tot? Alle in der Nähe des Altars? Und sie hatten diese Spinnengötzen bei sich...\n\nDas ist Shadra. Die Spinnenloa! Sie versuchen ihre Kraft abzuzapfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26518] = { id = 26518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfprämie", description = "Es gibt kaum einen größeren Troll als Umboda Dreikopf. Er ist ein grausamer Schlächter, der die Köpfe von Zwergen und Trollen sammelt! Wird langsam Zeit, dass er bekommt, was er verdient.\n\nFindet den großen Schläger auf den unteren Terrassen und kommt mit seinem Kopf zurück!", sourceObjective = "Besiegt Umboda Dreikopf und holt Euch seinen Kopf.", progress = "Lasst mal sehen!", completion = "Was für eine hässliche Fratze. Hat wohl gehofft, unter den anderen Köpfen einen hübscheren zu finden!", sourceObjectiveStatus = "unverified-source-field" }
quests[26519] = { id = 26519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer die Ettins beherrscht", description = "Ihr seid über ein Dokument der Gnolle gestolpert. Der Gnoll, von dem diese Propaganda stammt, kann ein wenig schreiben:\n\nBRÜDER VON JAULER, HÖRT SCHMUTZPRANKE AN! ORCS GEBEN SCHMUTZPRANKE KUGEL! SCHMUTZPRANKE BEHERRSCHT ETTIN-VIECHER! SCHMUTZPRANKE ZERMALMT MENSCHIES! HOLT EUCH SCHMUTZPRANKES PRANK-O-GRAPH IN DEN RETHBANHÖHLEN. HÖHLE IM WESTEN, IN SCHLUCHT VERSTECKT!\n\n<Die Unterschrift besteht aus einem Prankenabdruck.>\n\n<Anscheinend hat jemand auch ein Stück aus der Schriftrolle gebissen.>\n\nIhr solltet dem vielleicht nachgehen.", sourceObjective = "Tötet Ardo Schmutzpranke.", completion = "<Die Kugel zischt, als Ihr sie berührt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[26520] = { id = 26520, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet Großknecht Oslow", description = "<Als Ihr die Kugel berührt, hört Ihr ein leises Klicken.>\n\n<Ihr nehmt die Kugel von ihrem Sockel.>\n\nNun kontrolliert Ihr die Kugel und damit auch die Ettins. Vielleicht könntet Ihr mit einem Ettin den riesigen Felsbrocken entfernen, unter dem Großknecht Oslow in Seenhain eingeklemmt ist. Findet einen Ettin und wendet die Kugel bei ihm an. Begebt Euch dann nach Seenhain.", sourceObjective = "Benutzt die Ettinsteuerungskugel, um einen Ettin zu unterwerfen. Setzt die Ettinsteuerungskugel dann bei Eurem gebändigten Schluchtettin ein und bringt ihn dazu, Großknecht Oslow in Seenhain von dem riesigen Felsbrocken zu befreien.", completion = "Ihr habt einen Ettin benutzt, um den Felsbrocken zu entfernen, unter dem Großknecht Oslow eingeklemmt war? Unglaubliche Leistung, {name}! Oslow wird Euch sehr dankbar sein, wenn er sich wieder gefangen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[26521] = { id = 26521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesichter des Bösen", description = "Die Blutfratzen haben ihre Tikimasken überall in Jintha'Alor an die Mauern gehangen. Wir werden ihre widerlichen Zauber und ihre dunkle Magie nicht dulden.\n\nDiese Botschaft werden wir ihnen überbringen und gleichzeitig ihre Abwehr durchbrechen! Nehmt diese Fackel, {class}. Zündet ihre Tikimasken an und lasst sie brennen. Wenn ihre dunklen Idole zu Asche zerfallen, werden sie erkennen, dass sie den Wildhämmern nicht willkommen sind!", sourceObjective = "Zündet mit der Tikifackel 8 Tikimasken in Jintha'Alor an.", completion = "Die Elemente tanzen, das Feuer lodert. Durch die Flammen sollen sie den Preis ihrer Verruchtheit erkennen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26523] = { id = 26523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles, was krabbelt", description = "Da oben hab ich noch was bemerkt... Jintha'Alor ist voller Spinnen. Kleine, nicht größer als Eure Hand. Nicht ungewöhnlich für das Hinterland, aber etwas daran ist seltsam.\n\nIch vertraue den Trollen nicht, wenn sie Haustiere halten. Sie haben was vor. Bringt mir ein paar dieser Spinnen. Haltet sie am Leben, wenn es geht, dann werden wir sehen, was mir die Geister zu erzählen haben...", sourceObjective = "Sammelt 8 huschende Spinnlinge in Jintha'Alor.", progress = "Zeigt mir, was Ihr habt.", completion = "Bei Kurdans Bart... solche Spinnen hab ich noch nie gesehen. Dahinter steckt dunkle Magie.", sourceObjectiveStatus = "unverified-source-field" }
quests[26524] = { id = 26524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkle Gefäße", description = "Die Blutfratzentrolle hier beten seit jeher den verderbten Gott Hakkar, Loa des Blutes, an. Er war ein krankes, pervertiertes Wesen. Vor langer Zeit wäre er beinahe in unsere Welt vorgedrungen, konnte jedoch besiegt werden.\n\nDie Blutfratzen rühren immer noch in ihren dunklen Kesseln, die sie vor Jahren mit Blut gefüllt haben. Entweder hoffen sie auf einen längst verstorbenen Geist oder sie haben einen neuen, ebenso düsteren Plan.\n\nBesorgt mir diese Gefäße, {name}. Wir müssen sie gemeinsam mit den Spinnen untersuchen, um zu verstehen, was hier vorgeht!", sourceObjective = "Besorgt 5 Gefäße mit besudeltem Blut aus Jintha'Alor.", progress = "Seid in der Nähe der Kessel vorsichtig, {class}. Die Blutfratzen werden sie nicht freiwillig hergeben!", completion = "Das ist nicht nur Blut... das ist Gift!\n\nSpinnen... Gift... Hoffentlich habe ich mit meiner Ahnung unrecht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26525] = { id = 26525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Giftige Geheimnisse", description = "Wenn das Opfer bereits vollbracht wurde, wird Shadra diese Welt langsam vergiften. In der Höhle wimmelt es wahrscheinlich schon von ihrer Brut.\n\nLasst sie nicht entkommen, {name}. Bringt alle Spinnen um, die Ihr finden könnt!", sourceObjective = "Tötet 8 Bruten von Shadra.", completion = "Die sind wir los. Mögen diese schrecklichen Wesen nie wieder unser Land betreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26526] = { id = 26526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagt die Bewahrerin", description = "Shadra, die Spinnenloa... die Königin des Giftes, ein Geist der Dunkelheit und des Todes! Wenn es ein Opfer gegeben hat, werden die Trolle einen letzten verzweifelten Versuch unternehmen, um sie heraufzubeschwören.\n\n Sollten die Blutfratzen Rituale begonnen haben, dürfen sie nicht vollendet werden.\n\nÜberprüft die Höhle hinter dem Altar an der Spitze von Jintha'Alor. In ihrem Inneren verbirgt sich vielleicht noch eine von Shadras Bewahrerinnen. Tötet sie und bringt mir, was sie bei sich trägt, damit wir herausfinden können, was dort los ist.", sourceObjective = "Tötet Morta'gya die Bewahrerin und bringt die Tafel von Shadra an Euch.", progress = "Durchsucht ihre Leiche. Ich will nicht, dass mögliche Fallen der Blutfratzen durch ihre Tode unentdeckt bleiben.", completion = "Eine Tafel! Wenn ich das richtig lese... wird hier ein Ritual beschrieben, mit dem man Shadra selbst in diese Welt holen kann, sowie die Götzen, die man dafür benötigt.\n\nDass Ihr die Bewahrerin getötet und die Tafel an Euch gebracht habt, war sehr gut, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26527] = { id = 26527, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Greifenmeister Krallenaxt", description = "Ich würde diese Tafel in Stücke schlagen, wenn ich das Recht dazu hätte. Doch diese Entscheidung darf ich nicht fällen. Greifenmeister Krallenaxt muss sie sehen.\n\nKehrt mit der Tafel zum Nistgipfel zurück. Greifenmeister Krallenaxt kümmert sich im Greifenhorst um die Tiere.\n\nBeeilt Euch... aber lasst die Tafel bloß nicht aus den Augen!", sourceObjective = "Bringt die Tafel von Shadra zu Greifenmeister Krallenaxt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26528] = { id = 26528, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge von Shadra", description = "Greifenmeister Krallenaxt hat mich hierher geschickt, damit ich mich um Shadra, die Königin des Giftes, kümmere. Jintha'Alor zu erobern, ist nicht genug... die Trolle könnten sich neu formieren und die Kreatur zu einem späteren Zeitpunkt beschwören, wenn wir es am wenigsten erwarten.\n\nZuerst sammeln wir die Artefakte, dann holen wir Shadra unter unseren eigenen Bedingungen in diese Welt. Wir werden die verdorbene Kreatur mit unseren Hämmern vernichten. Ihr müsst dabei helfen, die Artefakte zu finden, und wenn Ihr schon dabei seid, dann fügt den restlichen Trollen ordentlich Schaden zu.\n\nDazu benötigen wir zuerst das Auge von Shadra, das in Agol'watha im Norden bewacht wird.", sourceObjective = "Besorgt das Auge von Shadra aus Agol'watha.", progress = "Hatte die Tafel recht? Habt Ihr das Auge gefunden?", completion = "Gut gemacht, {name}. Schon bald werden wir an die Tür des Achtbeins klopfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26529] = { id = 26529, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fangzahn von Shadra", description = "Als nächstes brauchen wir den Fangzahn von Shadra.\n\nShadras eigene Brut bewacht ihn in den Gruselruinen im Osten. Abscheuliche Spinnen, groß wie Zwerge und doppelt so stark. Ihr Gift ist stark, {name}... seid nicht nachlässig.", sourceObjective = "Besorgt den Fangzahn von Shadra aus den Gruselruinen.", progress = "Habt Ihr den Fangzahn?", completion = "Das ist er... nur noch eines, mein Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[26530] = { id = 26530, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Panzer von Shadra", description = "Wir brauchen nur noch dieses letzte Stück, um Shadra endgültig auszuräuchern.\n\nDer Panzer von Shadra befindet sich im Besitz von Quiaga der Bewahrerin, der letzten Hohepriesterin der Spinnengöttin. Sie hält sich an der Spitze des Altars von Zul auf und wird von anderen fanatischen Zeloten bewacht.\n\nErklimmt den Altar bis zur Spitze und vernichtet sie. Sie wird den Panzer bei sich tragen. Bringt ihn hierher.", sourceObjective = "Tötet Qiaga die Bewahrerin und bringt den Panzer von Shadra an Euch.", progress = "Habt Ihr ihn?", completion = "Das war alles, mein Freund! Wir sind bereit!", sourceObjectiveStatus = "unverified-source-field" }
quests[26531] = { id = 26531, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Beschwörung von Shadra", description = "Unsere besten Kämpfer stehen bereit, das Idol wurde zusammengesetzt... es ist soweit, {name}.\n\nWir werden wie folgt vorgehen. Ihr reist mit dem Idol uns voran in Richtung Südwesten, nach Shadra'Alor. Ihr müsst das Idol an allen drei Tempeln einsetzen und Euch durch die Trolle, die sie bewachen, kämpfen.\n\nWenn Ihr das getan habt, wird Shadra in unsere Welt eindringen. Wir erwarten sie mit Zorn in unseren Herzen. Sagt meinen Jungs in Eurer Nähe Bescheid, sobald Ihr das Ritual vollendet habt.", sourceObjective = "Benutzt das Idol von Shadra am nordwestlichen, südwestlichen und östlichen Tempel in Shadra'Alor.", completion = "Krallenaxt und die Jungs sind direkt hinter Euch. Lasst uns beginnen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26532] = { id = 26532, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadra, Königin des Giftes", description = "Keine Zeit verschwenden, {name}! Sie kommt schon aus dem Wasser!\n\nGreifenmeister Krallenaxt ist bereits mit den Jungs unterwegs. Zeigen wir es dem Achtbein!", sourceObjective = "Tötet Shadra die Königin des Giftes.", completion = "Ihr habt heute Großes für die Wildhämmer geleistet, {name}. Ich wünschte, Falstad hätte das miterlebt.\n\nIm Namen des ganzen Klans möchte ich Euch gerne dafür entschädigen, dass Ihr diesen widerwärtigen Schatten von diesen Ländern ferngehalten habt. Ihr habt diese Belohnung redlich verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[26533] = { id = 26533, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zanzils Geheimnis", description = "Vor vielen Jahren verstießen die Gurubashi einen der ihren aus Zul'Gurub: Einen Troll namens Zanzil. Die Gründe dafür sind unklar, aber ich nehme an, dass es mit den starken, verhaltensverändernden Drogen zusammenhing, die er jedem, dem er begegnete, verabreichte. Wie dem auch sei, die Priester der Gurubashi und ihr Blutgott sind vernichtet worden, aber Zanzil der Ausgestoßene existiert noch...\n\n...ebenso wie seine starken, verhaltensverändernden Drogen.\n\nIch würde sie gern in die Finger bekommen, {race}. Überprüft die Zombies im Südosten.", sourceObjective = "Beschafft 5 Phiolen von Zanzils Mixtur.", progress = "Hervorragend... Ihr seid noch kein Zombie. Das ist gut.\n\nOh, äh... nichts. es gab nur ein... ein potentielles Risiko. Hatte ich vergessen, Euch zu warnen?", completion = "<Jasper analysiert das seltsame Gemisch vorsichtig.>\n\nDiese Mixtur ist... Ich verstehe sie nicht. Vielleicht sollten wir einige klinische Tests vornehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26534] = { id = 26534, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was hast du zu bieten, Zanzil?", description = "Besucher von Hartzangs Versteck müssen bei ihrer Ankunft einige Verzichtserklärungen unterschreiben. Eine davon erlaubt es uns, einfache Tests an ihnen vorzunehmen. Diese Klausel werden wir wohl wieder aktivieren.\n\nDoch dieses Mal sollten wir versuchen, unsere Kunden nicht zu vergiften. Ist besser fürs Geschäft.\n\n<Jasper füllt eine Karaffe mit Zanzils Mixtur und gestoßenem Eis.>\n\nDer südöstliche Turm des Verstecks dient als provisorisches Gefängnis. Wir nennen es \"Hartzangs Zuchthaus\". Lasst die Gefangenen trinken und sagt mir, was passiert.", sourceObjective = "Bietet Jaspers DschungelschorleGmurgl, Orgus und Kapitän Bartholomäus Weichbart an.", completion = "Was, wirklich? Das ist hochinteressant. In dem Fall...\n\nWen interessiert, wie das Zeug funktioniert! Ich brauche das Rezept!", sourceObjectiveStatus = "unverified-source-field" }
quests[26535] = { id = 26535, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zutaten für eine Katastrophe", description = "Ich brauche Zanzils Rezept mehr als je zuvor. Einer von Zanzils Lakaien in den Ruinen von Aboraz müsste es haben. Reist nach Osten, zur anderen Küste des Kaps und stehlt es für mich!", sourceObjective = "Besorgt Zanzils Rezeptur von einem von Zanzils Anhängern in den Ruinen von Aboraz.", progress = "Hat er Schimmerkraut verwendet? Er hat bestimmt Schimmerkraut benutzt.\n\nNein, warte... Bernsteinsamen! Es muss Bernsteinsamen sein.", completion = "Das ist faszinierend! Denkt an all die Anwendungsgebiete!\n\nNur um Missverständnissen vorzubeugen: Ich will keine Sklavenarmee oder so etwas. Nein, nein... Die Ogerexplosionen interessieren mich viel mehr!", sourceObjectiveStatus = "unverified-source-field" }
quests[26536] = { id = 26536, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donnerfälle", description = "Arnold und ich angeln schon seit Jahren in der Gegend um Sturmwind. So lange braucht man, um eine gute Stelle zu finden. Einer meiner Lieblingsorte wird Donnerfälle genannt.\n\nEr liegt südlich von Sturmwind im Wald von Elwynn. Das Beste an den Donnerfällen ist der violette Flussbarsch. Man findet ihn nur dort oben an den Wasserfällen. Arnold und mir fällt der lange Weg in letzter Zeit schwer, deshalb möchte ich Euch bitten, für uns dorthin zu gehen und einige Barsche zu fangen.", sourceObjective = "Fangt 4 violette Flussbarsche bei den Donnerfällen südlich von Sturmwind. Kehrt mit Eurem Fang zu Catherine Leland zurück.", progress = "Habt Ihr die Fälle gefunden?", completion = "Diese Barsche sehen gut aus, {name}. Wollt Ihr mit uns heute Abend Fische grillen?", sourceObjectiveStatus = "unverified-source-field" }
quests[26537] = { id = 26537, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerschmettert sie!", description = "Geht hinaus und erledigt sie für mich.\n\nBerserker, Erdberster, Todesreiter... mir egal! Zerschmettert diese Steintroggs!", sourceObjective = "Tötet 12 beliebige Steintroggs an der Zerrissenen Front.", completion = "Ihr habt ihnen ganz schön zugesetzt. Aber ich glaube, wir müssen auf eine etwas andere Weise vorgehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26538] = { id = 26538, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soforthilfe", description = "Viele unserer Krieger sind bei dem Zwielichtangriff auf unsere Luftflotte gefallen. Die Überlebenden schwimmen den Überresten der Flotte entgegen. Sie bluten und haben schwere Verbrennungen erlitten. Ich brauche Unterstützung vom Ufer, um diese Männer zu retten!\n\nIm Hafen des Drachenmals wird es doch wohl einen Arzt oder Medizinmann geben, der gewillt ist, anderen Orcs zu helfen. Geht ans Ufer und versucht, Heilvorräte aufzutreiben und zur Flotte zu bringen!", sourceObjective = "Sucht einen Medizinmann im Hafen des Drachenmals, nahe des Ufers.", completion = "<Gregor verbeugt sich respektvoll vor Zaela.>\n\nWenn dies Zaelas Wunsch ist, dann sollt Ihr Eure Vorräte bekommen. Sagt nur dem Kriegshäuptling des Drachenmals nichts davon...", sourceObjectiveStatus = "unverified-source-field" }
quests[26539] = { id = 26539, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Festgefahrene Verhandlungen", description = "Der Aufenthaltsort des Kriegshäuptlings ist unbekannt! Aber sein Plan muss fortgeführt werden. {name}, Ihr seht aus wie jemand, der weiß, was er tut.\n\nUnsere Verhandlungen mit dem Drachenmalklan sind festgefahren. Ihr Kriegshäuptling ist... anders als erwartet. Sorgt dafür, dass die Verhandlungen fortgeführt werden.\n\nTrefft Euch mit Ornak am Ufer. Er wird Euch alles erklären.\n\nRedet mit Horzog hier an Deck. Er wird für einen raschen Transport zum Ufer sorgen.", sourceObjective = "Sprecht mit Ornak im Hafen des Drachenmals. Horzog wird für einen raschen Transport zum Ufer sorgen.", completion = "Ich bin froh, dass Ihr hier seid, {class}. Vielleicht kann ein erfahrener Veteran, der für die Horde in Nordend und an anderen Orten gekämpft hat, den Anführern des Drachenmalklans Vernunft einreden...", sourceObjectiveStatus = "unverified-source-field" }
quests[26540] = { id = 26540, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefährliches Mitleid", description = "Der rote Drachenschwarm stellt den Aspekt des Lebens dar. Deshalb hat sein Blut heilende Wirkung.\n\nDie Verbände in dieser Kiste wurden in rotes Drachenblut getränkt. Das sind meine letzten Vorräte. Mögen sich Eure Krieger dank ihnen rasch erholen.\n\nEs ist egal, wie Eure Verhandlungen hier ausgehen, Ihr werdet immer Freunde im Drachenmalklan haben.", sourceObjective = "Bringt die Kiste mit Bandagen des Drachenmals zurück zu Kriegsfürst Krogg auf See vor dem Hafen des Drachenmals.", progress = "Könnt Ihr unseren Verwundeten Hoffnung machen?", completion = "Drachenblut!? Wir sollten unseren Verbündeten unter den roten Drachen besser nichts davon erzählen.\n\nTrotzdem ist es mächtige Magie... Unsere Truppen werden bald wieder bereit stehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26542] = { id = 26542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Das Hinterland!", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Greifenmeister Krallenaxt im Greifenhorst am Nistgipfel zu melden.\n\nUnsere neuen Brüder in der Allianz brauchen unsere Hilfe dabei, die aggressive Hordenoffensive in ihrer geliebten Heimat abzuwehren. Reist vom Arathihochland nach Norden durch den zwergischen Bergpass und folgt der Straße nach Nordwesten Richtung Nistgipfel.\n\nFür den Ruhm und die Ehre der Allianz!", sourceObjective = "Reist zum Nistgipfel im Hinterland und sprecht mit Greifenmeister Krallenaxt.", completion = "Willkommen am Nistgipfel, {name}. Im Namen des Obersten Thans Falstad danke ich Euch für Euer Kommen, um uns zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26543] = { id = 26543, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muscheln meucheln", description = "Nichts schmeckt so gut wie frisches monströses Muschelfleisch, {name}. In den letzten Wochen hatte ich so viel zu tun, dass ich keine Zeit hatte, zu den örtlichen Muschelgründen zu gehen. Könntet Ihr mir vielleicht einige dieser Delikatessen besorgen?\n\nIhr findet die Muscheln in der Nähe des Strandes an der Ostküste von Durotar. Rund um den Hafen von Orgrimmar sollte es jede Menge geben.", sourceObjective = "Besorgt 10 Stücke Fleisch einer monströsen Muschel von den Muscheln an der Ostküste Durotars, südlich von Orgrimmar. Kehrt danach zu Razgar zurück.", progress = "Habt Ihr die Muscheln gefunden?", completion = "Scheinen die richtigen Muscheln zu sein, {name}. Die werden gut schmecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[26544] = { id = 26544, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie werden schlauer...", description = "<Der Gnomcorder kracht und knackt.>\n\nDie Schwarzfelsorcs scheinen doch noch klug zu werden. Man hat mir gemeldet, dass sie sich mit den Gnollen verbündet haben und einen Angriff planen, Ich brauche Einzelheiten. {name}!\n\nÜberprüft die Rethbanhöhlen im westlichen Teil der Rotkammschlucht für mich. Sucht nach Orcs mit dunkler Haut. Tötet alle, denen Ihr begegnet und durchsucht ihre Leichen nach Informationen.\n\nSolomon Ende.", sourceObjective = "Besorgt das Sendschreiben der Orcs des Schwarzfelsklans.", progress = "Was habt Ihr herausgefunden?", completion = "<Der Gnomcorder summt und surrt.>\n\nLegt das Sendschreiben in das kleine Fach, damit ich es lesen kann. Ich spreche fließend Orcisch.\n\n<Ihr hört einen entsetzten Schrei im Hintergrund.>\n\nDiese Orcs scheinen auf Jaulers direkten Befehl hier zu sein. Das bedeutet, dass Jauler den Invasionsplan der Orcs besitzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26545] = { id = 26545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jauler muss sterben!", description = "<Der Gnomcorder summt.>\n\nIhr müsst Jauler finden, {name}. Er hält sich irgendwo im nördlichen Teil der Rotkammschlucht auf. Tötet den räudigen Hund und durchsucht seine Leiche nach den Invasionsplänen des Schwarzfeldklans. Sollte das gelingen, bringt die Pläne zu mir in das Rathaus von Seenhain.\n\nSolomon Ende.", sourceObjective = "Tötet Jauler und bergt die Invasionspläne des Schwarzfelsklans.", progress = "Habt Ihr die Invasionspläne des Schwarzfelsklans?", completion = "<Ihr gebt Magistrat Solomon die Pläne. Er beginnt zu lesen.>\n\nSchattenfellarmee!? Diese verfluchten Orcs! Diese Invasionspläne weisen darauf hin, dass die Orcs und die Gnolle eine gewaltige Streitmacht im Osten zusammenziehen. Gath'Ilzogg, der General des Schwarzfelsklans will wohl mit seinen Armeen durch Seenhain marschieren und Sturmwind direkt angreifen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26546] = { id = 26546, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klingenschnabelfreunde", description = "Für unseren Klan sind Greifen heilige Tiere. Wir verehren sie. Es sind majestätische Himmelswesen, mehr als nur Tiere. Sie sind intelligent und listig.\n\nManche behaupten, wir würden sie halten, aber es ist eher wie eine Freundschaft. Wenn Ihr Euch mit den Wildhämmern anfreunden wollt, dann freundet Euch zuerst mit unseren Greifen an! Nehmt diesen Futtersack. Alles darin ist frisch und gut. Ihre findet unsere ausgebildeten Klingenschnabelgreifen in den Wäldern südlich des Greifenhorsts. Würdet Ihr einige von ihnen für mich füttern?", sourceObjective = "Füttert 7 ausgebildete Klingenschnabelgreifen mit dem Greifenfutter.", completion = "Behandelt sie respektvoll, dann werden sie ebenso mit Euch umgehen.\n\nVergesst Eure Manieren und Ihr seid ein Auge los!", sourceObjectiveStatus = "unverified-source-field" }
quests[26547] = { id = 26547, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Räudige Bedrohung", description = "Wir beschützen unser Volk und unsere Greifen mit allen Mitteln. Dazu gehört, dass wir Räuber verjagen, und zwar die aus dem Wald und die der Horde.\n\nErst einmal werde ich Euch noch nicht bitten, uns vor den zweibeinigen Ungeheuern zu schützen. Räudige Silbermähnen streunen durch die Wälder im Süden. Sie attackieren die Greifen, die zu niedrig fliegen. Jagt einige Silbermähnen, damit sie erkennen, dass Greifen keine Beute sind.", sourceObjective = "Tötet 8 räudige Silbermähnen.", completion = "Das hilft uns sehr, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26548] = { id = 26548, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf zur Front", description = "Wir benötigen Eure Hilfe nun in dringenderen Angelegenheiten, {name}.\n\nDie Horde wird dort draußen immer dreister. Sie sind in unserer Territorium eingedrungen und greifen uns hemmungslos an. Die Waldtrolle der Bruchhauer attackieren den Sturmfederaußenposten sogar bei Tage!\n\nIch brauche Eure Hilfe. Sprecht draußen mit Guthrum Donnerfaust. Er wird Euch einen Greifen zum Sturmfederaußenposten geben. Kerr Eisenblick wird Euch alles erklären, wenn Ihr dort eintrefft.", sourceObjective = "Sprecht mit Kerr Eisenblick im Sturmfederaußenposten.", completion = "Schön, Euch hier draußen zu sehen! Wir können anfangen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26549] = { id = 26549, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wahnsinn", description = "Unsere letzten beiden Verhandlungsführer sind von den Gesprächen mit dem Kriegshäuptling des Drachenmalklans noch nicht zurückgekehrt. Ich glaube, wir müssen unsere Muskeln spielen lassen.\n\nDeshalb möchte ich, dass IHR dieses Mal den Unterhändler begleitet. Ihr Kriegshäuptling wird seine Haltung vielleicht ändern, wenn er erkennt, dass die Horde voll von kampferprobten Helden wie Euch ist.\n\nIhr müsst den Unterhändler nur in das Hauptlager im Hafen des Drachenmals begleiten und bedrohlich aussehen.", sourceObjective = "Begleitet den Hordenunterhändler in den Hauptsaal im Hafen des Drachenmals und trefft Euch mit Kriegshäuptling Mor'ghor vom Drachenmalklan. Sprecht mit Ornak an der Küste, sollte Euch der Unterhändler abhanden kommen.", progress = "{name}, ich habe gehört, dass Ihr mit dem \"Kriegshäuptling\" über den Beitritt zu Eurer Horde sprechen wollt.\n\nSeid vorsichtig, {class}.\n\nKommt danach zu mir...", completion = "Aufwachen, {name}! Wir haben nicht viel Zeit.\n\nIch habe Eure Ausrüstung gerettet.\n\nJetzt habt Ihr die Torheit unseres Anführers am eigenen Leib erlebt. Sein Blut ist verseucht, seine Wut unbezähmbar -- sein Bestreben, die Horde zu schlagen, wird uns alle vernichten!", sourceObjectiveStatus = "unverified-source-field" }
quests[26550] = { id = 26550, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durch die Hintertür", description = "Zanzil der Ausgestoßene, der vom Gurubashistamm verbannt wurde, soll meine Beute werden. Vor kurzem habe ich von meinen Brüdern im Norden erfahren, dass er in die Gesellschaft zurückkehren will. Aus diesem Grund hat er einen Abgesandten zu den Schädelspaltern geschickt. Das sind keine guten Nachrichten.\n\nIch möchte, dass Ihr Euch Zanzils Pläne einmal anseht. Nehmt diesen Weihrauch und stellt ihn vor dem Fledermaustotem in den Ruinen von Jubuwal östlich von hier ab. Hir'eek wird Euch von dort an führen.", sourceObjective = "Stellt den Weihrauch der Gurubashi vor dem Totem von Hir'eek ab und hört Euch Zanzils Plan an.", completion = "Das hatte ich vermutet. Zanzil ist zu hochmütig, um sich in die Streitigkeiten zwischen den Blutskalpen und den Schädelspaltern einzumischen. Nein, er ist Teil eines größeren Plans... Jin'do der Verhexer will mit seiner Hilfe Hakkar zurück nach Zul Gurub bringen.\n\nGut, dass wir das herausgefunden haben, denn es gibt eine einfache Lösung.", sourceObjectiveStatus = "unverified-source-field" }
quests[26551] = { id = 26551, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beseitigt den Ausgestoßenen", description = "Ihr werdet Zanzil töten. Ihr seid auf Hir'eeks Schwingen geritten und habt durch seine Augen geblickt; Ihr wisst, wo sich Zanzil in den Ruinen von Aboraz versteckt. Reist dorthin und tötet ihn.\n\nOh, und {race}: Benutzt diesen Fetisch, falls wir getrennt werden. Er funktioniert nur im Schlingendorntal und wird Euch hierher zurückbringen, solltet Ihr rasch zu mir gelangen müssen.\n\nViel Glück, {race}. Zanzil ist kein gewöhnlicher Gegner.", sourceObjective = "Reist zu den Ruinen von Aboraz am Kap des Schlingendorntals und kümmert Euch um Zanzil den Ausgestoßenen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26552] = { id = 26552, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durch das Trollloch", description = "Zanzils Portal nach Zul'Gurub ist noch geöffnet. Zul'Gurub ist ein gefährlicher Ort, aber Chabal glaubt, dass Ihr diese Aufgabe erfüllen könnt.\n\nDas Portal erwartet Euch.", sourceObjective = "Benutzt Zanzils Portal und betretet Zul'Gurub.\n\nSolltet Ihr Euch verlaufen oder nach Zul'Gurub zurückkehren müssen, sprecht mit Chabal in Hartzangs Versteck.", sourceObjectiveStatus = "unverified-source-field" }
quests[26553] = { id = 26553, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hohepriesterin Jeklik", description = "Vor Euch ragt eine Rampe, die zu einer der zahlreichen Terrassen der Stadt führt, bedrohlich empor. Die fledermausfömrigen Totems vor Euch weisen darauf hin, dass Ihr Euch im Reich der Hohepriesterin Jeklik, einer Anhängerin von Hir'eek, befindet.\n\nJeklik gehörte zu den Hakkar anbetenden Priestern, die Zanzil wiedererwecken wollte. Wenn Ihr Euch beeilt, gelingt es Euch vielleicht, die Erweckung aufzuhalten!", sourceObjective = "Vernichtet die Leiche der Hohepriesterin Jeklik, bevor Zanzil sie wiedererwecken kann.\n\nSolltet Ihr Euch verlaufen oder nach Zul'Gurub zurückkehren müssen, sprecht mit Chabal in Hartzangs Versteck.", sourceObjectiveStatus = "unverified-source-field" }
quests[26554] = { id = 26554, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hals über Kopf nach Zul'Gurub", description = "Zanzil der Ausgestoßene ist erneut durch eines seiner Portale geflohen. Folgt ihm!", sourceObjective = "Geht durch Zanzils Portal.\n\nSolltet Ihr Euch verlaufen oder nach Zul'Gurub zurückkehren müssen, sprecht mit Chabal in Hartzangs Versteck.", sourceObjectiveStatus = "unverified-source-field" }
quests[26555] = { id = 26555, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hohepriester Venoxis", description = "Venoxis war der zweite der beiden Priester, die Zanzil von den Toten erwecken wollte. Es ist Euch bereits gelungen, Hohepriesterin Jekliks Leiche zu vernichten... Venoxis muss der nächste sein.", sourceObjective = "Kümmert Euch um Zanzil den Ausgestoßenen und Hohepriester Venoxis.\n\nSolltet Ihr Euch verlaufen oder nach Zul'Gurub zurückkehren müssen, sprecht mit Chabal in Hartzangs Versteck.", completion = "Ich hatte Euch gebeten, Zanzil den Ausgestoßenen zu töten, einen niederen verbannten Einsiedler der Gurubashi, und was macht Ihr? Ihr stürmt in die Hauptstadt der Gurubashi und eliminiert einen ihrer Hohepriester! Beinahe sogar zwei! Es gibt nur ein Wort, um ein so unbedachtes und tollkühnes Unterfangen zu beschreiben:\n\nHeldenmut.\n\nJin'do der Verhexer schleicht immer noch in Zul'Gurubs Mauern umher, aber als Ihr Jeklik zerschmettertet, verlor er eines seiner Beine. Heute ist der Sieg unser.", sourceObjectiveStatus = "unverified-source-field" }
quests[26556] = { id = 26556, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Müll abladen verboten", description = "Seit die Goblins in Orgrimmar Schutz gesucht haben, werfen sie all ihren Unrat in unsere Wasserspeicher.\n\nIch weiß nicht, welche Konsequenzen das für unseren Fischbestand haben wird, aber es sind bestimmt keine guten. Ich habe Berichte über eine neue mutierte Fischart erhalten, die in der toxischen Pfütze nahe ihres Lagers gesichtet worden ist. Einige Exemplare würden mir dabei helfen herauszufinden, was genau dort vorgeht.\n\nWürdet Ihr mir aushelfen?", sourceObjective = "Angelt 6 giftige Pfützenfische und kehrt zu Razgar ins Tal der Ehre zurück, wenn Ihr fertig seid.", progress = "Habt Ihr ein paar Exemplare geangelt?", completion = "Gute Arbeit, {name}. Dank dieser Exemplare werden wir herausfinden, was in der giftigen Suppe dort vorgeht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26557] = { id = 26557, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Augen auf beim Angeln", description = "Seit Jahren angle ich im Wasser von Orgrimmar Sandkarpfen. In letzter Zeit ist mir aufgefallen, dass meine Köder nicht mehr so gut funktionieren wie früher. Ich vermute, dass dies etwas mit den Tauren zu tun hat, die ins Tal der Weisheit gezogen sind.\n\nIch habe mit einigen ihrer Angler gesprochen. Anscheinend hat sich der Geschmack der Fische geändert. Heutzutage beißen sie wohl bei Hirschaugen an. Ihr solltet nördlich von Orgrimmar, unmittelbar hinter dem nördlichen Tor, jede Menge Hirsche finden.", sourceObjective = "Erlegt einen Hirsch nördlich von Orgrimmar und benutzt sein Auge als Köder, um einen Sandkarpfen im Tal der Weisheit zu fangen. Kehrt danach zu Razgar ins Tal der Ehre zurück.", progress = "War das Auge ein guter Köder?", completion = "Hervorragend! Diese Sandkarpfen sind ganz schön wählerisch, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[26558] = { id = 26558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Beschwörung von Shadra", description = "Der Götze ist bereit, {name}. Ich hoffe, Ihr seid es auch.\n\nReist mit dem Götzen vor uns nach Shadra'Alor im Südwesten. Ihr müsst den Götzen an jedem der drei Tempel einsetzen.\n\nWenn Ihr das tut, wird Shadra in dieses Reich beschworen. Die Todespirscher und ich werden rasch zu Euch stoßen, sie überwältigen und ihren Körper verwerten. Sprecht mit dem Späher, den ich vorangeschickt habe, wenn das Ritual vollendet ist, und wartet auf mein Eintreffen.", sourceObjective = "Benutzt den Götzen von Shadra am nordwestlichen, südwestlichen und östlichen Tempel in Shadra'Alor.", completion = "Marnal kommt näher...und Shadra noch näher. Bereitet Euch auf Blutvergießen vor.", sourceObjectiveStatus = "unverified-source-field" }
quests[26560] = { id = 26560, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jorgensen", description = "Ich weiß nicht, wo Krakauer oder Danforth sind, aber Jorgensen wurde nordwestlich von hier, in Renders Lager festgehalten. Wir saßen im gleichen, verdreckten Käfig, bevor man mich nach Althers Mühle verlegte.\n\nUm ihn zu befreien, brauchen wir den Schlüssel. Eine eiskalte Hexe aus der Hölle namens Utroka die Schlüsselmeisterin hält ihn fest in den Klauen. Wir müssen sie töten, wenn wir Jorgensens Käfigschlüssel haben wollen. Sie hält sich nördlich von hier in dem Tal auf, das zur Brennenden Steppe führt.\n\nAuf geht's, <Junge/Mädchen>.", sourceObjective = "Besorgt Jorgensens Käfigschlüssel.", progress = "Messner! Verdammt, es tut gut, ein freundliches Gesicht zu sehen. Holt mich hier raus!", completion = "Ich weiß, wo Krakauer und Danforth festgehalten werden. Wir müssen uns beeilen. Die beiden sollen geopfert werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[26561] = { id = 26561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krakauer", description = "Krakauer steht schon auf dem Richtblock! Die Orcs haben einen Hexendoktor der Gurubashi geholt, der ein dunkles Ritual über ihn sprechen soll. Wir müssen den Troll töten und Krakauer befreien!\n\nLos! Er ist in der Höhle dort. Geht nach rechts an der ersten Gabelung.", sourceObjective = "Tötet Ritualist Tarak.", completion = "Wa... Wo bin ich? Was ist passiert? Messner? Jorgensen?\n\nOH MEIN GOTT! Wir müssen Danforth holen! Hoffentlich ist es noch nicht zu spät!", sourceObjectiveStatus = "unverified-source-field" }
quests[26562] = { id = 26562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Nachzügler... Danforth", description = "Danforth wird auf der anderen Seite der Höhle gefoltert. Wer weiß, in welchem Zustand er mittlerweile ist! Wir müssen zu ihm und ihn retten!\n\nOberanführer Barbarius trägt den Schlüssel zu dem Hebel, der Danforth oben hält, bei sich. Wenn wir zusammen arbeiten, können wir Barbarius, dieses Schwein, töten. Wenn Barbarius tot ist, holen wir Danforth mit seinem Schlüssel herunter und hauen ab!\n\nBereit?", sourceObjective = "Tötet Oberanführer Barbarius und bergt den Hebelschlüssel des Schwarzfelsklans. Befreit Danforth mit dem Hebelschlüssel des Schwarzfelsklans.", progress = "Sieh mal einer an! Die ganze Truppe ist hier... abgesehen von Keeshan.", completion = "Worauf habt ihr Feiglinge denn die ganze Zeit gewartet? Meine Arme wurden schon müde.", sourceObjectiveStatus = "unverified-source-field" }
quests[26563] = { id = 26563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr der Kompanie Bravo", description = "Ich weiß nicht, wer Ihr seid, <Freund/Schwester>, aber Ihr habt Euch den Respekt und die Bewunderung der Kompanie Bravo verdient. Ihr habt unsere Haut gerettet und auch noch eine Bootsladung voller Orcs getötet. Wir werden den Gefallen erwidern.\n\nReist zurück nach Seenhain und meldet Euch bei Oberst Trottmann. Wir werden Johnny finden und die gute Nachricht persönlich überbringen. Wenn die Kompanie Bravo loslegt, haben diese Orcs keine Chance.", sourceObjective = "Meldet Euch bei Oberst Trottmann in Seenhain im Rotkammgebirge.", completion = "<Oberst Trottmann salutiert.>\n\nUnglaubliche Arbeit, {name}. Ihr habt es geschafft, die ganze Kompanie Bravo aus den Klauen der Schwarzfelsorcs zu befreien? Jetzt, da Keeshans Team gerettet ist und seine Habseligkeiten wieder da sind, gibt es für ihn keine Möglichkeit, uns abzuweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26564] = { id = 26564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heimwerker", description = "<Klei sieht Euch verächtlich an und macht ein Geräusch, das klingt, als reibe man zwei Steine aneinander.>\n\nSie haben all unsere Katapulte zerschlagen. Das hier versuche ich zu reparieren, aber bis jetzt ohne Erfolg.\n\nIhr könntet Euch nützlich machen. Reist zur Front und bringt mir alle Ersatzteile, die Ihr findet.\n\nKriegt Ihr das hin, Fleischsack?", sourceObjective = "Besorgt 6 Katapultteile.", progress = "Und? Ich hab nicht den ganzen Tag Zeit.", completion = "Also gut. Vielleicht seid Ihr doch in Ordnung.\n\nSchon gut, schon gut... kriegt Euch wieder ein. Gebt mir etwas Zeit mit diesen Teilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26565] = { id = 26565, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein wütender Fang", description = "Steht Euch der Sinn nach einer Herausforderung, {name}? Gut, das hatte ich gehofft. Der Südstrom führt westlich an Orgrimmar vorbei. Eure Herausforderung schwimmt in seinen mächtigen Wassern.\n\nWir suchen nach einem riesigen, wütenden Hecht. Dieser geschätzte Fisch war früher zahlreich in dieser Gegend vertreten, doch seit der Flut sieht man ihn nur noch selten. Begebt Euch zum Fluss, dann werden wir sehen, wie gut es wirklich um Eure Angelkünste bestellt ist.", sourceObjective = "Fangt einen riesigen wütenden Hecht im Südstrom. Ihr findet den Südstrom vor dem westlichen Tor von Orgrimmar. Kehrt danach ins Tal der Ehre zu Razgar zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[26566] = { id = 26566, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Triumph gnomischer Erfindungsgabe", description = "Wir werden alle Waffen, Erfindungen und Soldaten brauchen, die wir kriegen können, wenn wir Razlo Ritzelstoß und seine Anhänger besiegen wollen.\n\nIm Nordosten werdet Ihr Ingenieur Schleiffunke finden, der einer neuen Generation brillanter Gnomendenker angehört. Stellt Euch vor: er hatte seit mehr als drei Prototypen keine Explosion mehr!\n\nGenug angegeben. Ingenieur Schleiffunke arbeitet an einem Bot, mit dessen Hilfe er den Toxischen Flugplatz reinigen will. Stellt Euch ihm vor. Vielleicht könnt Ihr ihm bei den Tests des Bots helfen.", sourceObjective = "Sprecht mit Ingenieur Schleiffunke in Neu-Tüftlerstadt.", completion = "Sogar Mekkadrill selbst hat also von meinem kleinen Projekt gehört? Wunderbar! Mein neuester Prototyp ist zwar fast fertig, aber Ihr könntet mir noch bei der Suche nach den letzten Teilen helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26567] = { id = 26567, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "John J. Keeshan", description = "Habt Ihr mal von John Keeshan gehört, {name}? Ich war in allen drei großen Kriegen sein Kommandant. Ich sage Euch, dieser Mann hat mehr Orcs getötet als jeder andere. Wenn jemand die Invasion der Schwarzfelsorcs aufhalten kann, dann JOHN J. KEESHAN. Wir müssen ihn dazu bringen, uns zu helfen. Wenn die gewaltige Schwarzfelsarmee auf ihrem Weg nach Elwynn durch Seenhain marschiert, wird sie das ganze Land in Schutt und Asche legen.\n\nIch habe gehört, dass er dem geheimen Kampfclub angehört, der sich im Gasthaus von Seenhain trifft. Findet ihn und erzählt ihm alles, was Ihr wisst.", sourceObjective = "Bemüht Euch um die Hilfe von John J. Keeshan im Gasthaus Seenhain in Seenhain.", completion = "Euch helfen? Diesen Leuten helfen? Diese Leute, die mich eher anspucken als anlächeln würden?", sourceObjectiveStatus = "unverified-source-field" }
quests[26568] = { id = 26568, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Is' nich' mein Krieg", description = "Sie verlangten von mir, in diesen Kriegen zu kämpfen. Ich habe sie nicht darum gebeten! Ich tat, was ich tun musste, um zu siegen. Irgendwann wurde ich von diesen schmutzigen, mit Unrat beschmierten, verlausten Orcs gefangen genommen. Fünf lange Jahre benutzten sie mich als ihre Toilette. Schließlich brach ich aus, kehrte in meine Heimatstadt zurück... und was geschah? Die Leute spuckten mich an, beschimpften mich und nannten mich einen Babyorcmörder und andere üble Verleumdungen.\n\nNein, ich werde Euch wohl eher nicht helfen. Geht zurück zu Trottmann und sagt ihm, das sei nicht mein Krieg.", sourceObjective = "Kehrt zu Oberst Trottman zurück.", completion = "<Trottmann seufzt.>\n\nIch werde ihn noch nicht aufgeben, {name} - und ich werde das Rotkammgebirge nicht aufgeben. Wir müssen ihn aufmuntern... Weckt das schlafende Monster in ihm auf!", sourceObjectiveStatus = "unverified-source-field" }
quests[26569] = { id = 26569, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermessungsausrüstung", description = "Ah, meine Rettung! Ich habe gehört, dass Ihr Euch auf einer Mission zur Rettung von Seenhain ... und meiner Brücke... befindet. Hab viel zu lang daran gearbeitet, um zuzusehen, wie das verdammte Ding von plündernden Orcungeheuern zerstört wird!\n\nSolltet Ihr auf dem Weg nach Norden, zu Renders Lager, sein, könntet Ihr mir einen Gefallen erweisen. Besorgt ein paar Teleskope von den Fährtenlesern des Schwarzfels. Könnte ich gut für meine neue Vermessungsausrüstung gebrauchen.", sourceObjective = "Beschafft 5 Teleskope des Schwarzfelsklans.", progress = "Habt Ihr die Teleskope bekommen?", completion = "Großartige Arbeit, {name}! Bei meinem nächsten Projekt, der SUPERBRÜCKE von Seenhain, die sich über den gesamten Immerruhsee erstrecken soll, werden sie mir gute Dienste erweisen. Die Brücke sollte in rund 20 Jahren fertig sein. Plus minus einem Jahrzehnt, oder zwei.", sourceObjectiveStatus = "unverified-source-field" }
quests[26570] = { id = 26570, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renders Armee", description = "Hey, auf dem Weg nach Norden? Hättet Ihr Lust, Euren eigenen kleinen Krieg gegen diese Schwarzfelsmonster anzuzetteln? Was sagt Ihr dazu, {name}?\n\nTötet jeden Schwarzfelsorc, der Euch rund um Althers Mühle oder Renders Lager begegnet. Tötet, bis sich Eure Haut von ihren Blutspritzern rot färbt und kommt dann zu mir zurück. Ich werde Euch großzügig belohnen.\n\nDas wird die Invasion des Schwarzfelsklans wahrscheinlich nicht aufhalten, aber es wird ihre Pläne empfindlich stören.", sourceObjective = "Tötet 25 beliebige Schwarzfelsorcs in Althers Mühle oder Renders Lager.", completion = "Ihr habt uns einen Tag, vielleicht sogar zwei verschafft. Gute Arbeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26571] = { id = 26571, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegswaffen", description = "Das, worum ich Euch bitten möchte, wird nicht leicht zu erfüllen sein, {name}. Keeshan hat alles in diesem Orcgefängnis zurückgelassen, und damit meine ich nicht nur seine Seele und seinen Lebenswillen.\n\nWenn Johnny für uns kämpfen soll, müssen wir seinen wertvollsten Besitz bergen. Die Orcs haben Keeshans Bogen und sein Überlebensmesser an sich gebracht.\n\nReist nach Althers Mühle östlich von hier und sucht nach den beiden Orcleutnants Murdunk und Homurk. Sie haben Keeshans Ausrüstung. Holt sie Euch.\n\nIch bleibe mit dem Gnomcorder in Verbindung.", sourceObjective = "Bergt Keeshans Bogen und Keeshans Überlebensmesser.", sourceObjectiveStatus = "unverified-source-field" }
quests[26572] = { id = 26572, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elektrisierender Einfall", description = "Wisst Ihr, was ein goldener Steinfisch ist, {name}? Diese Fische kann man nicht mit normalen Mitteln fangen. Ihre Kiefer sind so stark, dass sie Angelhaken und Köder einfach durchbeißen.\n\nMan findet sie im Donnergrat südlich von Orgrimmar. Früher war der Grat voller Donnerechsen, aber sie sind alle bei der Flut ertrunken.\n\nNehmt mein Messer, schwimmt dort hinein und schneidet ihre Schwänze ab. Der Stromschlag des Schwanzes sollte die Steinfische töten.", sourceObjective = "Schneidet im Donnergrat, südlich von Orgrimmar, den Schwanz einer ertrunkenen Donnerechse mit Razgars Filetiermesser ab. Benutzt den Schwanz nahe eines goldenen Steinfischs, um ihn damit zu töten. Kehrt danach zu Razgar ins Tal der Ehre zurück.", progress = "Wie ist es da unten gelaufen? Hattet Ihr Glück mit den Schwänzen und den Steinfischen?", completion = "Gut gemacht, {name}! Ganz ehrlich, goldene Steinfische bekommt man nur schwer. Das ist ein besonderer Leckerbissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26573] = { id = 26573, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Er muss mit ganzem Herzen dabei sein", description = "<Der Gnomcorder klickt.>\n\nSeine Ausrüstung allein reicht nicht, {name}. Er muss diese Schlacht von ganzem Herzen wollen. Um das zu erreichen, benötigen wir Gegenstände von sentimentalem Wert. Die Schwarzfelsorcs von Renders Lager im Norden besitzen zwei solcher Gegenstände, die Keeshan gehören.\n\nBegebt Euch dorthin und durchsucht ihre Kisten nach Keeshans Stirnband und einem Jadeamulett, das ihm seine Frau - die bei einer Invasion der Schwarzfelsorcs brutal ermordet wurde - hinterlassen hat.\n\nBringt sie zu mir, solltet Ihr fündig werden.", sourceObjective = "Findet Keeshans rotes Stirnband und Keeshans Jadeamulett.", progress = "Habt Ihr Stirnband und Amulett gefunden?", completion = "Ich hoffe, dass er dank dieser Gegenstände und seiner geretteten Kameraden seine Meinung ändert. Ohne Keeshan sind wir aufgeschmissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26574] = { id = 26574, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adellas geheimes Lager", description = "Lady Shandris hat Euch bereits darum gebeten, uns noch mehr zu helfen.\n\nAdella hat sich in Richtung Osten aufgemacht, zu den Waldpfotengnollen, und ein kleines Lager südlich von Camp Mojache errichtet. Wenn Ihr Lady Shandris und der Allianz weiter dienen wollt, so solltet Ihr Euch bei Adella melden.\n\nBegebt Euch nicht zu nahe an Camp Mojache heran... die Horde wird mit einem Angriff nicht zögern. Haltet Euch südlich und haltet nach unseren Bannern Ausschau.", sourceObjective = "Meldet Euch bei Adella im Schattengeäst in Feralas.", completion = "Willkommen im Schattengeäst, {name}. Lady Shandris hat Euer Kommen angekündigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26575] = { id = 26575, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steinalt", description = "Ich muss Euch um einen weiteren Gefallen bitten, Fleischling.\n\nEs dreht sich um einen Basilisken, der viel größer und älter als die anderen ist. Normalerweise fürchten wir sie nicht, doch dieser Basilisk ist mittlerweile so stark, dass er sogar einige meiner Söhne versteinert hat. Das dürfen wir nicht hinnehmen.\n\nSucht Gorgonit im Osten und erschlagt ihn. Er hat bereits viel länger gelebt als nötig.", sourceObjective = "Tötet Gorgonit.", completion = "Danke, {race}. Ihr habt alles getan, worum ich Euch zu bitten wagte. Ich werde der Steinmutter berichten, welch guten Eindruck Ihr bei mir hinterlassen habt.\n\nMöge der Stein unter Euren Füßen Euch bei der Suche nach der Weltensäule stets stützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26576] = { id = 26576, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhige Hand", description = "Im Norden, ganz in der Nähe, werdet Ihr Terrath den Beständigen finden. Er hat die Aufgabe angenommen, die Steindrachen zurückzugewinnen. Alle paar hundert Jahre muss das wiederholt werden... die Steindrachen sind launisch und beugen sich nur der Stärke.\n\nTerrath ist ausgeglichen und vernünftig, doch seine Ziele werden schwer zu erreichen sein. Geht zu ihm. Appelliert an die ausgeglichenere Seite der Steinmutter.", sourceObjective = "Sprecht mit Terrath dem Beständigen vor dem Bleichen Hort.", completion = "Seid gegrüßt, {race}. Man hat mir Euer Kommen bereits angekündigt. Wenn Ihr mir helfen möchtet, dann könnte ich vielleicht auch Euch behilflich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[26577] = { id = 26577, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felserhebung", description = "Auf der Rubinspanne im Osten werdet Ihr Gorsik finden. Er steht für den instabilen und gewalttätigen Teil des Naturells unseres Volkes. Er ist weder freundlich noch offenherzig, aber seine Stimme hat Gewicht.\n\nBeweist Euch Gorsik, dann wird es Euch leichter fallen, Euch auch der Steinmutter zu beweisen.", sourceObjective = "Sprecht mit Gorsik dem Tosenden auf der Rubinspanne.", completion = "Ihr seid Diamants Auserwählter.\n\nSo klein. So zerbrechlich.\n\nIst Euch bewusst, dass auf der Grundlage Eurer Handlungen der gesamte \"Irdene Ring\" beurteilt wird? Seid Ihr sicher, dass Ihr wirklich stellvertretend für so viele handeln wollt?\n\nIhr seid ein Narr. Ein zuversichtlicher Narr. Wir werden sehen, ob Ihr auch ein fähiger Narr seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[26578] = { id = 26578, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdammnispilze", description = "Die Spalte, die in Eure Welt führt, hat unsere Heimat vergiftet. Korrumpiert. Verschmutzt.\n\nDiese Spanne schwärt und wächst. Unter dem ganzen Dreck kann man die Reinheit des Steins kaum noch erkennen.\n\nWenn Ihr uns zur Seite stehen wollt, dann beseitigt diese Überwucherung. Sucht nach hell leuchtenden Pilzen, die schneller wachsen als die anderen. Das sind die schlimmsten Übeltäter.", sourceObjective = "Zerstört 10 Verdammnispilze.", completion = "Ihr habt Euch an Diamant gewandt. Er ist geduldig. Vertrauensselig. Vielleicht zu sehr. Ihr müsst mir viel beweisen, wenn Ihr meine Gunst erlangen wollt, {race}.\n\nAber den Anfang habt Ihr immerhin gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26579] = { id = 26579, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verweichlicht", description = "Die Fungusungetüme um uns herum sind einer Schwäche erlegen, die der Eurer Art sehr gleicht. Ihre Haut ist weich geworden. Sie gehören nicht mehr zum Stein.\n\nTötet sie. Wir wollen nicht, dass diese Krankheit sich ausbreitet.", sourceObjective = "Tötet 8 Fungusungetüme.", completion = "Ihr tragt ein gewisses Maß an Macht in Euch. Ich kann diese Stärke respektieren, besonders bei Eurer Art.\n\nMeine Bedenken sind noch nicht aus dem Weg geräumt. Weder in Bezug auf das übermäßige Wachstum noch auf Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[26580] = { id = 26580, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vertraute Eindringlinge", description = "Fleischling. Einige Eurer Art huschen über die Felsen. Zu scheu, um näher zu kommen, zu schnell, um sie zu zerschmettern.\n\nWenn Ihr meine Gunst erlangen wollt, kümmert Euch um sie. Ich bin diese Spielchen leid.", sourceObjective = "Sprecht mit den \"Fleischlingeindringlingen\" auf der Rubinspanne.", completion = "Schön Euch wiederzusehen, Bruder. Wie ich sehe, tragen Eure Bemühungen Früchte. Die Steinlords scheinen Euch zumindest ein wenig zu vertrauen.\n\nWir sind hier, um zu helfen. Vielleicht können wir gemeinsam herausfinden, was diesen plötzlichen Wuchs verursacht. Ich befürchte nämlich, dass Euer Riesenfreund seine Wut auf das falsche Ziel richtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[26581] = { id = 26581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Kopf in den Wolken", description = "Ich bin zwar kein Druide, aber ein paar dieser Pilze sehen nicht so aus, als seien sie natürlich gewachsen. Ich weiß, dass unser Freund, der Steinlord da hinten, Azeroth die Schuld an diesem Befall geben will, aber ich glaube, die Ursachen sind hausgemacht.\n\nIm Nordosten sah ich einige Wolken aus rotem Nebel am Wasser, die anscheinend neue Wucherungen nach sich zogen. Nehmt einen meiner Windteufel und besorgt mir eine Probe aus diesen Wolken. Es kann sein, dass Ihr in Bodennähe bleiben müsst, um sie zu sehen.", sourceObjective = "Bringt Lorvarius' Windteufel zu den Wolken aus rotem Nebel in der Rubinspanne und bringt eine Probe davon mit.", completion = "Ihr habt zugelassen, dass der Nebel Eure Haut berührt? Ich hoffe, es gab keine unangenehmen Wirkungen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26582] = { id = 26582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unnatürliche Ursachen", description = "Der Ursprung ist definitiv magisch. Nicht einmal druidisch. Ich habe einen der Steintroggs im Norden unter Verdacht.\n\nGeht zu Gorsik und weist ihn auf sie hin. Hoffentlich gewinnt Ihr dadurch seine Unterstützung.", sourceObjective = "Sprecht mit Gorsik dem Tosenden in der Rubinspanne.", completion = "Die Steintroggs? Und ich soll Euren Worten Glauben schenken?\n\nIch mag Verlok ohnehin nicht. Ein Verdacht reicht vollkommen aus, um sie zu Staub zu zermahlen. Wir werden sehen, ob Ihr die Wahrheit sprecht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26583] = { id = 26583, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zorn der Fungumanten", description = "Ihr Anführer versteckt sich in seinem Loch dort vorn. Er hat diese Plage über die Rubinspanne gebracht.\n\nEr muss sterben.\n\nEine Eurer Begleiterinnen vom Irdenen Ring befindet sich bereits im Inneren. Ihr solltet mit ihr sprechen.", sourceObjective = "Sprecht mit Erdheilerin Norsala, tötet dann Fungumant Glop.", progress = "Ich passe nicht hinein. Unsere Elementare sind der Aufgabe nicht gewachsen.\n\nIhr müsst sie erledigen.", completion = "Gut gemacht, {race}.\n\nGorsik wird von Eurer Tat erfahren. Therazane wird von Eurer Tat erfahren.\n\nIhr seid ganz schön teuflisch für Eure Größe... und Eure Weichheit.", sourceObjectiveStatus = "unverified-source-field" }
quests[26584] = { id = 26584, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschüttelt und gerührt", description = "Ich habe meine Brüder ausgesandt. Sie werden Verlok von oben angreifen. Die Verlok werden sich wie immer auf ihren Felsvorsprüngen versammeln, um unserem Zorn zu entgehen. Sobald sie das tun, werden wir dafür sorgen, dass die Erde bebt, bis sie zu Boden gehen.\n\nDann könnt Ihr Euch nützlich machen. Sorgt dafür, dass sie sich nicht mehr erheben, wenn sie zwischen meinen Brüdern am Boden liegen.", sourceObjective = "Tötet 8 Säulenbrecher von Verlok im unteren Teil der Wacht Verlok.", completion = "Gut gemacht, Fleischling. Ihr habt meine Brüder gut ergänzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26585] = { id = 26585, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerstörung der Verderbnis", description = "Wenn dieses abscheuliche Wachstum wirklich von den Einwohnern Verloks stammt, dann bewahren sie ihre Vorräte sicher im Dorf im Norden auf. Bringt sie mir, damit ich Eure Behauptung überprüfen kann.", sourceObjective = "Besorgt 8 Taschen des Wunderwachstumsmittels von Verlok.", progress = "Ich warte auf Euren Beweis, {race}…", completion = "Also sind Eure Worte wahr. Ihr habt meinen Dank, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26586] = { id = 26586, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche nach der Kompanie Bravo", description = "Wenn Ihr und Keeshan Seenhain verteidigen wollt, müssen wir sein altes Bataillon finden. Das Letzte, was ich hörte, war, dass Messner, Jorgensen, Krakauer und Danforth von den Schwarzfelsorcs gefangen genommen wurden. Ich weiß zwar nicht, wo sie sein könnten oder ob sie noch leben, aber ich wäre ein verdammter Narr, wenn ich Euch nicht bitten würde, sie zu suchen.\n\nSucht in Althers Mühle östlich von hier nach Hinweisen.", sourceObjective = "Sucht in Althers Mühle nach einem Mitglied der Kompanie Bravo.", completion = "Keeshan? Ihr meint, JOHNNY LEBT? Ihr könnt Euren süßen Allerwertesten wetten, dass ich helfen werde, aber erst müsst Ihr mich aus diesem verdammten Käfig befreien.", sourceObjectiveStatus = "unverified-source-field" }
quests[26587] = { id = 26587, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schlüssel zum Erfolg", description = "Der Schlüssel zu diesem Käfig befindet sich in einem Beutel nördlich von diesem Ort im Höhlenbau der Worgen. Das Problem ist, dass dieser Beutel sicher auf einem Baumstumpf inmitten blutdürstiger, mordgieriger Worgs liegt. Holt den Schlüssel, ohne die schlafenden Worgs aufzuwecken.\n\nIhr habt nur einen Versuch. Reist zum Höhlenbau der Worgs und findet einen Weg zur Mitte. Seid vorsichtig und nehmt Euch vor dem Worghauptmann des Schwarzfels in Acht. Holt den Schlüssel und kehrt zu mir zurück.\n\nSolltet Ihr einen Begleiter haben, wäre es besser, ihn zurückzulassen!", sourceObjective = "Besorgt Messners Käfigschlüssel.", progress = "Habt Ihr den Käfigschlüssel?", completion = "RACHE!", sourceObjectiveStatus = "unverified-source-field" }
quests[26588] = { id = 26588, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein wütender Fang", description = "Steht Euch der Sinn nach einer Herausforderung, {name}? Gut, das hatte ich gehofft. Der Südstrom führt westlich an Orgrimmar vorbei. Eure Herausforderung schwimmt in seinen wilden Wassern.\n\nWir suchen nach einem riesigen, wütenden Hecht. Dieser geschätzte Fisch war früher zahlreich in dieser Gegend vertreten, doch seit der Flut sieht man die großen nur noch selten. Begebt Euch zum Fluss, dann werden wir sehen, wie gut es wirklich um Eure Angelkünste bestellt ist.", sourceObjective = "Fangt einen riesigen wütenden Hecht im Südstrom. Ihr findet den Südstrom vor dem westlichen Tor von Orgrimmar. Kehrt danach zu Razgar ins Tal der Ehre zurück.", progress = "Konntet Ihr einen riesigen Hecht fangen?", completion = "{name}, Ihr habt einen! Einen so starken, schönen Fisch bekommt man nur selten zu Gesicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26589] = { id = 26589, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wildnis von Feralas", description = "Ihr habt heldenhaften Mut, uns dabei helfen zu wollen, diese Länder zu beschützen. Wenn Ihr der Wildnis noch mehr helfen wollt, so werden sich noch andere finden, die Eure Hilfe gebrauchen können.\n\nDer üppige Wald von Feralas liegt südlich von hier. Sucht in den Schatten der mächtigen Zwillingskolosse Konu Runentotem auf. Er hat Hinweise auf eine beunruhigende Krankheit gefunden.\n\nFolgt der Straße nach Westen, vorbei an den Zwillingskolossen, bis Ihr Camp Ataya erreicht. Geht in Frieden, {name}, und mit der Erdenmutter.", sourceObjective = "Reist nach Feralas und sprecht mit Konu Runentotem in Camp Ataya.", completion = "Friede sei mit Euch. Ich wünschte, wir würden uns unter freudigeren Umständen treffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26590] = { id = 26590, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das heilige Wasser der Klarheit", description = "Hey, hört mich an. Ihr seht nicht wie ein gewöhnlicher Tourist aus, und ich stecke ein wenig in der Klemme. Mein Cousin im Norden hat mir dieses seltsame Artefakt geschickt und ich brauche Eure Hilfe, um es zu... äh... identifizieren.\n\nAls erstes müsst Ihr mir das heilige Wasser der Klarheit besorgen. Es heißt, dass jeder, der aus dieser Quelle trinkt, eine Vision der Klarheit erhält. \n\nKlingt recht vielversprechend, oder?\n\nSchöpft es aus dem Nek'maiquellbrunnen am Gipfel des Nagalagers. Viel Glück!", sourceObjective = "Schöpft das heilige Wasser der Klarheit aus dem Nek'maniquellbrunnen Wellspring am Kap des Schlingendorntals.", progress = "<Flem richtet seine Ohren auf, als Ihr Euch nähert.>\n\nDas heilige Wasser der Klarheit? Ist es hier!?", completion = "<Der {race} stürzt das Wasser in einem Schluck hinunter.>\n\nAhh... wisst Ihr, wie schwer es ist, im Schlingendorntal frisches Wasser zu bekommen? Kein Wunder, dass die Naga ihren Schrein so streng bewachen!\n\nOh, stimmt ja... das Artefakt. Klarheit...\n\nMir ist alles klar!", sourceObjectiveStatus = "unverified-source-field" }
quests[26591] = { id = 26591, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettung an vorderster Front", description = "Ihr scheint schnell zu Fuß zu sein, {race}. Ich brauche jemanden, der sich in das Chaos der Front stürzt und unsere Verletzten versorgt.\n\nNehmt meine Rettungsausrüstung. Sie ist ganz einfach zu verwenden.\n\nHeilt sie, bevor die Steintroggs sie endgültig erwischen.", sourceObjective = "Versorgt 10 verletzte Irdene.", completion = "Falls Ihr Eurer Karriere als {class} je überdrüssig seid, sucht mich auf. Ihr scheint mit diesen fleischigen Händen ziemlich geschickt zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[26592] = { id = 26592, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diffraktorisches Chromaskop", description = "Ich benötige Analysewerkzeuge, um dieses Artefakt zu identifizieren. Ein diffractorisches Chromaskop sollte ausreichen, glaube ich.\n\nIch habe das Mithrilgehäuse bereits, was seltsamerweise am schwierigsten zu finden ist. Wir brauchen nur noch zwei andere Teile, einen Rubin und einen Saphir.\n\nIn der Nähe lagern Piraten, unmittelbar im Süden von hier und etwas weiter entfernt im Osten. Piraten lieben Schätze... seht doch mal nach, ob Ihr ein paar Edelsteine für mich findet.", sourceObjective = "Besorgt einen Blutsegelrubin und einen Blutsegelsaphir.", progress = "<Flems Augen funkeln.>\n\nSind das etwa Edelsteine?", completion = "<Flem wiegt die Edelsteine in seinen Händen und nickt zufrieden.>\n\nJa, die reichen. Ich beginne die Analyse...\n\n<Der Goblin schlägt die Edelsteine eine Weile gegeneinander, dann sieht er zu Euch empor.>\n\nOh, Ihr seid immer noch hier? Ihr haltet mich doch nicht für einen Betrüger oder so?", sourceObjectiveStatus = "unverified-source-field" }
quests[26593] = { id = 26593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zitterhand Angst einjagen", description = "Wenn ich etwas nicht leiden kann, dann sind das Leute, die ihre Spielschulden nicht bezahlen! Und es gibt 'ne Menge Leute, die mir was schulden. Ob Ihr mir wohl beim Eintreiben helfen könnt?\n\nDa ist zuerst mal \"Zitterhand\" Phillipe unten bei den Docks. Er schuldet mir eine Menge nach dem Spiel letzte Woche und ich will mein Geld jetzt! Aber um da dranzukommen, müssen wir ihm gehörig Angst einjagen.\n\nVerlasst die Stadt und jagt alte Nebeltalgorillas. Sucht Euch ein paar nette Innereien heraus und bringt sie zu Zitterhand. Sagt ihm ja nicht, dass sie von einem Tier stammen, er soll ruhig das Schlimmste annehmen.", sourceObjective = "Erhaltet 5 Nebeltalinnereien von alten Nebeltalgorillas.", progress = "He! Den Blick, den Ihr mir da zuwerft, mag ich gar nicht, Sire.", completion = "Igitt! Wo habt Ihr das denn her? Nein, sagt es mir lieber nicht. Ich will es gar nicht wissen!\n\nWer hat Euch geschickt? Seewolf?", sourceObjectiveStatus = "unverified-source-field" }
quests[26594] = { id = 26594, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu MacKinley", description = "Hier, nehmt diesen Beutel und gebt ihn Seewolf. Und sagt ihm, dass ich alles zurückzahlen wollte! Ich schwöre es!!\n\nIch war nur ein bisschen betrunken und habe mich verlaufen... Ihr wisst ja, wie es so geht. Er wird es verstehen - Ihr müsst nicht erst grob werden!", sourceObjective = "Bringt Zitterhands Bezahlung zu \"Seewolf\" MacKinley.", progress = "Da seid Ihr ja, {name}. Habt Ihr Zitterhands Bezahlung?", completion = "Heh heh, gut gemacht! Wie stark hat Zitterhand denn gezittert, als Ihr ihm die Eingeweide gezeigt habt?\n\nHah! Man kann ihn so leicht lesen, wenn man mit ihm Karten spielt, da muss man einfach gewinnen!\n\nMeinen Dank für Eure Hilfe, {name}. Jetzt sollt Ihr bezahlt werden...", sourceObjectiveStatus = "unverified-source-field" }
quests[26595] = { id = 26595, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rien ne va plus - Nichts geht mehr", description = "Es gibt drei Phasen bei der Schuldeneintreibung: höflich fragen, energisch fragen und etwas, das ich als \"Phase Drei\" bezeichne.\n\nLeider bin ich alter Hund zu Phase Drei nicht mehr in der Lage. Deshalb muss ich so viele Kumpane, Handlanger, Angeber, Schläger und edle Abenteurer wie Euch einstellen!\n\nJans Fitzpünktchen, Ephram Mondsturz and Maury Wilkins verstecken sich an der östlichen Küste. Ihr solltet alle drei problemlos bei einem Ausflug abklappern können... Bringt mir ihren wertvollsten Besitz.", sourceObjective = "Besorgt Maurys Klumpfuß, Fitzpünktchens Drehmomentschlüssel mit Ratsche und Ephrams juwelenbesetzten Spiegel.", progress = "{name}, habt Ihr die Schuldner gefunden?", completion = "Großartig! Die werden gutes Geld bringen, vor allem das, was sich in Maurys Fuß befindet! Vielen Dank, {name}!\n\nIch hoffe, die drei haben ihre Lektion gelernt. Man soll nie etwas verwetten, was man nicht aufgeben kann.\n\nVielleicht ist es für sie zu spät, aber... sie sollten gut darüber nachdenken, mit wem sie spielen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26596] = { id = 26596, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf von Kalimdor", description = "Ich wurde von den guten Leuten von Theramore geschickt, um loyale Mitglieder der Allianz zu finden, die Lady Jaina mit einigen Problemen in den Düstermarschen aushelfen kann.\n\nIhr wart doch nicht wirklich hier, um für die Goblins zu arbeiten, oder?\n\nDer Weg in die Düstermarschen führt durch Ratschet. Sprecht dort mit Gazlowe. Er wird euch von dort aus die richtige Richtung zeigen.\n\nIgitt... ich glaube, ich bin auf einen Fisch getreten! Und er hat gezappelt!", sourceObjective = "Nehmt das Schiff von Beutebucht nach Ratschet und sprecht dort mit Gazlowe.", completion = "Ja? Was braucht Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[26597] = { id = 26597, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlingendornfieber", description = "Krank... so... furchtbar k-k-krank... \n\n... habe mich mit Schlingendornfieber angesteckt... \n\n...um genau zu sein, SchlingendornKAPfieber...\n\n...tödliches V-v-virus... \n\n... einziges Heilmittel... wäre... wäre es... das Herz von M-m-m-mokk dem Wilden zu essen... schwer zu fassendes, weißes Wildtier... \n\n... Hexendoktor Unbagwa... Einziger, der es b-b-beschwören kann...\n\n... sucht Unbagwa... versteckte Höhle am südlichen Kap...\n\n... schnell... sterbe... sterbe...", sourceObjective = "Sucht Hexendoktor Unbagwa und lasst ihn Mokk den Wilden beschwören. Bringt das Herz von Mokk zu Fin Fizrackett.", progress = "... Mutter?\n\n... so kalt... \n\n... ich fahre hinab in den Wirbelnden Nether... h-h-h-halt mich fest, Mutter...", completion = "... fühle die Kraft zurückkehren... \n\nWo bin ich? Beutebucht? Ach du meine Güte! Ich hatte einen seltsamen Traum... \n\n... die Schwäche hat mich nicht vollständig verlassen...", sourceObjectiveStatus = "unverified-source-field" }
quests[26598] = { id = 26598, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Herz von Mokk", progress = "Hexendoktor Unbagwa weiß, was Mokk der Wilde mag. Ja, ja!\n\nIch sprechen mit Geistern und mach er kommen, tue ich.\n\nAber andere Gorillabiester mögen Geistersprechen auch. Du beschützt Hexendoktor Unbagwa und ich mach ihn kommen zu dir.\n\nHexendoktor Unbagwa will zuerst etwas. Du bringst Gorillafangzahn und ich lasse Geister reden!", completion = "Hexendoktor Unbagwa mag Gorillafangzähne! Für dich ich reden mit Geister. Lasse Mokk den Wilden kommen.\n\nDu beschützt Hexendoktor Unbagwa vor anderen Gorillabiestern, sonst kein Mokk für dich!" }
quests[26599] = { id = 26599, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Truhe des Kapitäns", description = "Früher hab ich ein Schiff von hier bis ganz nach Ratschet, in Kalimdor gesegelt. Ich war ein erfolgreicher Kapitän mit einem einwandfreien Ruf.\n\nBis...\n\nDiese verfluchten Meeresriesen mich ruinierten! Sie haben mein Schiff zerschmettert, meine Crew umgebracht und mich in ein Rettungsboot nach Beutebucht gesteckt. Ich werde nicht ruhen, bis ihre Leichen auf dem Meeresboden verstreut liegen!\n\n Einer dieser Riesen, Gorlash, hat meine Kapitänstruhe gestohlen. Ich habe gehört, dass Gorlash an der Küste östlich von hier sein Unwesen treibt. Findet ihn und bringt mir meine Truhe zurück! Tut das, und Ihr habt Euch die Dankbarkeit eines Kapitäns verdient!", sourceObjective = "Erhaltet Smotts' Truhe von Gorlash am Schlingendornkap.", progress = "Ahoi, {name}! Habt Ihr Gorlash finden können? Die Truhe war mein Lieblingsstück und sie hatte ein Geheimfach, mit meinen größten Schätzen.", completion = "Ihr habt sie gefunden! Das ist ein wunderbarer Tag für den alten Hecklebury! Dass ich meine Truhe wiederbekommen habe, beruhigt mich ein wenig.\n\nAber meine Rache ist noch nicht vollständig...", sourceObjectiveStatus = "unverified-source-field" }
quests[26600] = { id = 26600, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein riesiges Bankett", description = "Der nächste Riese auf meiner Liste nennt sich Negolash. Ich sehe noch vor mir, wie er aus der Gischt sprang und den armen Poopdeck-Paul aus dem Krähennest riss.\n\nVerschlang ihn in einem Bissen... Auf dem Weg nach unten brach er noch meinen Kreuzmast in zwei Teile.\n\nKeines meiner Besatzungsmitglieder hat einen so schrecklichen Tod verdient. Also werden wir Negolashs Appetit gegen ihn verwenden. Kelsey Yance verkauft Euch bestimmt etwas Fleisch, und Klein Whiskeys Schnaps reicht aus, um einen... nun, einen Meeresriesen umzuhauen. Ihr werdet beide in der Stadt finden.", sourceObjective = "Kauft eine Kiste mit Fleisch der Güteklasse E von Kelsey Yance und eine Kiste mit Pupellyverbos Portwein von Klein Whiskey.", progress = "Wir werden viel Essen brauchen, {name}. Unser Ziel ist Quantität, nicht Qualität.", completion = "Das war doch nicht teuer, oder? Hier, nehmt ein paar Münzen als Entschädigung.\n\nUnd jetzt legen wir mit meiner Rache los, einverstanden?", sourceObjectiveStatus = "unverified-source-field" }
quests[26601] = { id = 26601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mok'rash der Spalter", description = "Mok'rash der Spalter ist der letzte Riese. Und der größte, wenn ich mich recht entsinne. Größer als eine Welle im Orkan, mit einem Bart wie ein Tangwald und einem Hammer mächtig wie eine Eiche.\n\nEr verhöhnt mich von der Janeirospitze, der Insel kurz vor diesem Pier. Nur wegen ihm sitze ich immer noch hier fest und friste mein Dasein als Landratte.\n\nWenn Ihr schwimmen könnt, dann macht Euch auf den Weg zur Janeirospitze und tötet Mok'rash.\n\nSeid vorsichtig, {name}. Mok'rash wird sich nicht so leicht geschlagen geben wie seine Brüder.", sourceObjective = "Tötet Mok'rash den Spalter auf der Janeirospitze.", completion = "Mo'krash... Negolash... Gorlash... sie sind alle tot.\n\nJetzt habe ich wohl keine Entschuldigung mehr. Ich kann auf die weiten Meere zurückkehren und wieder plündern und stehlen! Und das alles dank Euch.\n\nJetzt brauche ich nur noch ein Schiff....", sourceObjectiveStatus = "unverified-source-field" }
quests[26602] = { id = 26602, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riesenportionen erwünscht", description = "Nehmt das Essen und legt es in unser altes Rettungsboot südöstlich von hier an der Küste. Wenn Negolash das ganze Essen riecht, wird er angerannt kommen!\n\nUnd dann erwartet ihn bereits <ein beherzter/eine beherzte> {class}, <der/die> seinen Kadaver zurück in die salzige Tiefe schleudern wird.", sourceObjective = "Legt die Riesenkiste Riesenessen in Captain Smotts'Rettungsboot. Beschwört Negolash damit und tötet ihn.", completion = "Ich kann mein Glück kaum fassen, {name}! Mein Glück hat sich zum Besseren gewendet, seit ich Euch getroffen habe, soviel ist sicher!\n\nSollte ich ein neues Schiff bekommen und solltet Ihr je auf See gehen wollen, dann werdet Ihr mein Ehrengast sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[26603] = { id = 26603, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flaschenpost", description = "In der Flasche findet Ihr eine Notiz, auf der Folgendes, in recht guter Handschrift, steht:\n\n<An alle, die mir helfen können:>\n\n<Bitte, ich benötige dringend Hilfe. Eine große Bestie hält mich auf einer Insel in den Südlichen Meeren gefangen.>\n\n<Die Sternbilder am Nachthimmel sind mir nicht vertraut und von Dschungelbäumen verdeckt, aber an klaren Tagen kann ich die Küstenlinie im Nordwesten erkennen und im Südwesten etwas, das große Segelschiffe sein könnten.>\n\n<Ich flehe Euch an, mein möglicher Retter, bitte helft mir.>", sourceObjective = "Sucht den Schreiber der Nachricht auf der Insel Jaguero am Schlingendornkap.", completion = "Seid Ihr gekommen, mich zu befreien?", sourceObjectiveStatus = "unverified-source-field" }
quests[26604] = { id = 26604, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schutz ihrer königlichen Hoheit, Prinzessin Poobah", description = "Diese teuflischen Dschungelkatzen umkreisen mich bereits seit einiger Zeit. Ich beobachte sie so gut ich kann, aber sie scheinen... im Gras zu verschwinden.\n\nHört, wie sie knurren und zischen!\n\nVersteht mich nicht falsch... Ihr sollt mich immer noch retten, aber beseitigt zuerst diese Katzen. Ich muss nicht gerettet werden, wenn ich danach als Abendessen ende.", sourceObjective = "Tötet 5 Jagueropirscher.", completion = "Da seid Ihr ja endlich. Ich hatte schon befürchtet, ich würde gefressen werden, bevor Ihr von der Jagd zurückkehrt.\n\nEine Prinzessin im Magen einer Katze... wäre das nicht eine vornehme Beute?", sourceObjectiveStatus = "unverified-source-field" }
quests[26605] = { id = 26605, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bahaarte Diebe", description = "Ich verstehe ja, dass Ihr mich retten wollt, aber der richtige Zeitpunkt ist noch nicht gekommen.. Zuerst benötige ich etwas von meinem Besitz.\n\nDie Gorillas und Affen auf der anderen Seite der Insel haben das meiste davon gestohlen. Ich brauche meine Tiara, mein Szepter, meine Pantoffeln und mein Tagebuch, dann bin ich bereit zur Abreise.\n\nWas? Seht mich nicht an, als wäre ich irgendeine Verrückte. Ihr versteht nicht, was es bedeutet, Prinzessin zu sein.", sourceObjective = "Sucht nach Poobahs Tiara, Poobahs Szepter, Poobahs Pantoffeln und Poobahs Tagebuch bei den Affen auf der Insel Jaguero.", progress = "Ich zittere bei dem Gedanken an das, was Mukla mit mir vorhat.", completion = "<Poobah betrachtet ihren Besitz.>\n\nEs scheint alles da zu sein. Also gut, dann bin ich bereit, gerettet zu werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[26606] = { id = 26606, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muklas Ende", description = "{name}, ich setze all mein Vertrauen in Euch. Befreit mich. Der große Himmelsmähnenkönig Mukla hält mich gefangen. Er herrscht über die wilden Tiere auf der Insel. Mit Hilfe dieser Fessel halten sie mich hier gegen meinen Willen fest. Wenn es Euch gelingen sollte, ihn zu töten und den Schlüssel zu dieser Kette zu finden, würde ich tief in Eurer Schuld stehen.\n\nIch höre ihn oft an der Südostseite der Insel, aber seid bitte vorsichtig. Nehmt ihn nicht auf die leichte Schulter.", sourceObjective = "Tötet König Mukla, findet den Fesselschlüssel.", progress = "Ich danke meinen Ahnen, dass jemand gekommen ist, um mir zu helfen. Habt Ihr den Schlüssel, mit dem ich befreit werden kann?", completion = "{name}, Ihr habt mich vor großer Ehrlosigkeit bewahrt. Wenn es in meiner Macht stünde, würde ich Euch einen Platz in meinem Stamm anbieten. Doch leider kann ich Euch erst einmal nur diese Kleinigkeit für Eure Tapferkeit und Euren Anstand anbieten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26607] = { id = 26607, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie haben zuerst Blut vergossen", description = "Nehmt dieses Bündel mit Keeshans Habseligkeiten und kehrt in den Keller des Gasthauses in Seenhain zurück. Die Kompanie Bravo ist bereits dort und redet mit Keeshan. Erinnert ihn daran, wer als erstes Blut vergossen hat, {name}. Seenhain braucht Keeshan. Die Allianz braucht Keeshan.\n\nWegtreten, Soldat!", sourceObjective = "Bringt Keeshans Habseligkeiten zu John J. Keeshan im Gasthaus von Seenhain im Rotkammgebirge.", progress = "Ihr schon wieder?", completion = "<Keeshan nimmt Euch das Bündel ab und öffnet es.>\n\nMein Bogen... und mein Messer! Wo habt Ihr...\n\nJades Amulett... Meine geliebte Jade.\n\n<Keeshan nimmt sein rotes Stirnband.>\n\nLasst uns Orcs töten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26608] = { id = 26608, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abgebrochene Verhandlungen", description = "Geht nun, geht zurück zu Eurer Flotte. Sagt ihnen, was für ein Ungeheuer die Herrschaft über das Drachenmal für sich beansprucht.\n\nUnser \"Kriegshäuptling\" ist ein Verräter an seinem Blut. Seit seiner Rückkehr von der Scherbenwelt stinkt er nach Dämon und führt die Überreste unseres Klans ins Verderben.\n\nHelft dem Drachenmal, sich von Mor'ghor zu befreien, dann werden die unter uns, die reinen Blutes sind, für immer Eure Verbündeten sein. Das kann ich versprechen.", sourceObjective = "Kehrt zu Admiral Steinfaust vor der Küste der Drachenmalfestung im Schattenhochland zurück.", completion = "Die Höllenorcs aus der Scherbenwelt erheben Anspruch auf das Drachenmal? Obszön!\n\nWenn Höllschrei wüsste, was hier vorgeht, würde er ihre Stadt dem Erdboden gleichmachen...", sourceObjectiveStatus = "unverified-source-field" }
quests[26609] = { id = 26609, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Blutsegelbukaniere", description = "Ihr scheint ja sehr erpicht auf Arbeit zu sein, Kumpel. Bin nicht sicher, warum eine Landratte wie Ihr, {race}, und <ein/eine:c> {class} noch dazu, den Schwarzmeerräubern Hilfe anbietet, aber ich werd Euch nicht fortschicken.\n\nWir haben Beutebucht zu unserem gemütlichen zweiten Zuhause auf dem Festland gemacht, aber Gerüchten zufolge, hecken die Blutsegelbukaniere wieder etwas aus. Meine Jungs sind aber zu beschäftigt, sich einen anzusaufen und Mädchen nachzugaffen! Was ich brauch, ist ein Späher.\n\nBegebt Euch zur Bucht im Norden von Beutebucht an der Ungezähmten Küste und schaut, was Ihr so findet.", sourceObjective = "Erster Maat Krazz will, dass Ihr die Bucht nördlich von Beutebucht überprüft.", completion = "Oben auf dem Fass findet Ihr eine Karte mit einigen hastig geschriebenen Worten und einigen Münzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26610] = { id = 26610, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutsegelverrat", description = "Auf der Karte hat jemand ein rotes \"X\" in Beutebucht eingezeichnet, genau dort, wo Ihr gerade steht.\n\nDaneben hat jemand gekritzelt:\n\n\"Errichtet Euren Kommandoposten hier und wartet ab. Der Flottenmeister wird sich bei Euch melden, wenn die Zeit reif für Taten ist.\"\n\n\"Ich übertrage Leutnant Bruce hier das Kommando. Dieses Mal wird alles anders sein. Dieses Mal werden wir Beutebucht endgültig erobern.\"\n\nDie Karte wird von einem Dolch gehalten, der mitten in Beutebucht steckt.", sourceObjective = "Meldet Eure Entdeckung dem Ersten Maat Krazz in Beutebucht.", completion = "Sicher erinnere ich mich an Euch, {class}. Wie ich sehe, seid Ihr seid vom Spähen zurück....", sourceObjectiveStatus = "unverified-source-field" }
quests[26611] = { id = 26611, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Baron muss davon erfahren", description = "Beim Klabautermann! Also planen die Blutsegelbukaniere irgendeinen Angriff auf Beutebucht? Diese Schurken haben vielleicht Nerven. Die Schwarzmeerräuber werden Beutebucht niemals preisgeben!\n\nDas ist größer, als ich vermutet hatte. Meldet Baron Revilgaz sofort Eure Entdeckung! Ihr findet ihn hier in Beutebucht.", sourceObjective = "Berichtet Baron Revilgaz von den geplanten Blutsegelangriffen.", completion = "Blutsegel Bukaniere greifen Beutebucht an? Das ist nicht das erste Mal, dass dieses Gesindel so etwas versucht. Beutebucht ist uneinnehmbar!\n\nHört sich so an, als ob sie eine Taktik versuchen wollen. Ich würde es Firallon zutrauen, etwas Verrücktes zu versuchen. Nun gut, lasst uns herausfinden, was sie jetzt wieder im Schilde führen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26612] = { id = 26612, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einzelheiten des Angriffs", description = "Ich brauche Details, {name}. Wir sind den Blutsegeln hauptsächlich wegen unseres Bollwerks hier in Beutebucht überlegen, aber Informationen spielen ebenfalls eine wichtige Rolle.\n\nDie Blutsegelbukaniere haben nur ein paar kleine Lager im Süden errichtet, die sie als \"Südkommando\" bezeichnen. Nun, dieses so genannte Südkommando werdet Ihr überfallen. Findet ihre Pläne und tötet ihre Männer. Kehrt mit allen Informationen, die Ihr findet, zu mir zurück.", sourceObjective = "Tötet 8 Seebären der Blutsegelbukaniere und 8 Hochmagi der Blutsegelbukaniere und erbeutet die Blutsegelkarten und Blutsegelbefehle.", progress = "Ahoi, {name}. Was habt Ihr im Lager der Blutsegel im Süden herausgefunden?", completion = "Perfekt, {name}. Jetzt, da wir ihren Plan kennen, ist es nur noch eine Frage der Zeit.\n\nUnd wenn ich bedenke, dass diese Narren genau vorm Kap vor Anker gegangen sind ...", sourceObjectiveStatus = "unverified-source-field" }
quests[26613] = { id = 26613, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf dem Schnupftabak", description = "Ah, das Leben auf See. Ich sag nicht, dass es das wahre Leben ist, aber es ist mein Leben.\n\nWenn ich in den Hafen komme, such ich mir eine gute Flasche Grog und sehr guten Schnupftabak. Schlechte Angewohnheiten, ich weiß, aber irgendein Laster muss'n Pirat ja nun mal haben, nich?\n\nAlso könnt Ihr Euch vielleicht vorstellen, wie niedergeschlagen ich war, als ich herausfand, dass der Kräuterkundige nichts von dem Zeug mehr da hatte. Erzählte mir, dass seine Lieferung von den verdammten Räubern der Blutsegelbukaniere geklaut worden ist.\n\nIch wette, <ein furchtloser/eine furchtlose:c> {class} wie Ihr könnte sie überreden, die Ware zu teilen, nich?", sourceObjective = "Deeg in Beutebucht möchte, dass Ihr ihm 15 winzige Haufen Schnupftabak bringt.", progress = "Glück mit den Waren, Kumpel?", completion = "Klasse gemacht, {name}! Und gerade noch rechtzeitig, bevor ich wieder Anker lichten muss! Kann Euch gar nicht genug danken, alter Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[26614] = { id = 26614, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Auge offen halten", description = "Haltet ein! Wer da?\n\nGrrr, ich bin so gut wie nutzlos ohne mein verzaubertes Spezialauge. Als ob es nich' schon schlimm genug is', dass ich meine Augen im Kampf verlor'n hab! Aber zum Glück haben wir in Menethil angelegt und ein reisender Hexer hat 'n Spezialglasauge verzaubert, mit dem ich wieder was sehen kann.\n\nGestern Nacht hab'n mir aber 'n paar von den Blutsegelbukanier'n auf'm Weg nach Haus aufgelauert. Die ham mir doch echt mein Auge geklaut! Scheint, als hätt'n die Burschen Beutebucht gefunden.\n\nKönnt'er 'nem alten Seebären helfen und mir mein Auge zurückholen?", sourceObjective = "Besorgt Torkels Auge von den Blutsegelbukanieren.", progress = "Ahoi, Kumpel! Kann zwar nich' sehen, aber kann Euch schon über'n halben Hafen hinwech riechen.\n\nKönnte mein Auge wirklich gut gebrauchen. D'r Käpt'n wird mich wohl kielholen, wenn er rausfindet, dass mein Glubscher in die Hände der dreckigen Blutsegelbukaniere gefallen is'.\n\nWozu is'n Ausguck gut, wenn er nix sieht? Das Krähennest war mein Zuhause... ohne meine Augen kann ich von Glück sagen, wenn ich die Bilge schrubbn darf.", completion = "Da brat mir doch einer 'nen Storch! Ihr habt mein wunderbares Auge gefunden! Lass uns mal gucken, ob's noch passt.\n\n{name} ho! Kinners, ich kann sehen!!", sourceObjectiveStatus = "unverified-source-field" }
quests[26616] = { id = 26616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es ist nie vorbei", description = "Diese Schwarzfelsorcs werden eine Armee brauchen, wenn sie gegen die Kompanie Bravo und Euch etwas ausrichten wollen, {name}. Trefft Euch mit uns an den Docks, die auf den Immerruhsee hinausgehen, wenn Ihr bereit seid. Wir segeln auf meinem Flussboot zum Immerruhlager auf der anderen Seite des Sees.\n\nBis später, {name}.", sourceObjective = "Fahrt auf Keeshans Flussboot zum Immerruhlager im Rotkammgebirge.", completion = "Zeit, ein paar Orcs zu erledigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26617] = { id = 26617, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein alter Seebär", description = "Diese alte, verwitterte Münze wurde bei der Leiche des Piraten \"Guter Junge\" Bruce gefunden. Auf der Vorderseite ist das Abbild eines großen, unbekannten Piratenschiffs eingestanzt; auf der Rückseite der Begriff \"Mannschaft der Trümmerflut\".\n\nJemand, der schon lange im Pirateriegeschäft ist, konnte wissen, um was es sich bei dieser Münze handelt und was sie bedeutet.", sourceObjective = "Bringt die verwitterte Münze zu Flottenmeister Seehorn in Beutebucht.", progress = "Was habt Ihr denn da, {race}? Lasst mal sehen.", completion = "Diese Münze! Wo habt Ihr die her?\n\nBruce... ja, verstehe. Er gehörte früher den Schwarzmeerräubern an. War einer von uns, bevor Graumähne die Häfen von Gilneas schließen ließ und seine Besatzung gefangen nahm.\n\nIch weiß, dass sich die Leute durch das, was in Gilneas geschah, veränderten, aber ich hätte nie gedacht, dass sie ihre Loyalitäten wechseln würden. Vor allem nicht Bruce.\n\nKönnte ich die Münze vielleicht behalten? Ich gebe Euch ihren Gegenwert in Gold.", sourceObjectiveStatus = "unverified-source-field" }
quests[26618] = { id = 26618, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wölfe sind uns auf den Fersen", description = "Die Stadtbewohner werden in erster Linie von den Terrorwölfen bedroht. Sie lauern in den Wäldern um uns herum, die meisten findet man jedoch am Nordufer des Flusses.\n\nSie sind anders als die räudigen Hunde, die Ihr aus Elwynn, oder wo immer Ihr auch herkommt, gewöhnt seid. Sie sind mannsgroß und zweimal so teuflisch.\n\nWenn Ihr den Einwohnern von Dunkelhain wirklich helfen wollt, dann jagt die Wölfe, damit wir auf unseren Straßen endlich wieder sicher sind.", sourceObjective = "Tötet 12 Terrorwölfe.", completion = "Denkt nicht, dass sei zu leicht gewesen. Tiefer in den Wäldern lauern weit größere Gefahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[26619] = { id = 26619, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr wollt also eine Revolution", description = "Wenn es stimmt, was Ihr sagt, {name}, dann haben wir Freunde innerhalb des Drachenmalklans. Wir könnten einen Aufstand in ihren eigenen Reihen unterstützen. Das würde viel Blutvergießen auf beiden Seiten verhindern.\n\nIch kann dabei helfen, aber den gefährlichsten Teil muss ich Euch überlassen.\n\nMeine Krieger der Axtbeißer werden mit ihrer Offensive an den Küstenstreifen beginnen. Nutzt diese Ablenkung und schleicht Euch hinter die feindlichen Linien. Sprecht dort mit Zaela, Eurem Kontakt zu den Rebellen.\n\nWir werden den Drachenmalklan bewaffnen und seine teuflischen Herrscher stürzen!", sourceObjective = "Schleicht Euch hinter die Frontlinie am Hafen des Drachenmals und sprecht mit Zaela.", completion = "{name}, was machen Eure Leute? Greift Ihr das Drachenmal an oder seid Ihr hier, um uns von Mor'ghors Verderbnis zu befreien?\n\n\n\nAh, jetzt verstehe ich. Mir gefällt, wie Ihr denkt. Kriegshäuptling Mor'ghor wird völlig überrascht werden.\n\nLasst uns beginnen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26620] = { id = 26620, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewürzte Wolfkebabs", description = "Gewürzter Wolfkebab ist eine Spezialität des Hauses! Natürlich kann ich Euch einige machen. Doch zuerst brauche ich die Zutaten.\n\nBringt mir fünf Wolfskronfleischsteaks. Die Terrorwölfe nahe dem Fluss nördlich der Stadt, lassen sich gut jagen, aber ich würde an Eurer Stelle nicht zu tief in die Wälder vordringen.", sourceObjective = "Sammelt 5 Wolfskronfleischsteaks von Terrorwölfen.", progress = "Habt Ihr schon fünf Wolfskronfleischsteaks gefunden?", completion = "Hmmm-hmmm! Das Kronfleisch ist der beste Teil. Allerdings ist es nicht sehr effizient, damit zu kochen.\n\nHier, nehmt dieses Rezept. Es unterscheidet sich ein wenig von dem anderen, aber Flankenfleisch ist viel leichter zu bekommen, wenn Ihr dringend eine Mahlzeit benötigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26621] = { id = 26621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstand", description = "Die Waffen, die wir von der Horde bekommen haben, sind mehr als ausreichend. Wir vier sollten uns aufteilen und so viele Arbeiter und Händler des Drachenmals bewaffnen wie möglich.\n\nUnterschätzt uns nicht, {name}. Selbst unsere Kaufleute sind im Kampf gnadenlos.\n\nLasst uns so viel Schaden wie möglich anrichten. Bewaffnet eine Truppe des Drachenmalklans und mäht die Teufelsvollstrecker und Hexenmeister nieder, die mein Volk schon so lange einschüchtern. Danach treffen wir uns hier, um unseren letzten Schlag einzuleiten!", sourceObjective = "Bewaffnet 3 Arbeiter oder Händler des Drachenmals und tötet 10 Vollstrecker des Drachenmals und 4 Hexenmeister des Drachenmals.", progress = "Die Revolution hat endlich begonnen!\n\nDas Drachenmal schüttelt endlich die Fesseln ab, mit denen die Unwürdigen uns gebunden hatten.", completion = "Wir haben viele gute Orcs verloren, doch den Kampf werden wir für uns entscheiden, {name}.\n\nMor'ghors Regime bricht zusammen. Nur die Bestie selbst steht noch.", sourceObjectiveStatus = "unverified-source-field" }
quests[26622] = { id = 26622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet Mor'ghor", description = "Die Zeit ist gekommen. Heute stirbt Mor'ghor.\n\nEine Warnung, {class}. Dämonenblut fließt durch seine verfluchten Adern. Er bedient sich unnatürlicher Kräfte. Er wird sterben, das ist sicher. Doch es wird kein leichter Kampf. Ihr wisst ja noch, dass sich Mor'ghor an der Spitze des Lagers aufhält. Dort werde ich Euch treffen. Erledigt ihn!\n\nVergesst nicht, 3 Anhänger des Drachenmals zu rekrutieren, solltet Ihr zu wenig Kämpfer haben - Ihr werdet unsere Hilfe brauchen.", sourceObjective = "Tötet Kriegshäuptling Mor'ghor im Hafen des Drachenmals. Ihr könnt immer noch Händler und Arbeiter des Drachenmals rekrutieren. Sie werden Euch helfen.", completion = "Gut gemacht, {name}! Während meiner Abwesenheit habt Ihr die Horde mit Stolz erfüllt.\n\nDer Drachenmalklan ist zu uns gestoßen. Zaela führt ihn an. Es wurde Blut vergossen, doch nur wenige sind gefallen. Das Drachenmal steht nun loyal hinter uns.\n\nUnsere Horde wird stärker!", sourceObjectiveStatus = "unverified-source-field" }
quests[26623] = { id = 26623, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwärzliche Krebsküchlein", description = "Ich verrate Euch ein kleines Geheimnis - Schwärzliche Krebsküchlein werden in Wirklichkeit aus Spinnenfleisch gemacht! Ist ein bisschen eklig, aber die Küchlein haben einen würzigen Beigeschmack und eignen sich gut als Zwischenmahlzeit!\n\nAber wenn Ihr immer noch welche probieren möchtet, muss ich leider gestehen, dass ich kein Fleisch mehr habe. Ich brauche ein paar Fleischklumpen, dann kann ich die Küchlein backen.\n\nJagt am besten Giftweberspinnen. Sie nisten im Norden zwischen dem Vorgebirge und dem Fluss.", sourceObjective = "Erbeutet 6 schwärzliche Klumpen von Giftweberspinnen.", progress = "Seid gegrüßt, {name}. Habt Ihr die Fleischklumpen für mich?", completion = "Ah ja, da habt Ihr ja ein paar nette Klumpen eingesammelt! So, jetzt muss ich die nur noch mit meiner hochgeheimen Gewürzmischung würzen - wehe, Ihr schaut! - und sie dann noch ein bisschen in der Pfanne braten...\n\nDie schwärzlichen Krebsküchlein sind meine Spezialität, deswegen verrate ich das Rezept nicht. Aber hier habt Ihr das Rezept für ein Gericht, das fast genauso gut schmeckt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26624] = { id = 26624, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Tuchfühlung mit den Blutsegeln", description = "Diese Pläne sind... interessant. Firallon, so dumm kannst du doch nicht sein!\n\nSeht, alle seine Schiffe sollen sich auf das Feuern ihrer Kanonen konzentrieren. Nur ein paar Männer kommen durch die Tunnel rein. Mit drei Schiffen und einem Dutzend Kämpfer wird er Beutebucht nie einnehmen. Und das weiß er auch.\n\nNein, sie haben etwas anderes vor... und Ihr werdet herausfinden, was. Sprecht mit Yancey Grillsen, dem Rekrutierer der Blutsegel.\n\nRichtig, {name}. Hofft, dass sie Euch nicht wiedererkennen.", sourceObjective = "Meldet Euch bei Yancey Grillsen am Wasserfall nördlich von Beutebucht.", completion = "Jaaa, is' die richtige Entscheidung, Bursche.", sourceObjectiveStatus = "unverified-source-field" }
quests[26625] = { id = 26625, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troggzor der Erdinator", description = "Ihr müsst das sofort beenden!\n\nKehrt zur Front im Nordwesten zurück und tötet ihren Schlachtenführer, Troggzor den Erdinator. Bringt mir zum Beweis seinen Knüppel.", sourceObjective = "Erbeutet den Knüppel des Erdinators.", progress = "Ist er tot? Habt Ihr den Knüppel?", completion = "<Der General nickt ernst.>\n\nEndlich können wir vorrücken und den Steinvater befreien.", sourceObjectiveStatus = "unverified-source-field" }
quests[26627] = { id = 26627, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Einsiedler", description = "Ich habe gehört, dass etwas im Bettlerschlupfwinkel vor sich geht. Man sieht Lichter im Turm östlich der Stadt.\n\nNur wenige haben den Mut, sich so nahe am Gebirgspass der Totenwinde aufzuhalten. Ihr seid <der/die> erste, <der/die> sich hier meldet, seit ich davon erfahren habe. Seht es Euch an und stellt sicher, dass das, was dort haust, menschlich ist.", sourceObjective = "Findet den Bewohner des Turms im Bettlerschlupfwinkel.", completion = "Ah, willkommen, Fremder! Ich würde Euch gerne etwas anbieten, aber hier gibt es nicht viel...\n\nDürfte ich Euch bitten, ein paar Botengänge für einen alten Einsiedler zu machen?", sourceObjectiveStatus = "unverified-source-field" }
quests[26628] = { id = 26628, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod von unten", description = "Das ist übel. Es scheint, als ob die Säbelflossen sich zum Angriff sammeln.\n\nNaga sind bekannt für ihre Ruchlosigkeit im Kampf. Sie werden so lange angreifen, bis ich tot bin.\n\nIch schätze mein eigenes Leben nicht höher als das meiner Crew, aber Ihr müsst helfen, mich zu verteidigen. Die Crew ist nicht in der Lage, ohne meine Kenntnisse des Meeres nach Beutebucht zurückzufinden.\n\nDie Naga werden vom Meer her kommen. Ihr müsst mit mir hier oben bleiben, um den Angriff abzuwehren. Bemannt die Kanone und treibt sie zurück.\n\nSeid Ihr bereit, {name}?", sourceObjective = "Beschützt Wank O'Breen während des Angriffs.", completion = "Wir haben den Angriff überlebt!\n\nOhne Euch hätten wir es nicht geschafft, {name}.\n\nSobald die Flut kommt, werden wir hier wegsegeln. Wenn Ihr nicht ein so viel versprechender Held wärt, würde ich Euch einen Platz in meiner Crew anbieten. Aber ich seh schon, Ihr habt Größeres vor.\n\nAuch wenn Ihr nur ein schwacher {race} seid...", sourceObjectiveStatus = "unverified-source-field" }
quests[26629] = { id = 26629, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feststellung Eurer Loyalität", description = "Da is' nur eine Sache...\n\nYancey hört einiges. Ein paar Kumpel von mir hatten schon ziemlich tief ins Glas geschaut, als sie mir von <einem/einer:c> {class} erzählten, <der/die> sich durch das Südkommando kloppte un' nach Karten und Befehlen suchte. <Er/Sie> hat sogar ein paar anständige Piraten über die Klinge springen lassen.\n\nWie ich schon sagte, denen kam der Grog aus den Augen raus, aber... ein Bukanier muss seinen Ohren trauen. Deshalb hat mich Firallon selbst gefragt, ob ich Euch nich' ne kleine Aufgabe stellen könnte...\n\nBringt mir den Kopf von Flottenmeister Seehorn.", sourceObjective = "Besorgt den Kopf von Flottenmeister Seehorn in Beutebucht.", progress = "Spezialbefehl von Firallon. Sagt, der Tauren sei zu gefährlich.", completion = "Na da haut's mich doch aus dem Krähennest! So was sieht man wirklich selten.\n\n<Yancey schüttelt Eure Hand.>\n\nWillkommen an Bord, {name}. Beutezüge und Plünderungen erwarten Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[26630] = { id = 26630, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sieht doch wie ein Taurenpirat aus", description = "Firallon will MEINEN Kopf? Das ist wirklich interessant. Aber wir finden schon einen Ausweg.\n\nDieser Yancey weiß wahrscheinlich nicht so genau, wie ich aussehe. Den meisten Nicht-Tauren fällt es schwer, uns Tauren auseinanderzuhalten. Den meisten Nicht-Tauren fällt es sogar schwer, uns von einem gewissen... vierbeinigen Nutztier zu unterscheiden.\n\nRikqiz, der Lederverarbeiter, hält eine solche Kreatur hier in Beutebucht, und Narkk versorgt mich mit Piratenhüten. Besorgt Ersatz für meinen Kopf und meinen Hut und kehrt mit beidem hierher zurück.", sourceObjective = "Besorgt einen Kuhkopf und einen übergroßen Piratenhut. Bringt beides zu Flottenmeister Seehorn.", progress = "Ihr solltet wissen, dass das den meisten Tauren peinlich wäre. Ich finde es... amüsant.", completion = "Damit sollten wir den minderbemittelten Blutsegelbukanier täuschen.\n\nDas hat Spaß gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26631] = { id = 26631, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer erster Tag als Pirat", description = "Ihr habt zwar den Flottenmeister erledigt, aber Regeln sind Regeln und Befehle Befehle. Und meine Befehle besagen, dass alle neuen Piraten als Deckhelfer anfangen. Das sind die Regeln.\n\nIhr werdet für Käpt'n Kielhol, den Kommandanten der Springflut, arbeiten. Es is' das westlichste Schiff der Flotte, die südlich der Kapspitze liegt.\n\nSucht ihn in seiner Kapitänskajüte auf un' bringt ihm Eure Papiere.", sourceObjective = "Bringt Käpt'n Kielhol Eure Papiere.", progress = "Habt Ihr Eure Papiere, Deckhelfer? Will Euch ja nich' den ganzen Weg zurück zu Yancey schicken.", completion = "Ja... ja... Verstehe... scheint alles in Ordnung zu sein.\n\nHabt den großen Seehorn weggeputzt, ja? Spielt auf MEINEM Schiff keine Rolle. Das einzige, was Ihr hier wegputzen werdet, sind die Flecken auf dem Deck. Nehmt Euch einen Mopp.", sourceObjectiveStatus = "unverified-source-field" }
quests[26632] = { id = 26632, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geleitschutz", description = "Gut, ich glaube, das funktioniert wieder. Ihr müsst das Katapult nach Nadelfelsbruch, der Stadt der Steintroggs, nördlich der Front bringen.\n\nDer Fahrer wird Euch begleiten. Ich werde mich auf den Rückweg machen und Kies darüber informieren.\n\nDie Steintroggs werden zweifellos versuchen, Euch aufzuhalten. Haltet sie vom Katapult fern. Es hat eine ziemliche Durchschlagskraft.\n\nLasst mich wissen, wenn Ihr bereit seid, {name}.", sourceObjective = "Geleitet das Katapult des Irdenen Rings sicher nach Nadelfelsbruch.", completion = "<Der Katapultkommandant wirft Euch einen anerkennenden Blick zu.>\n\nDie Erzählungen von Eurer Kampfkunst eilen Euch weit voraus, {race}. Wollen wir mal sehen, ob Ihr uns auch dabei helfen könnt, diese Fungusschrecken von der Front fernzuhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26633] = { id = 26633, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Putzdienst", description = "Die Decks der Springflut sollten leuchten wie ein Sternrubin, Deckhelfer {name}. Ich führe 'n ordentliches Schiff, dafür sorgen Deckhelfer wie Ihr!\n\nNa, worauf wartet ihr denn noch, Ihr miesmuscheldämliche Schiffsratte? Ans Deck mit Euch! Nehmt den Mopp in die Hand!", sourceObjective = "Nehmt Euch einen Deckhelfermopp vom Deck der Springflut und haltet das Deck 2 Minuten lang sauber.", completion = "Ich habe wilde Putzgeräusche von hier unten gehört, Bursche. Genau DAS will Euer Käpt'n hören.", sourceObjectiveStatus = "unverified-source-field" }
quests[26634] = { id = 26634, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fluch vieler Piraten", description = "Zahnfleischerkrankung. Das ist ein großes Problem, {race}.\n\nIch weiß, dass Ihr neu seid und Euch wahrscheinlich noch nie jemand das Zahnfleisch aufgeschnitten hat, aber wir anderen Piraten müssen uns mit etwas herumschlagen, dass sich SKORBUT nennt. Deshalb lagern wir hier so viele Limonen.\n\nNa ja... lagerten hier so viele Limonen. Jemand hat unsere letzte Lieferung geklaut, aber sie können nicht weit gekommen sein - vielleicht bis zu den nahegelegenen Inseln? Schafft sie wieder her, dann überlege ich mir vielleicht, was ich tun kann, um für Eure Beförderung vom Deckhelfer zu sorgen.", sourceObjective = "Besorgt 5 Scheffel Limonen.", progress = "Zu viele gute Männer habe ich an dieser leicht zu verhindernden Krankheit sterben sehen, {race}. Wir brauchen diese Limonen.", completion = "Ich werde sie direkt verteilen, {race}. Und ich werde ein gutes Wort für Euch einlegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26635] = { id = 26635, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwimmen mit Kanonenkugeln", description = "Würdet Ihr 'nem Deckhelferkameraden helfen?\n\nKielhol hat mir befohlen, ein paar Kanonenkugeln vom Meeresboden aufzusammeln. Ich erklär' Euch, wieso ich das nicht kann.\n\nErstens: Ich habe winzige Arme. Seht sie Euch doch an! Glaubt Ihr wirklich, ich könnte damit eine Kanonenkugel aufheben, selbst, wenn sie Unterwasser liegt?\n\nZweitens: Ich habe sehr schwache Atmungsorgane. Mir wird schon schwindlig, wenn ich den Atem länger als zehn Sekunden anhalten muss.\n\nDrittens: Da sind Haie.\n\nIhr müsst mir helfen, {name}! Eine weitere Degradierung würde ich nicht aushalten... Will gar nicht wissen, was als nächstes käme!", sourceObjective = "Bergt 6 Blutsegelkanonenkugeln aus dem Wasser unter der Springflut.", progress = "Wisst Ihr, ich war nicht immer ein Deckhelfer.", completion = "Danke, {name}. Ich hab' schon Leute 'was von wegen \"dem Schönling\" und irgendeiner \"Buhkiste\" reden hören. Ich glaube nicht, dass ich diese Buhkiste von innen sehen will.", sourceObjectiveStatus = "unverified-source-field" }
quests[26636] = { id = 26636, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marschgepäck der Kompanie Bravo: Tarnung", description = "Wir werden einiges an Ausrüstung brauchen, bevor wir die Schwarzfelsarmee ausschalten und das Rotkammgebirge retten können. Dabei könnt Ihr Euch nützlich machen, Grünschnabel.\n\nKeeshan hat mir befohlen, dafür zu sorgen, dass das Marschgepäck der Kompanie Bravo getarnt wird. Ich möchte, dass Ihr nach Süden geht und Euch ein wenig \"gärtnerisch\" betätigt. Bei diesem kleinen Abenteuer gibt es zwei Zutaten, über die Ihr Bescheid wissen solltet: (1) Blätter und (2) Fuchskot. Wir brauchen beides.\n\nHabt Ihr Euch nie gefragt, woraus Tarnung besteht?\n\nGeht nach Süden und findet, worum ich Euch gebeten habe, <Freund/Lady>.", sourceObjective = "Sammelt 5 Blätterhaufen und 5 Portionen Fuchskot.", progress = "Blätter und Kot - das brauche ich.", completion = "Gut gemacht, Grünschnabel. Ich lege die Tarnung direkt in die Kiste. Wir sollten bald bereit sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[26637] = { id = 26637, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marschgepäck der Kompanie Bravo: Chloroform", description = "Der erste Teil unserer Mission findet verdeckt statt, {name}. Deshalb müssen wir in der Lage sein, unseren Feind lautlos auszuschalten. Um das zu erreichen, brauchen wir Chloroform.\n\nDie Drüsen der Matschwirbler am Grund des Immerruhsees enthalten Chloroform. Schwimmt hinunter und besorgt mir Matschwirblerdrüsen. Kriegt Ihr das hin?\n\nKehrt zu mir zurück, wenn Ihr genügend Drüsen gefunden habt.\n\nIhr wollt wissen, wo der See ist? Macht die Augen auf, Trottel. Unmittelbar westlich.", sourceObjective = "Sammelt 8 Matschwirblerdrüsen.", progress = "Habt Ihr die Drüsen gefunden?", completion = "Perfekt. Diese Orcs werden uns buchstäblich verschlafen. Ich brauche einige Minuten, um sie zu verarbeiten, dann lege ich sie in das Marschgepäck der Kompanie Bravo.", sourceObjectiveStatus = "unverified-source-field" }
quests[26638] = { id = 26638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagd auf die Jäger", description = "Südlich von hier, entlang des Uferpfads, lauern Schwarzfelsorcs in den Wäldern. Im Schutz der Dunkelheit überfallen sie die Ahnungslosen. Diese Orcs bilden die erste Verteidigungslinie der Schwarzfelsarmee. Es sind Kundschafter, die alles, was sie sehen, ihrem Oberkommando melden. Sie müssen AUSGESCHALTET werden, sonst könnten sie unsere Mission gefährden.\n\nGeht nach Süden und tötet alle Jäger des Schwarzfels, die Ihr seht.", sourceObjective = "Tötet 8 Jäger des Schwarzfels.", completion = "Hervorragende Arbeit, {name}. Wir müssen uns beeilen, bevor sie Verstärkung anfordern.", sourceObjectiveStatus = "unverified-source-field" }
quests[26639] = { id = 26639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kontaktpunkt: Brubaker", description = "Wir müssen unser Marschgepäck zusammen bekommen, vorher sind wir verdammt unnütz. Dabei werdet Ihr helfen, {name}. Kundschafter benötigen wir ebenfalls. Zum Glück haben wir Unterstützung aus Sturmwind erhalten. Brubaker, ein alter Kriegskamerad von mir, ist von SI:7 geschickt worden, um uns als Kundschafter zu dienen. Trefft ihn im Kampfgebiet südlich von hier.\n\nTrefft Euch mit Brubaker und findet heraus, was er weiß.", sourceObjective = "Findet Brubaker.", completion = "Brubaker ist tot. Anscheinend versuchen die Orcs durch diesen grausigen Anblick eine Nachricht zu senden. Bei näherem Hinsehen entdeckt Ihr etwas in Brubakers Beutel.", sourceObjectiveStatus = "unverified-source-field" }
quests[26640] = { id = 26640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unaussprechliche Gräuel", description = "<Ihr faltet die Notiz auseinander und beginnt zu lesen.>\n\nKeeshan, wenn Ihr diese Nachricht lest, werde ich tot sein. Wahrscheinlich wurde meine Position kompromittiert.\n\nDie Orcs begehen unaussprechliche Gräuel an ihren Gefangenen. Ja, Gefangene, Keeshan. Sie haben Käfige voll mit Kriegsgefangenen. Bevor Ihr dieses Tal in die Luft sprengt, müsst Ihr die Gefangenen befreien.\n\nSagt meiner Frau, dass ich sie liebe und dass sie den verdammten Müll rausbringen soll.\n\n-Brubaker\n\nPS - Sie haben schwarze Drachen.\n\nBringt Keeshan Brubakers Report.", sourceObjective = "Bringt Brubakers Report zu John J. Keeshan im Immerruhlager im Rotkammgebirge.", progress = "Sie haben Brubaker erwischt?", completion = "<Keeshan liest den Report.>\n\nVERDAMMT! Jetzt wird es kompliziert. Wir müssen die Kriegsgefangenen befreien, bevor wir das Tal sprengen können. Mal ganz abgesehen von den schwarzen Drachen, die den Orcs zur Seite stehen.\n\nSeid Ihr bereit, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[26641] = { id = 26641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eiertanz", description = "Die Brutwachen der Blutfratzen im Nordosten bewachen die Eier von Shadras Brut. Auch wenn wir die Blutfratzen töten, werden diese schrecklichen Kreaturen irgendwann aus ihren Eiern schlüpfen und in die Wildnis entkommen.\n\nDas müssen wir verhindern. Reißt alle Eier, die Ihr findet, aus ihren Eiersäcken und bringt sie mir. Versucht nicht, sie selbst zu zerstören; die Kleinen könnten herauskommen.\n\nWenn Ihr wieder hier seid, sorge ich dafür, dass sie vernünftig entsorgt werden!", sourceObjective = "Besorgt 5 Eier der Shadrabrut aus Agol'watha.", progress = "Habt Ihr die Eier?", completion = "Wir werden sie sofort verbrennen und die Asche zur Sicherheit verstreuen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26642] = { id = 26642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erhaltung des Brachlands", description = "Seit Jahren bildet das Brachland das Herz des Hordengebiets in Kalimdor. Es ist eine wichtige Verbindung zwischen den Orcs von Durotar und den Taurensiedlungen in Mulgore.\n\nIm Chaos des Kataklysmus drohen wir durch Überflutungen, Erdbeben und sogar einer Invasion der Stacheleber von diesem wichtigen Grasland abgeschnitten zu werden.\n\nIhr wirkt, als wärt Ihr bereit für eine Herausforderung. Meldet Euch bei Kargal Schlachtnarbe in der Fernwacht und stellt sicher, dass der Weg ins Brachland frei bleibt! Reist ins nahe gelegene Klingenhügel und von dort aus gen Westen. Überquert den Südstrom, dann werdet Ihr ihn finden.", sourceObjective = "Meldet Euch bei Kargal Schlachtnarbe in der Fernwacht im Nördlichen Brachland.", completion = "Ein neuer Rekrut aus Orgrimmar, richtig?\n\n<Kargal mustert Euch.>\n\nIch nehme, was ich kriegen kann. Es ist ein Alptraum, die Straßen frei zu halten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26643] = { id = 26643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hungerdiät", description = "In den Gruselruinen östlich von hier wimmelt es von ausgewachsenen Spinnen der Shadrabrut. Sie sind so groß, dass sie einen ganzen Zwerg nachts davonschleppen können. Die Beweise dafür werdet Ihr sehen, wenn Ihr dort ankommt... eingesponnene Körper überall in den Ruinen.\n\nSie halten sie nicht lange am Leben, {name}, aber von den Leichen ernähren sie sich tagelang. Den Opfern kann niemand mehr helfen, aber diese Spinnen dürfen nicht noch fetter und kräftiger werden. Sorgt dafür, dass diese Kokons verschwinden.", sourceObjective = "Zerstört 6 eingesponnene Opfer in den Gruselruinen.", completion = "Eine makabere Aufgabe, {name}, doch nun werden sich die überlebenden Spinnen nicht mehr erholen. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[26644] = { id = 26644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufmerksamkeit erregen", description = "Deckhelfer {name}! Das ist ein trauriger Tag für den alten Käpt'n Kielhol. Heute verliere ich meinen besten Deckhelfer.\n\nIch habe einen Brief von Flottenmeister Firallon erhalten. Anscheinend hat er von Eurer guten Putzleistung gehört. Ihr sollt an Bord der Purpurschleier kommen und als sein Bootsmann und Dritter Maat dienen. Sie liegt direkt neben der Springflut.\n\nDas ist 'n großer Schritt in Eurer Piratenkarriere, Deckhelfer {name}. Ich würde vorschlagen, sein Angebot anzunehmen.\n\nWegtreten!", sourceObjective = "Meldet Euch bei Flottenmeister Firallon im Inneren der Purpurschleier am Schlingendornkap.", completion = "Also Ihr habt den alten Seehorn abgemurkst? Yancey hat so was gesagt, aber ich wollte sicherstellen, dass er nicht wieder Seemannsgarn gesponnen hat.\n\nIch werde es kurz machen. Das mit Kielhols Mannschaft habt Ihr gut gemacht, aber ich erwarte, dass Ihr bei meiner noch besser seid. Ich muss mich um eine ganze Flotte kümmern, also werdet Ihr mir bei der täglichen Routine auf meinem Schiff helfen.\n\nWillkommen an Bord der Purpurschleier, Seemann.", sourceObjectiveStatus = "unverified-source-field" }
quests[26645] = { id = 26645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nachtwache", description = "Ihr seid leider <der Einzige, der/die Einzige> die; mir hier helfen kann, {name}. Die Streitkräfte Sturmwinds werden von weit größeren Gefahren bedroht. Sie können keinen einzigen Soldaten zum Schutz von Dunkelhain abstellen. Ich und die anderen aus der Nachtwache müssen uns um die Sicherheit unserer Heimat kümmern.\n\nLeider bedrohen uns nicht nur Wölfe. Verrottende Schrecken treiben nahe dem Spukhaus der blinden Mary am südöstlichen Stadtrand ihr Unwesen. Wenn wir sie nicht in Schach halten, werden sie in der Nacht unsere Häuser besuchen.\n\nKümmert Euch um die Untoten und meldet Euch bei mir, um belohnt zu werden.", sourceObjective = "Tötet 8 verrottende Schrecken nahe dem Spukhaus der blinden Mary, südöstlich von Dunkelhain.", completion = "Wunderbar, {name}. Für Euren Dienst an den Einwohnern von Dunkelhain sollt Ihr entlohnt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[26646] = { id = 26646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsgefangene", description = "Das Marschgepäck der Kompanie Bravo ist fertig, {name}. Ich werde Euch damit ausrüsten. Ihr werdet Renders Tal, südöstlich von hier, betreten und unsere Kriegsgefangenen befreien. Ich gebe Euch Jorgensen mit. Er wird Euch den Rücken freihalten.\n\nDie Gefangenen sitzen im Nordosten des Tals in einem großen Käfig, aber der Schlüssel zu diesem Käfig befindet sich in einer Höhle im Süden des Tals. Ihr müsst den Schlüssel stehlen, für Ablenkung sorgen und die Bürger befreien.\n\nViel Glück, {name}! Wir bleiben über das Marschgepäck in Verbindung.", sourceObjective = "Befreit die Kriegsgefangenen, die im Gefängnis von Renders Tal sitzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26647] = { id = 26647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dicke Emma", description = "Wir haben viel Arbeit vor uns. Wie viel Erfahrung habt Ihr mit Kanonen? Hmm... wirklich? Und wie sieht es mit uralten, zusammenbrechenden Piratenkanonen aus?\n\nAuf den Decks gibt es noch ein paar Kanonen, die auf die altmodische Weise funktionieren: Man lädt immer nur eine Kanonenkugel, zielt, arretiert und feuert. Funktioniert gut, wenn man die Seite eines Dreimasters treffen will... nicht so gut bei Ruderbooten und ähnlichem.\n\nGeht doch mal nach oben und feuert ein paar Schuss auf Timmy Grinsezweig ab.", sourceObjective = "Übt die Benutzung der Kanone, indem Ihr Timmy Grinsezweig mit 5 Kanonenkugeln von der Dicken Emma trefft.", completion = "Mir gefällt Euer Stil, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26648] = { id = 26648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsere Todfeinde", description = "Hey, Neuling, seht Euch das mal an.\n\n<Der Zwerg hebt seine Augenklappe und enthüllt einen echten, funktionierenden Augapfel.>\n\nIch trage die Klappe nicht wegen eines verlorenen Auges. Ich trage sie, weil das ANDERE Auge so stark ist, dass es von dem normalen ausgebremst wurde.\n\nMit diesem Auge kann man alles Mögliche sehen, zum Beispiel die maskierten Schlägertypen, die uns folgen. Der Flottenmeister sagt, dass sie auf der Insel Jaguero aufgetaucht sind. Feuert diese Leuchtpistole ab, wenn Ihr dort eintrefft, und ich werde Euch helfen, sie auch zu sehen.", sourceObjective = "Tötet 15 Ninjas auf der Insel Jaguero.", sourceObjectiveStatus = "unverified-source-field" }
quests[26649] = { id = 26649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schießbudenpiraterie", description = "Ihr wisst ja jetzt, wie man mit unseren Kanonen umgeht, also wird es Zeit, dass Ihr echte Ziele trefft!\n\nDie Venture Company hat nördlich von hier Gold gefunden... eine seltene Art, die sie \"schwarzes Gold\" nennen. Sieht für mich eher wie ein schwarzer Fleck aus.\n\nWir werden uns dieses Gold holen, aber zuerst müssen wir die Trottel der Venture Company los werden. Ein Ruderer wird Euch dort hinaus bringen. Verlasst das Schiff über die Laufplanke und sprecht mit ihm am Nordstrand der kleinen Insel.", sourceObjective = "Sprecht mit dem Ruderer der Blutsegelbukaniere außerhalb der Purpurschleier und tötet dann 75 Ölarbeiter der Venture Co. mit der Kanone.", completion = "Ahahaha! Ihr habt sie glatt aus ihrer Takelage gesprengt! Darauf trinke ich!\n\nVor Euch liegt eine große Zukunft, Grünschnabel.", sourceObjectiveStatus = "unverified-source-field" }
quests[26650] = { id = 26650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die \"Maid im Glück\"", description = "Ich weiß ja, dass Ihr erst vor kurzem auf der Purpurschleier angekommen seid, aber ich könnte Euch für 'ne andere Aufgabe gebrauchen. Die Maid im Glück ist das dritte Schiff in meiner Flotte. Sie liegt östlich von hier. Ihr Skipper, Kapitän Stillwasser, weilt nicht mehr unter uns.\n\nVerdammt seien diese maskierten Strolche!\n\nIn jedem Fall hat mir Stahlauge von Euren Heldentaten auf See erzählt, und mir gehen langsam die qualifizierten Briganten aus. Ich denke, dass Ihr mehr als nur in der Lage sein werdet, Eure neuen Pflichten zu erfüllen.\n\nHerzlichen Glückwunsch, <Kumpel/Mädchen>. Ihr seid der neue Kapitän der Maid im Glück.", sourceObjective = "Meldet Euch in Eurer Kapitänskajüte im Inneren der Maid im Glück am Schlingendornkap.", completion = "Ihr seht Pläne ausgerollt auf dem Tisch liegen. Sie erklären alles!\n\nDas sind Einzelheiten des bevorstehenden Angriffs auf Beutebucht. Kampfformationen, Angriffspläne und etwas über eine Gruppe, die \"Mannschaft der Trümmerflut\" heißt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26651] = { id = 26651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Um einen Krieg zu gewinnen, müsst Ihr zum Krieg werden", description = "<Das Funkgerät der Kompanie Bravo piept.>\n\nVersteht Ihr es schon, {name}? Wisst Ihr jetzt, was wir tun müssen, um einen Krieg gegen diese Ungeheuer zu gewinnen? IHR MÜSST ZUM KRIEG WERDEN! KEINE GNADE!\n\nDie Kriegsgefangenen sind befreit. Ihr könnt das Zephyrium anbringen. Betretet vorsichtig die Gebäude dort draußen und bringt je einen Sprengsatz an.\n\nBringt je eine Zephyriumladung an der Munitionshütte des Schwarzfels und am Turm des Schwarzfels an. Trefft Euch mit mir und dem Rest der Kompanie Bravo in der Schieferwindschlucht östlich von Renders Tal.", sourceObjective = "Bringt mit dem Marschgepäck der Kompanie Bravo je eine Zephyriumladung am Turm des Schwarzfels und an der Munitionshütte des Schwarzfels an.", completion = "Und jetzt jagen wir das ganze verdammte Ding in die Luft.", sourceObjectiveStatus = "unverified-source-field" }
quests[26652] = { id = 26652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geisterhaarfaden", description = "Es gibt einen armen, traurigen Geist namens die blinde Mary, die in einem alten Farmhaus in den Hügeln südlich von Dunkelhain herumspukt.\n\nNehmt diesen spektralen Kamm und bittet die blinde Mary, ihr Haar damit zu kämmen. Bringt mir den Kamm. Ich werde das Geisterhaar darin auflesen, das ich für den Faden brauche.\n\nUnd seid vorsichtig, denn dunkle Wesen treiben sich nahe des Hauses herum...", sourceObjective = "Bringt den spektralen Kamm zur blinden Mary.", progress = "<Schluchz> Oh bitte seht mich nicht an! Ich habe diese Augen mit meinen eigenen Händen herausgerissen, aber ich spüre immer noch Euren Blick!\n\nIch sehe entsetzlich aus! Entsetzlich! Bitte seht weg!!", completion = "Was ist das? Ein Kamm? Er ist wunderschön! Und er gleitet durch mein Haar, als wäre es gar nicht so furchtbar verfilzt und widerspenstig wie es ist.\n\nOh, hätte ich doch nur einen Spiegel...", sourceObjectiveStatus = "unverified-source-field" }
quests[26653] = { id = 26653, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung aus Dunkelhain", description = "Ach, was soll ich armer, alter Mann nur machen? Ich brauche einige Vorräte aus Dunkelhain, aber das Dorf ist so weit weg und ich bin so alt und schwach... ich würde die Reise niemals überstehen.\n\nKönnt Ihr nach Dunkelhain reisen und mir etwas Geisterhaarfaden mitbringen? Den bekommt Ihr im Haus von Madame Eva am Dorfplatz von Dunkelhain.", sourceObjective = "Sprecht mit Madame Eva in Dunkelhain.", completion = "So, Ihr braucht also Geisterhaarfaden, hm? Ich habe leider keinen mehr auf Lager, aber ich kann Euch welchen herstellen - wenn Ihr mir das Geisterhaar besorgt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26654] = { id = 26654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr mit dem Kamm", description = "NEIN!!!!!\n\nNehmt ihn weg, nehmt diesen Kamm weg!\n\nIch bin ein Monster und niemand wird mich jemals wieder für schön halten!", sourceObjective = "Bringt den Geisterhaarkamm zu Madame Eva nach Dunkelhain.", progress = "Ich kann spüren, dass Ihr die blinde Mary getroffen habt. Habt Ihr auch meinen Kamm?", completion = "Damit kann ich eine Rolle Geisterhaarfaden herstellen und es bleiben sogar noch einige Haare übrig. Hier habt Ihr einige Münzen für diese zusätzlichen Haare.", sourceObjectiveStatus = "unverified-source-field" }
quests[26655] = { id = 26655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abliefern des Fadens", description = "Hier ist Euer Faden, {name}. Man kann tausend Dinge damit machen, zum Beispiel böse Geister binden oder leblose Dinge mit Leben erfüllen.", sourceObjective = "Bringt den Geisterhaarfaden zu Calvinius in seinem Turm im Bettlerschlupfwinkel.", progress = "Ich brauche den Geisterhaarfaden, um ihn quer über meine Tür und meine Fenster zu spannen. Das hält unliebsame Geister fern. Habt Ihr ihn für mich besorgt?", completion = "Wunderbar! Das ist gerade richtig...\n\nHier, bitte, mein guter {name}, nehmt dies als Bezahlung für Eure ehrenhafte Tat.", sourceObjectiveStatus = "unverified-source-field" }
quests[26656] = { id = 26656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immer. In. Bewegung. Bleiben.", description = "Als Todesschwinge kam, sind die Steindrachen zu ihm geschwärmt. In seiner Abwesenheit fehlt ihnen jegliche Bestimmung. Sie streifen durch die Gegend und fressen unseresgleichen.\n\nIch habe Dutzende von opalschimmernden Wächtern gebunden, aber ich kann sie nicht aus der sicheren Deckung führen. Ich brauche jemanden, der schneller ist, und ich glaube, Ihr seid genau richtig für diese Aufgabe.\n\nFührt sie am Boden Richtung Therazanes Thron im Osten. Einige werden es sicher nicht schaffen, aber solange Ihr nicht stehenbleibt, solltet Ihr einige von ihnen zu unseren Truppen führen können.", sourceObjective = "Hetzt mindestens 5 opalschimmernde Wächter nach Osten aus dem Bleichen Hort hinaus, zum Steinkreis in der Nähe von Therazanes Thron.", completion = "Gut gemacht. Ich habe viele Stärken, aber Schnelligkeit gehört nicht dazu.", sourceObjectiveStatus = "unverified-source-field" }
quests[26657] = { id = 26657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein harter Fall", description = "Steindrachen lassen sich nur von Stärke beeindrucken. Wenn wir sie ausreichend bestraft haben, werden sie sich unserem Willen unterwerfen.\n\nIch habe eine Vielzahl meiner stärksten Riesen auf die Felder im Westen geschickt. Sie werden die Drachen zu Boden befördern. Ihr kümmert Euch dann darum, dass sie sich nach ihrem Fall nicht wieder in die Lüfte schwingen.", sourceObjective = "Tötet 6 Steindrachen.", completion = "Offensichtlich nicht nur schnell. In Euch scheint Einiges zu stecken.\n\nGut gemacht, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26658] = { id = 26658, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerbrechliche Werte", description = "Jetzt ist es an der Zeit, die Aufmerksamkeit der Brutmutter zu erregen. Dazu benötigen wir einen Hammer, den die Troggs während der Opferzeremonie für sie benutzen.\n\nSucht die Bestienzähmer der Steintroggs, die im südlichen Teil des Bleichen Horts versuchen, Basilisken zu zähmen. Einer von ihnen trägt einen Hammer bei sich.", sourceObjective = "Beschafft einen Mauerhammer.", progress = "Konntet Ihr einen Hammer finden?", completion = "Wunderbar.\n\nJetzt werden wir den Steindrachen einen Schlag verpassen, den sie in den nächsten hundert Jahren nicht vergessen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26659] = { id = 26659, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachhallender Schlag", description = "Ihr werdet einen Resonanzkristall am westlichen Rand des Bleichen Horts finden. Schlagt mit dem Hammer darauf, dann wird die Brutmutter kommen.\n\nMacht Euch für einen Kampf bereit. Ich werde dort sein, um Euch zu helfen, aber sie wird sich nicht leicht geschlagen geben.", sourceObjective = "Besiegt Aeosera.", progress = "Diese Brutmutter nimmt die Steindrachen seit fast 300 Jahren unter ihre Fittiche. Sie ist recht stark, sogar für einen Steindrachen.", completion = "Beeindruckend, Fleischling. Ihr seid fähiger, als ich ursprünglich angenommen hatte.\n\nIch werde diese Einschätzung auch der Steinmutter übermitteln.", sourceObjectiveStatus = "unverified-source-field" }
quests[26660] = { id = 26660, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zombiesaft", description = "Ich brauche eine Flasche eines bestimmten Schnapses, und zwar Zombiesaft. Schankwart Smitts aus der Taverne \"Zum Roten Raben\" in Dunkelhain sollte welchen haben.\n\nUnd bitte sputet Euch, {name}. Die Nächte sind kalt und ich brauche den Schnaps, um meine Adern wieder mit Feuer zu erfüllen!", sourceObjective = "Sprecht mit Schankwart Smitts.", completion = "Ihr braucht etwas Zombiesaft, wie? Hmm, das Zeug ist ziemlich stark - ich werde nicht oft danach gefragt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26661] = { id = 26661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Sammeln von Faulblüten", description = "Wenn Ihr mir einige Fäulnisblüten bringt, kann ich Zombiesaft für Euch brauen.\n\nFäulnisblüten wachsen an seltsamen Orten. Sie wachsen besonders gut auf Dingen, die tot sind. Im Dämmerwald gibt es jede Menge davon!\n\nIch habe einige im Friedhof \"Stille Gärten\" gesehen. Sucht in der Nähe der Gräber... aber achtet auf die Toten, die dort umherwandern.", sourceObjective = "Sammelt 5 Fäulnisblüten auf dem Friedhof \"Stille Gärten\".", progress = "Hallo, {name}. Habt Ihr mir Fäulnisblüten gebracht?", completion = "Gut, Ihr habt die Fäulnisblüten gefunden.\n\nIch werde etwas Zombiesaft zubereiten... aber Vorsicht, das ist starkes Zeug.", sourceObjectiveStatus = "unverified-source-field" }
quests[26662] = { id = 26662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Mannschaft der Trümmerflut", description = "Auf den Karten wird eine Gruppe namens Mannschaft der Trümmerflut erwähnt. Der Name ist Euch nicht bekannt, obwohl Ihr schon von einigen anderen neuen Bukanieren gehört habt.\n\nBesucht sie doch mal und findet heraus, was sie wissen.", sourceObjective = "Sprecht mit Long John Copper auf der Maid im Glück, Shawn Stooker dem Koloss auf der Purpurschleier und der klagenden Mary Smitts auf der Springflut.", sourceObjectiveStatus = "unverified-source-field" }
quests[26663] = { id = 26663, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versenkung aus dem Inneren", description = "Der Angriff auf Beutebucht steht kurz bevor. Kehrt rasch nach Beutebucht zurück und informiert den Baron.\n\nSo lange Ihr bei den Piraten noch angesehen seid, wäre es aber gut, wenn Ihr deren Vorräte sabotieren würdet. Die Piraten bewahren die meisten ihrer Vorräte unter Deck auf. Sie sind auf die ganze Flotte verteilt.", sourceObjective = "Sabotiert das Fass mit Grog, das Fass mit Schießpulver und die Kiste mit Kanonenkugeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[26664] = { id = 26664, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meutereimacher", description = "Bevor Ihr nach Beutebucht zurückkehrt, solltet Ihr alles tun, um die Blutsegelbukaniere zu schwächen. Leider ist es Euch selbst als Kapitän verboten, andere Bukaniere kaltblütig zu töten. Das darf nur ein Flottenmeister.\n\nAllerdings dürft Ihr Meuterer zu Tode bringen... und Meuterei lässt sich nur schwer widerlegen.\n\nApropos, diese Blutsegelkorsaren, die auf den untersten Decks der Schiffe herumhängen, benehmen sich in letzter Zeit wirklich sehr verdächtig...", sourceObjective = "Beschuldigt 9 Korsaren der Blutsegel der Meuterei und tötet sie dann.", sourceObjectiveStatus = "unverified-source-field" }
quests[26665] = { id = 26665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf der Beute", description = "Ihr habt den Eindruck, dass Ihr genug Schaden angerichtet habt. Ihr kennt außerdem die Schlachtpläne der Blutsegelbukaniere. Ihr habt alles getan, um das Euch Baron Revilgaz gebeten hat.\n\nEs ist Zeit, den Piratenhut an den Nagel zu hängen und nach Beutebucht zurückzukehren. Der Moment der Schlacht naht.", sourceObjective = "Meldet Euch bei Baron Revilgaz in Beutebucht am Schlingendornkap.", completion = "Die Trümmerflutler!? Ich dachte, die wären seit JAHREN tot und vergessen!\n\n<Revilgaz hört angestrengt zu, während Ihr ihm die zusammengetragenen Informationen weitergebt.>\n\nDas ergibt einen Sinn. Und es sind keine guten Neuigkeiten. Die Mannschaft der Trümmerflut sind ernstzunehmende Gegner und wenn sie wieder so viele sind, wie damals, als sie verschwanden, steht uns ein schwerer Kampf bevor.", sourceObjectiveStatus = "unverified-source-field" }
quests[26666] = { id = 26666, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Legende von Stalvan", description = "Ich bin hier, weil mein Bruder Stalvan, den ich seit Jahren nicht gesehen habe, mir einen Brief geschickt hat. Als ich hier eintraf, sagte man mir, er sei tot...\n\nDie ganze Stadt weigert sich, mir mehr zu erklären. Sie reagieren misstrauisch und ängstlich, wenn ich seinen Namen erwähne. Als ob ich mich nicht selbst schon so fühlen würde!\n\nIch habe Angst vor dem, was passieren könnte, wenn mein Ärger und mein Frust zunehmen. Bitte helft mir, der Sache auf den Grund zu gehen. Fragt Amtmann Daltry nach allen Informationen, die er über meinen Bruder besitzt.", sourceObjective = "Sucht Amtmann Daltry im Rathaus von Dunkelhain auf.", completion = "Kann ich Euch helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[26667] = { id = 26667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die gestohlenen Briefe", description = "Ihr wollt etwas über Stalvan wissen...\n\nIhr seid nicht <der/die> erste, wisst Ihr das? Fremde kommen ab und zu hier durch und fragen nach ihm. Immer nur Fremde. Alle, die hier leben, wissen es besser.\n\nWie dem auch sei, Ihr habt Pech. Die Hälfte meiner Archive ist weg. Wilde Worgen sind vor ein paar Nächten ins Rathaus eingebrochen und haben alles in Stücke gerissen. Die Dokumente, nach denen Ihr sucht, sind mittlerweile wahrscheinlich in ganz Schattenhain verstreut, tief in den Wäldern im Westen. Sind die Suche nicht wert, wenn Ihr mich fragt.", sourceObjective = "Findet das Bündel zerrissener Briefe in Schattenhain.", progress = "Ernsthaft, mein Herr, ich will keinen Ärger...", completion = "Beim Licht... Ihr habt sie tatsächlich geholt?\n\nIch bin schockiert. Ich sollte mich wohl bei Euch dafür bedanken, dass Ihr sie in die Archive zurückgebracht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26668] = { id = 26668, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Detonation", description = "Der Sprengstoff, den Ihr angebracht habt, ist hochexplosiv, {name}. Wenn ich diesen Knopf am Marschgepäck der Kompanie Bravo drücke, wird das ganze Tal in einem gigantischen Feuerball des Todes vergehen.\n\nWisst Ihr was? Ich glaube, die Ehre gebührt Euch. Die ganze harte Arbeit ist schließlich an Euch hängen geblieben.\n\nBereit?", sourceObjective = "Sprengt Renders Tal in die Luft.", completion = "Habt Ihr gesehen, wie die Orcs explodiert sind? SO MACHEN WIR DAS IN DER KOMPANIE BRAVO! Lasst uns mit dem Rest dieser Clowns aufräumen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26669] = { id = 26669, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In einer dunklen Ecke", description = "Wenn es Euch wirklich ernst ist, helfe ich Euch, {name}. Ich weiß, wo die anderen Dokumente sein müssen. Ich habe zu viel Angst, um etwas zu unternehmen.\n\nEs gibt nur wenige Orte, an denen sich diese furchtbaren Schrecken der Nacht versammeln, wenn sie nicht gerade den Wald durchstreifen. Einer davon ist der Verrottende Obstgarten im Süden. Sie benutzen die Gebäude als Schlupfwinkel. Wenn sie die Dokumente nicht einfach gefressen haben, werdet Ihr sie wahrscheinlich dort finden... aber ich wette, dass Ihr ihre Verstecke gründlich durchsuchen müsst.", sourceObjective = "Durchsucht den Verrottenden Obstgarten nach der zerrissenen Tagebuchseite.", progress = "Ihr seid in einem Stück zurückgekommen, wie ich sehe.", completion = "Mehr habt Ihr nicht gefunden?\n\nDas sind schlechte Nachrichten...", sourceObjectiveStatus = "unverified-source-field" }
quests[26670] = { id = 26670, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rolands Verdammnis", description = "Das ist nicht alles...\n\nLasst es sein, {name}. Eure Suche kann Euch nur noch nach Rolands Verdammnis führen. Das ist eine Mine südlich der Stadt und der größte Worgenbau in ganz Dämmerwald. Niemand in Dunkelhain hat diesen Ort je lebend verlassen. Einige der Berichte, die ich hier habe, weisen daraufhin, dass diese Ungeheuer dort ihren Ursprung haben... wer weiß, welches Böse sich darin verbirgt?\n\nBitte gebt auf, {name}. Lasst uns die ganze Sache vergessen und nie wieder davon sprechen.", sourceObjective = "Sucht in Rolands Verdammnis nach den restlichen Seiten von Stalvans Tagebuch.", progress = "Ich sagte Euch doch, {name}, dass sich die Suche nicht lohnt...", completion = "Was, Ihr habt sie geholt?!\n\nIch weiß nicht, ob ihr mutig oder verrückt seid. Im Namen meiner Archive danke ich Euch jedoch erneut.", sourceObjectiveStatus = "unverified-source-field" }
quests[26671] = { id = 26671, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal von Stalvan Dunstmantel", description = "Ihr habt alles gefunden. Alles, bis auf die letzte Seite...\n\n...die ich hier habe. Seht mich nicht so an. Ihr werdet alles verstehen, wenn Ihr sie gelesen habt. Einige behaupten sogar, sie sei verflucht. Um ehrlich zu sein, war ich erleichtert, als die Worgen eingebrochen sind und die Seiten gestohlen haben!\n\nNehmt sie. Ach nein, nehmt alle. Ich danke Euch dafür, dass Ihr meine Archive wiederbeschafft habt, aber ich will nichts mehr mit der Sache zu tun haben. Lasst mich bitte in Ruhe.", sourceObjective = "Bringt die Legende von Stalvan zurück zu Tobias Dunstmantel.", progress = "Ihr seid wieder da! Habt Ihr etwas über meinen Bruder herausgefunden?", completion = "Ich kann Euch gar nicht genug danken... Ich hatte auf ein freudiges Wiedersehen gehofft, aber je mehr ich erfahre, desto sehnlicher wünsche ich mir, ich hätte nie gefragt.\n\nAber ich muss es wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26672] = { id = 26672, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wahrheit auf den Grund gehen", description = "Das kann nicht sein. Mein Bruder hatte einen starken Willen, aber eine solche Boshaftigkeit... so etwas brutales, blutiges, krankes...\n\n<Tobias hebt eine Hand vor sein Gesicht und wendet den Blick ab.>\n\nIch brauche Antworten. Ich muss wissen, wie mich dieser Brief erreicht hat. Ich muss wissen, ob Stalvan das wirklich getan hat.\n\nIch muss wissen, warum...\n\nNehmt meinen Ring, {name}. Bringt ihn zu Madame Eva. Diese Frau ist eine Anhängerin der alten Künste und verbirgt das auch nicht... es ist vielleicht verrückt, aber ich bin soweit, alles zu versuchen.", sourceObjective = "Bringt Madame Eva den Familienring der Dunstmantels.", progress = "Welche dunklen Stimmen haben Euch an meine Tür gebracht, {class}?", completion = "Wie interessant. Es ist lange her, dass ich einen solchen Ring gesehen habe...", sourceObjectiveStatus = "unverified-source-field" }
quests[26673] = { id = 26673, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE - BREADCRUMB#", description = "Das kann nicht sein. Mein Bruder hatte einen starken Willen, aber eine solche Boshaftigkeit... so etwas brutales, blutiges, krankes...\n\n<Tobias hebt eine Hand vor sein Gesicht und wendet den Blick ab.> Ich brauche Antworten. Ich muss wissen, wie mich dieser Brief erreicht hat. Ich muss wissen, ob Stalvan das wirklich getan hat.\n\nIch muss wissen, warum...\n\nNehmt meinen Ring, {name}. Bringt ihn zu Madame Eva. Diese Frau ist eine Anhängerin der alten Künste und verbirgt das auch nicht... es ist vielleicht verrückt, aber ich bin soweit, alles zu versuchen.", sourceObjective = "Bringt Madama Eva den Familienring der Dunstmantels.", sourceObjectiveStatus = "unverified-source-field" }
quests[26674] = { id = 26674, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunstmantels Rache", description = "Leider kann ich Tobias nicht die Antworten geben, nach denen er sucht. Aber ich kann Euch bei der Suche nach der einzigen Person helfen, die das vermag...\n\nStalvan Dunstmantel.\n\nBringt den Ring zum Anwesen der Dunstmantels in den Wäldern im Osten, wo Stalvans Leiche begraben wurde. Tretet ein und haltet den Ring hoch. Wenn das Licht des abnehmenden Mondes durch den Ring scheint, werden die Geister Euren Ruf erhören.\n\nVergesst eines nicht, {name}. Die Fragen der Lebenden spenden oft mehr Trost als die Antworten der Toten.", sourceObjective = "Benutzt den Familienring der Dunstmantels im Anwesen der Dunstmantels östlich der Stadt.", completion = "Meister Harris hatte vielleicht sogar recht. Es wäre besser gewesen, wenn ich die Vergangenheit hinter mir gelassen hätte.\n\nIch habe jetzt ein neues Leben. Ob es das eines Ungeheuers oder das eines Mannes ist, hängt von mir ab.\n\nEuch kann ich nicht genug für Eure Unterstützung danken, egal, zu welchem Ergebnis sie geführt hat. Bitte nehmt dies zusammen mit meinem Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[26675] = { id = 26675, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wert des Vertrauens", description = "Die Probleme dieser Welt scheinen nie zu vergehen. Sie verschieben und verändern sich, bilden sich neu, aber sind doch stets vorhanden.\n\nDer Wind hat uns Gerüchte über einen Verräter in unserer Mitte zugeflüstert. Wir haben eine unserer besten Schildwachen mit den Nachforschungen betraut, doch sie wurde tot aufgefunden. Ich habe das zu verantworten, da ich annahm, der Verräter wisse nichts von unserem Vorgehen... Ich handelte unüberlegt, und sie musste den Preis für meine Dummheit bezahlen.\n\nIch brauche ein fremdes Gesicht, um die Spur wieder aufzunehmen. Jemanden, den die Leute in der Stadt nicht kennen. Das ist eine gefährliche Bitte. Werdet Ihr mir helfen?" }
quests[26676] = { id = 26676, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saftlieferung", description = "Hier habt Ihr Euren Zombiesaft...\n\n... aber passt mir mit dem Zeug auf. Es ist stark genug, um die Toten zu erwecken!", sourceObjective = "Bringt Calvinius den Zombiesaft im Bettlerschlupfwinkel.", progress = "Ich brauche den Zombiesaft, um mich in diesen dunklen, kalten Nächten warm zu halten. Habt Ihr ihn für mich besorgt?", completion = "Seid tausendmal bedankt, {name}! Ihr erwärmt das Herz eines alten Mannes mit Eurer Naiv... ääh... mit Eurer Freundlichkeit!\n\nHier, bitte schön, mein Freund, nehmt dies als ein Zeichen meiner Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[26677] = { id = 26677, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ghulbildnis", description = "Es ist ein Wunder, dass die lebenden Toten mich hier draußen am Stadtrand noch nicht gefressen haben! Erst gestern hat eine Horde Ghule beinahe die Wände meines Turms eingeschlagen!\n\nIch möchte ein Abbild herstellen - eine Art \"Vogelscheuche\" für Ghule. Dafür benötige ich einige Ghulrippen. Rund um das Anwesen der Dunstmantels, nördlich von Dunkelhain, wandern stinkende Leichname umher, bei denen ihr jede Menge finden solltet...\n\nBesorgt mir die Rippen, dann werde ich Euch mit einigen Münzen belohnen.", sourceObjective = "Sammelt 7 Ghulrippen von Stinkenden Leichnamen auf dem Anwesen der Dunstmantels.", progress = "Wahrscheinlich würdet Ihr auch zahlreiche Rippen in Rabenflucht finden, aber wer will schon spät nachts so weit laufen...", completion = "Ah, danke! Die sind genau richtig für mein Vorhaben.", sourceObjectiveStatus = "unverified-source-field" }
quests[26678] = { id = 26678, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doppelrum", description = "<Baron Revilgaz seufzt.> Ich habe zwar Teile von Firallons Plan erahnt, aber trotzdem sind wir nicht auf die beiden Frontalangriffe der Blutsegel und der Trümmerflut vorbereitet. Wir werden ein kleines Wunder brauchen, um Beutebucht an diesem Tag zu halten.\n\nIch habe ein Fass Doppelrum in meinem Quartier. Steigt die Treppe drei Stockwerke hinunter und nehmt die erste Tür zu Eurer Rechten. Ihr könnt die Warnungen auf dem Fass ignorieren... sie sollten Eure geringste Sorge sein.", sourceObjective = "Findet Baron Revilgaz' Fass mit Doppelrum in Beutebucht.", completion = "Das muss der Doppelrum sein. Ihr schenkt Revilgaz ein Glas ein und überlegt, ob Ihr Euch auch eins gönnen sollt...", sourceObjectiveStatus = "unverified-source-field" }
quests[26679] = { id = 26679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kehrt zu Revilgaz zurück", description = "Draußen geschieht etwas. Sind die Blutsegelbukaniere etwa schon hier?\n\nBringt Revilgaz seinen Doppelrum. Schnell.", sourceObjective = "Bringt Baron Revilgaz in Beutebucht den Doppelrum.", progress = "Ratet mal, wer aufgetaucht ist, während Ihr weg wart?", completion = "<Der Baron leert rasch seinen Kelch.>\n\nAH! Das tut gut, {name}. Aber zurück zum Geschäft. Ich glaube, dass Ihr und ich eine Stadt zu retten haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[26680] = { id = 26680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogerdiebe", description = "Vor ein paar Wochen wurde ich von einer Bande Ogern angegriffen, als ich draußen Kräuter sammelte, ziemlich weit von meinem Haus entfernt. Ich lief davon und musste eine Kiste mit wertvollen Werkzeugen und Kräutern zurücklassen.\n\nNachdem sie mich vertrieben hatten, stolzierten die Oger zurück zum Ogerhort im südlichen Dämmerwald. Ich bin mir sicher, dass meine Kiste irgendwo in der Nähe des Hügels sein muss.\n\nBitte, {name}, beschafft mir diese Kiste wieder, denn sie fehlt mir sehr.", sourceObjective = "Bringt Calvinius' Kiste zu Calvinius.", progress = "Habt Ihr meine Kiste? Wenn ja, dann gebt sie mir schnell, ich bitte Euch!", completion = "Dank dem Toten- ähm, ich danke EUCH, {name}! Ihr habt Euch Eure Belohnung mehr als verdient.\n\nAha! Oh Glück! Glückliche Nächte können kommen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26681] = { id = 26681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Brief für den Bürgermeister", description = "Bringt diese Nachricht zu Ello Schwarzhaupt, dem Bürgermeister von Dunkelhain.\n\nEr und ich sind alte Freunde und wenn er den Zettel liest und herausfindet, was Ihr für mich getan habt... dann freut er sich bestimmt genauso sehr, wie ich das tue! Hahahaha!", sourceObjective = "Bringt Calvinius' Brief zu Ello Schwarzhaupt, dem Bürgermeister von Dunkelhain.", progress = "Ein Brief? Worum geht es bei dieser Geschichte?", completion = "<Ello sieht sich den Brief an und sein Gesicht verliert augenblicklich alle Farbe.>\n\nIhr Narr! Ihr habt uns alle verdammt!", sourceObjectiveStatus = "unverified-source-field" }
quests[26682] = { id = 26682, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine torkelnde Bedrohung", description = "Düstermarschen ist das Gebiet der Horde, {name}. Die Menschen haben ihre kleine Insel und ihre heißgeliebte Sandbank, aber die Sümpfe gehören uns.\n\nIrgendwann werden wir diese Pattsituation mit den Menschen auch noch klären. Doch erst einmal müssen wir unser eigenes Gebiet beherrschen. Die Moderrankenmorastbestien im Norden tauchen aus dem Sumpf auf und greifen jedes Lebewesen an, das sich ihnen nähert. Wenn wir diese Marschen beherrschen wollen, dann darf sich unser Land nicht gegen uns wenden!\n\nTötet die Morastbestien, wenn Ihr der Horde dienen wollt. Man wird Euch belohnen.", sourceObjective = "Tötet 7 Moderrankenkrabbler oder Moderrankenwüteriche im Sumpf nördlich von Brackenwall.", completion = "Gut gemacht, {name}. Nun können wir uns hier auf die größeren Bedrohungen konzentrieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[26683] = { id = 26683, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seht zu den Sternen", description = "Mein Gnomenfreund Zinken hat versprochen, mir beim Bau eines Geräts zu helfen, mit dem man zu den Sternen blicken kann. Laut Zinkens Blaupause muss ich zuerst eine Möglichkeit finden, das Licht zu reflektieren.\n\nIch erinnere mich an eine Frau namens Mary, die in dieser Gegend rasch bekannt wurde, weil sie stets einen Handspiegel bei sich trug. Könntet Ihr vielleicht Mary suchen und sie fragen, ob sie uns eine reflektierende Oberfläche für dieses Projekt leihen würde? Ich glaube, sie lebte früher im südlichen Dämmerwald...", sourceObjective = "Findet Mary und überredet sie, eine reflektierende Oberfläche für Viktoris Projekt abzugeben.", completion = "Ja, das stimmt. Ich besaß einmal einen Spiegel.", sourceObjectiveStatus = "unverified-source-field" }
quests[26684] = { id = 26684, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der irrsinnige Ghul", description = "Der Handspiegel war einer meiner wertvollsten Schätze, bis... zu dem Zwischenfall. Danach warf ich ihn hinter die Scheune. Dort hinten trieb ein irrsinniger Ghul sein Unwesen. Vielleicht hat er ihn aufgehoben. Angeblich halten sich diese teuflischen Bestien im Friedhof \"Stille Gärten\" auf.", sourceObjective = "Erbeutet Marys Handspiegel von dem irrsinnigen Ghul.", progress = "Ich habe Zinken die Anfänge unserer Sternenguckermaschine gezeigt. Er war beeindruckt. Habt Ihr ein reflektierendes Gerät gefunden?", completion = "Wie wunderbar! Das wird sehr gut funktionieren. Vielen Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[26685] = { id = 26685, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feines Glas", description = "Jetzt brauche ich nur noch einen Gegenstand, dann ist das Gerät komplett. Laut Zinkens Blaupause fehlt eine Art Linse. Die einzige Linse, die ich kenne und die groß genug wäre, wird nur schwer zu beschaffen sein.\n\nEs gibt einen Oger namens Zzarc'Vul, der auf dem Hügel im südlichen Dämmerwald lebt. Wenn es Euch gelingen würde, mir sein Monokel zu bringen, könnte ich das als Linse verwenden!", sourceObjective = "Tötet Zzarc'Vul auf dem südlichen Ogerhügel in Dämmerwald und erbeutet sein Ogermonokel.", progress = "Konntet Ihr Zzarc'Vul davon überzeugen, uns sein Monokel für unser Experiment zu leihen?", completion = "Endlich! Die Sternenguckermaschine ist komplett! Danke, {name}. Jetzt kann ich meine Forschungen fortsetzen...", sourceObjectiveStatus = "unverified-source-field" }
quests[26686] = { id = 26686, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wandelnde Knochen", description = "Ihr werdet Euch mit noch fauligeren Untoten herumschlagen müssen, {name}.\n\nDer Friedhof \"Stille Gärten\" etwas weiter südlich der Stadt ist ein Ort, an dem man sich nachts nicht blicken lassen sollte. Die Knochen, die sich dort aus dem Boden erheben, sind klug genug, um sich daran zu erinnern, wie man eine Axt schwingt oder einen Zauber wirkt.\n\nIch muss wohl nicht erklären, wie gefährlich sie das macht. Seid vorsichtig, aber denkt daran, dass das Volk von Dunkelhain leiden wird, wenn Ihr scheitert.", sourceObjective = "Kommandantin Althea Schwarzhaupt aus Dunkelhain möchte, dass ihr 5 Skelettkrieger und 5 Skelettmagier vernichtet.", completion = "Das Volk von Dunkelhain dankt Euch, {name}. Ihr habt Euch als starker Verbündeter der Nachtwache erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26687] = { id = 26687, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkung aus Theramore", description = "Hawthorne tot... mein eigener Sohn ermordet... die Lage im Brachland ist außer Kontrolle, {name}.\n\nIch werde das Kommando über die Triumphfeste übernehmen und versuchen, für Ruhe zu sorgen. Doch dazu benötige ich Verstärkung. Verstärkung, die man mir in Theramore schon vor Wochen versprochen hat!\n\nReist nach Theramore in den Düstermarschen und blast Hauptmann Garran Vimes den Marsch. Welchen Zweck erfüllt diese verdammte Straße durch den Sumpf, wenn Soldaten und Material trotzdem nicht kommen?", sourceObjective = "Reist zur Insel Theramore in den Düstermarschen und sprecht mit Hauptmann Garran Vimes in der Hauptkaserne.", completion = "Was jetzt, Soldat?\n\nVerstärkung? Für das Brachland? Seit Monaten stecken wir Soldaten und Vorräte dort hinein!\n\nMuss jemand Doppelzopf an den Angriff auf Nordwache erinnern? Unsere Verluste an der Ehrenwacht? Was ist mit den Soldaten geschehen, die ich zur Triumphfeste geschickt habe? Wir können niemanden mehr entbehren!\n\n{name}, wenn Ihr uns wirklich helfen wollt, dann konzentriert Euch auf die Lage hier in den Düstermarschen. Wir schlagen uns mit Deserteuren und den Übergriffen der Horde herum... wir können Hilfe gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26688] = { id = 26688, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worgen in den Wäldern", description = "Es scheint, als würden dunkle Dinge unaufhaltsam in den Dämmerwald gezogen. Meister Treuwein hat sich der Aufgabe verschrieben, das Böse und die Ketzerei zu vertreiben. Dank unserer Anstrengungen lebt das Volk von Dunkelhain in Sicherheit.\n\nIhr glaubt, Ihr seid würdig, Euch unserer Gruppe anzuschließen?\n\nEinst dachte ich wie Ihr. Die Selbstzufriedenheit der Wache hatte mich meiner Illusionen beraubt und so schloss ich mich Meister Treuwein an. Wenn Ihr Euch beweisen möchtet, so kann dies nicht durch Worte geschehen.\n\nMesst Eure Fertigkeiten an den Worgen der Nachtheuler im Schattenhain. Wir werden sehen, ob Ihr in der Lage seid, es mit diesen Monstern aufzunehmen.", sourceObjective = "Tötet 7 Worgen der Nachtheuler im Schattenhain.", completion = "Ich bin beeindruckt, {name}. Es scheint, als wäret Ihr durchaus fähig, Euch im Kampf zu behaupten. Vielleicht können wir ja eine Aufgabe für Euch finden, die jemanden mit Euren Fähigkeiten etwas mehr herausfordert.", sourceObjectiveStatus = "unverified-source-field" }
quests[26689] = { id = 26689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Verrottende Obstgarten", description = "Die Worgenplage erstreckt sich über Schattenhain hinaus. Im Süden, ganz am Rand von Dunkelhain, liegt der Verrottende Obstgarten. Dort findet man noch wildere Bestien.\n\nDie Worgen dort sind listiger, {name}, aber ebenso grausam und böse. Sie beschwören verdorbene Schatten, die ihre Feinde aus der Entfernung in Stücke reißen. Geht zum Verrottenden Obstgarten und tötet die Schattenwirker, um die Stadt zu beschützen!", sourceObjective = "Tötet 10 Schattenwirker der Nachtheuler im Verrottenden Obstgarten.", completion = "Ihr habt Euch gut gegen die Schattenwirker geschlagen, {name}. Doch selbst heutzutage, Jahre nach ihrem ersten Auftauchen, scheint es mehr als genug zu geben, um die von uns Getöteten zu ersetzen.\n\nIch setze all meine Hoffnung auf Meister Carevin. Er wird dem Problem sicherlich auf den Grund gehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26690] = { id = 26690, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faulig und besudelt", description = "Eure früheren Leistungen haben mich davon überzeugt, dass Ihr Euch den härtesten Worgen stellen solltet, die diese Wälder heimsuchen.\n\nDie Faulreißer und die Besudelten haben sich als die gefährlichsten der Worgen, die hier eine neue Heimat gefunden haben, erwiesen. Sie haben sich in der Nähe einiger Höhlen und in der Mine im Süden niedergelassen.\n\nSchon aus der Ferne kann man das Licht ihrer Lagerfeuer sehen...", sourceObjective = "Tötet 8 Faulreißer der Nachtheuler und 8 besudelte Nachtheuler in Rolands Verdammnis.", completion = "{name}, um ehrlich zu sein, hatte ich nicht damit gerechnet, dass Ihr so weit kommen würdet, aber Ihr seid offensichtlich ein {class}, den man im Auge behalten sollte. Solltet Ihr Euch also auch offiziell Meister Treuweins Kampf anschließen wollen, werde ich Euch gern ein Empfehlungsschreiben aufsetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26691] = { id = 26691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worgen in den Wäldern", description = "Bitte sehr, {name}. Bringt diese Nachricht zu Meister Treuwein.\n\n<Er zieht rasch ein Stück verblichenes Pergament hervor und reicht es Euch.>\n\nWenn es nur noch mehr wie Euch gäbe, dann wären wir bald zahlreicher als die Nachtwache! Vielleicht könnten wir dann das Werk vollenden, das wir wenigen begonnen haben.", sourceObjective = "Bringt Calors Notiz zu Jonathan Treuwein.", progress = "Ja, was ist? Beeilt Euch, ich habe dringende Aufgaben.", completion = "Entschuldigt den frostigen Empfang, {name}, aber Euch ist sicher klar, dass ich ein äußerst vielbeschäftigter Mann bin. Wie ich sehe, habt Ihr Calor so sehr beeindruckt - und ich kann Euch versichern, dass das nicht oft vorkommt - dass er Euch empfohlen hat.\n\nEs sind einige abstoßende Gestalten unterwegs, {name}, und ich kann die Hilfe von allen gebrauchen, die sich bewiesen haben. Wir kämpfen gegen Dämonen, die Untoten und alle, die ihnen helfen. Seid wachsam, seid vorsichtig und vertraut niemandem, der unseren Kampf nicht unterstützt.\n\nRuhm unter dem Licht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26692] = { id = 26692, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausrottung der Schattenfelle", description = "Da von den Schwarzfelsorcs südlich vom Immerruhsee nichts außer Asche und Kohle übrig geblieben ist, können wir unsere Aufmerksamkeit auf die Armee der Schattenfellgnolle im Galardelltal unmittelbar nördlich von hier richten.\n\nGeht hinaus und bringt sie alle um, {name}! Beginnt mit der Operation: Ausrottung, Soldat. Für die Kompanie Bravo und für die Allianz!", sourceObjective = "Tötet 20 beliebige Gnolle der Schattenfelle.", sourceObjectiveStatus = "unverified-source-field" }
quests[26693] = { id = 26693, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der dunkle Turm", description = "Wir hatten Glück. Die Bewohner dieses Tals haben uns wichtige Informationen gegeben. Die beiden hinter uns, die Ranthals, haben mir berichtet, dass die Gnolle im Galardelltal von einem mächtigen Magus im Turm von Ilgalar kontrolliert werden. Das Problem ist, dass dieser Turm durch ein magisches Kraftfeld versiegelt wird.\n\nAls erstes brauchen wir den Schlüssel, damit Ihr ins Innere vorstoßen könnt. Fangor, der Gnollgeneral, besitzt Eure Fahrkarte ins Innere. Tötet General Fangor und holt Euch den Schlüssel.\n\nIch melde mich.", sourceObjective = "Erbeutet den Schlüssel von Ilgalar.", sourceObjectiveStatus = "unverified-source-field" }
quests[26694] = { id = 26694, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Großmagus Doane", description = "<Das Marschgepäck der Kompanie Bravo vibriert.>\n\nGute Arbeit, Grünschnabel. Ich habe wichtige Informationen für Euch. Der Magus in dem Turm ist ein Mensch namens Doane. Der verdammte Verräter arbeitet für die Schwarzfelsorcs. Ich will seinen Tod.\n\nVerschafft Euch mit dem Schlüssel von Ilgalar einen Weg ins Innere des Turms. Arbeitet Euch bis zur Spitze vor und zeigt Doane, was die Kompanie Bravo mit Verrätern macht.\n\nKehrt zum Treffpunkt Schieferwindschlucht zurück, wenn die Tat vollbracht ist.\n\nKeeshan Ende und aus.", sourceObjective = "Tötet Großmagus Doane.", completion = "Er hat sich wegteleportiert? Und Dunkelflamme erwähnt? Was zur Hölle geht hier vor?\n\nLasst uns aufsatteln und diesen Unfug zu Ende bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26695] = { id = 26695, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Startvorbereitungen", description = "Ich habe eine Idee, die etwas Laufarbeit von Euch erfordert. Die Schwarzmeerräuber sind ein Kartell der Goblins. Deshalb haben sie Zugang zu jeder Menge Sprengstoff. Ich weiß sogar, dass unser alter Freund Narkk eine ganze Kiste hinten in seinem Laden in der Alten Hafenbehörde aufbewahrt.\n\nHolt sie Euch und bringt sie her, wenn sie noch nicht hochgegangen ist.", sourceObjective = "Besorgt Narkks Handbomben aus der Alten Hafenbehörde in Beutebucht.", progress = "Ihr lebt noch?", completion = "Ihr habt sie dabei! Ich glaube, so langsam dreht sich der Wind zu unserem Vorteil, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26696] = { id = 26696, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf von Kalimdor", description = "Sagt mal, Ihr habt nicht zufällig einen etwa so großen Fisch gesehen? Kurze Flossen? Hört auf den Namen Steve?\n\nEgal, ich such' einfach weiter.\n\nAber... es gibt einen anderen Grund, aus dem ich nach Beutebucht gekommen bin. Boss Krog, drüben in den Düstermarschen, sucht neue Arbeiter.\n\nWartet am Ende des Piers auf das nächste Schiff, dann fahrt nach Ratschet. Gazlowe sollte Euch von da aus weiterhelfen können.\n\nSteve? Steve!", sourceObjective = "Nehmt das Schiff von Beutebucht nach Ratschet und sprecht dort mit Gazlowe.", completion = "Ja, Was kann ich für Euch tun?", sourceObjectiveStatus = "unverified-source-field" }
quests[26697] = { id = 26697, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die letzte Reise der Trümmerflutpiraten", description = "Wir werden diesen Angriff nicht überstehen, wenn all diese Worgenpiraten von Norden in den Hafen einfallen. Zum Glück sieht es so aus, als wären sie nicht mit Kanonen bewaffnet. Wenn es uns gelingt, Euch aus dem Hafen zu bringen, könnt Ihr sie aus der Luft angreifen.\n\nIhr findet Kebok, den Assistenten des Windreitermeisters der Horde, gleich um die Ecke. Erklärt ihm, dass Ihr seinen mutigsten Windreiter benötigt.\n\nNehmt all die Handbomben mit, die Ihr tragen könnt. Ihr werdet sie brauchen, um die Landungsboote aufzuhalten!", sourceObjective = "Sprecht mit Kebok in Beutebucht und schwingt Euch auf einen tapferen Windreiter. Tötet dann mit den Handbomben 85 Crewmitglieder der Trümmerflutpiraten und zerstört 6 Landungsboote der Trümmerflutpiraten.", completion = "Ich hoffe, diese räudigen Hunde können schwimmen!\n\nMoment, das nehme ich zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[26698] = { id = 26698, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach Seehorn", description = "Als die Trümmerflutpiraten ankamen, griff Seehorn nach der ersten Waffe, die er in die Hände bekam und sprang von diesem Vorsprung. Ihr werdet ihn da unten finden. Wahrscheinlich schlägt er ein paar neue Löcher in diese Worgenschädel.\n\nHelft ihm. Um die Motivation kümmere ich mich von hier oben.", sourceObjective = "Meldet Euch bei Flottenmeister Seehorn in Beutebucht.", completion = "Ich hätte wissen sollen, dass die Trümmerflutpiraten noch leben und nichts Gutes im Schilde führen. Ich hatte sie schon vor Jahren abgeschrieben.", sourceObjectiveStatus = "unverified-source-field" }
quests[26699] = { id = 26699, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Abwehr der Trümmerflutpiraten", description = "Die Trümmerflutpiraten sind überall! Die Haudraufs von Beutebucht, die der Baron angeworben hat, haben einer solchen Überzahl nichts entgegen zu setzen.\n\nWährend Ihr dort unten seid, könntet ihr mir helfen, ein paar von ihnen los zu werden?\n\nWenn Ihr fertig seid, macht Euch nicht die Mühe wieder heraufzukommen. Ich werde wahrscheinlich ziemlich beschäftigt sein.", sourceObjective = "Tötet 10 Räuber der Trümmerflutpiraten in Beutebucht.", completion = "Wir dürfen nicht nachlassen, {name}. Wir können Beutebucht nicht viel länger halten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26700] = { id = 26700, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Maid im (Un)Glück", description = "Ich habe gehört, dass dieses Schiff hier Die Maid im Glück heißt. Wart Ihr nicht mal der Kapitän von diesem Kahn? Dann kennt Ihr Euch dort ja aus.\n\nDie Trümmerflutpiraten sind unsere Hauptsorge, aber wir können auch nicht einfach zusehen, während wir mit diesen Kanonen beschossen werden. Ergreift das Seil hinter mir und erledigt ein paar dieser wütend aussehenden Korsaren. Meldet Euch beim Baron, wenn Ihr fertig seid.", sourceObjective = "Tötet 8 Korsaren der Blutsegelbukaniere in Beutebucht.", completion = "Ein Angriff auf Eure ehemalige Besatzung...\n\nIhr seid wirklich ein echter Pirat geworden, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[26701] = { id = 26701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flug nach Brackenwall", description = "Hört mal, die Horde liegt mir nicht gerade am Herzen... aber andererseits hasse ich Euch auch nicht unbedingt.\n\nEuer Gold ist so gut wie das jedes Anderen.\n\nDieser zweiköpfige Oger und sein Fisch haben etwas Gold für Eure Reisespesen dagelassen. Ich glaube, die Person, die Ihr dort sucht, heißt Krog. Und die beste Art, dort hinzugelangen, ist unser Flugmeister Bragok. Er lässt Euch hinfliegen, wenn Ihr wollt. Dank Eures Freundes ist der Flug kostenlos.", sourceObjective = "Sprecht mit Bragok in Ratschet, um nach Brackenwall zu fliegen. Meldet Euch dann bei Krog.", sourceObjectiveStatus = "unverified-source-field" }
quests[26702] = { id = 26702, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flug nach Theramore", description = "Hört mal, die Allianz liegt mir nicht gerade am Herzen... aber andererseits hasse ich Euch auch nicht unbedingt.\n\nEuer Gold ist so gut wie das jedes Anderen. Manchmal besser.\n\nJeyne hat etwas Gold für Eure Reisespesen dagelassen. Ich glaube, die Person, die Ihr dort sucht, heißt Calia Hastings. Und die beste Art, dort hinzugelangen, ist unser Flugmeister Bragok. Er lässt Euch hinfliegen, wenn Ihr wollt. Dank Eures Freundes ist der Flug kostenlos.", sourceObjective = "Sprecht mit Bragok in Ratchet, um nach Theramore zu fliegen. Meldet Euch dann bei Calia Hastings.", completion = "Willkommen in Theramore.", sourceObjectiveStatus = "unverified-source-field" }
quests[26703] = { id = 26703, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Streicht die Blutsegel", description = "Dass der Sieg zum Greifen nah ist, haben wir fast allein Euch zu verdanken. Es bleibt jedoch noch eine letzte Aufgabe... tötet Flottenmeister Firallon.\n\nEin Großteil von Firallons Mannschaft scheint bereits tot zu sein, aber ich kenne den alten Seebären nur zu gut. Er ist noch nicht erledigt. Nein, er hat sich bestimmt in seiner Kajüte verbarrikadiert, um mit seinem Schiff unterzugehen.\n\nSprecht noch einmal mit Kebok. Er wird Euch einen Windreiter geben. Ich versuche den Kanonenbeschuss zu unterbrechen, während Ihr an Bord seid.", sourceObjective = "Sprecht mit Kebok in Beutebucht, lasst Euch einen Windreiter geben und tötet Flottenmeister Firallon.", completion = "{name}! Ihr seid wach! Wir haben Euch, kurz nachdem die letzten Angreifer den Schwanz eingezogen haben, im Hafen treiben sehen. Ihr habt uns eine Weile lang Sorgen gemacht...\n\nIch wollte mich noch bei Euch bedanken, {name}. Ihr habt uns die Informationen verschafft, die wir brauchten, um uns auf diesen Angriff vorzubereiten und uns geholfen, nicht nur die Blutsegelbukaniere, sondern AUCH die Trümmerflutpiraten abzuwehren. Wir in Beutebucht werden uns stets an Euren Namen erinnern.\n\nWir sind sehr stolz auf unsere Beute. Wollt Ihr die erste Wahl haben?", sourceObjectiveStatus = "unverified-source-field" }
quests[26704] = { id = 26704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE" }
quests[26706] = { id = 26706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endspiel", description = "Wir müssen dieses fliegende Kanonenboot loswerden, wenn unser Volk eine Chance auf Flucht haben möchte.\n\nSo lautet der Plan. In Kielwasser trieben sich früher einige sympathisierende Rebellen herum. Ich konnte eine beträchtliche Menge Sprengstoff aus einem unserer Lager besorgen.\n\nWir werden den Feind mit einer Kraft überrumpeln, die so klein ist, dass sie sich unentdeckt durch die Luft bewegen kann. Die Hippogryphen der Nachtelfen eignen sich perfekt dafür.\n\nTobias gibt Euch das Signal, wenn wir bereit sind.", sourceObjective = "Springt auf einen Hippogryphen, wenn Tobias Euch das Zeichen dazu gibt, und zerstört das Kanonenboot der Horde.", progress = "Es lohnt sich nur Risiken einzugehen, die Siege bringen, die es sich zu erringen lohnt.", completion = "Wir haben es geschafft, {name}. Wir haben die Evakuierung in die Wege geleitet. Wenn wir uns bald auf den Weg machen, sieht die Flotte der Verlassenen bald nur noch eine Staubwolke von uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[26707] = { id = 26707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine tödliche Rebe", description = "Ich brauche jede Menge Leichengras für Meister Harris' Gebräu. Es ist schwer zu kriegen, aber unsere Vorräte dürfen nicht abnehmen. Leichengras ist ziemlich hartes Zeug...\n\nDie Pflanze macht Euch fertig, wenn Ihr nicht aufpasst! Aber wenn Ihr trotzdem helfen wollt, dann werde ich Euch gern für alles bezahlen, das Ihr selbst gesammelt habt.\n\nIhr werdet jede Menge auf Yorgens Bauernhof im Südosten finden.", sourceObjective = "Sammelt 5 Stück Leichengras.", progress = "Habt Ihr das Leichengras?", completion = "Ich danke Euch, {class}... und ich bin sicher, dass die {race}, die durch den Trank, der daraus gebraut wird, vielleicht ihren Verstand zurückbekommen, Euch ebenfalls danken würden.", sourceObjectiveStatus = "unverified-source-field" }
quests[26708] = { id = 26708, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "AHHHHHHHHHHHH! AHHHHHHHHH!!!", description = "Ich bin hier, um Euch und der Kompanie Bravo bei der Beseitigung dieses Schlamassels zu helfen. Steigt in den Belagerungspanzer der Kompanie Bravo und räumt den Weg zu Keeshans Posten auf der anderen Seite des Tals, nördlich von hier, frei.\n\nDie Situation ist hochgradig gefährlich, Soldat. Den Schwarzfelsorcs ist Eure Position mittlerweile bekannt. Sie sind mit einer großen Streitmacht auf dem Weg zu Euch.\n\nEliminiert sie alle ohne Gnade. Wir sehen auf der anderen Seite. Möge das Licht Eurer Seele gnädig sein.", sourceObjective = "Tötet 200 Schwarzfelsorcs mit dem Belagerungspanzer der Kompanie Bravo.", completion = "Wir müssen uns nur noch um die Orcs kümmern, die die Burg Steinwacht besetzt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[26709] = { id = 26709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Steinthron", description = "Ich kehre auf meinen Thron zurück. Ich habe kein Verlangen danach, noch mehr vom Irdenen Ring zu sehen, aber Ihr seid hier stets willkommen, {race}. Wenn Ihr uns beim Wiederaufbau unseres Reichs helfen wollt, dann können wir Euch vielleicht ebenfalls helfen.\n\nAlles zu seiner Zeit.", sourceObjective = "Sucht nach Therazane bei Therazanes Thron.", completion = "Ihr seid zurückgekehrt. Das ist gut. Die Steinlords haben nach Euch gefragt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26710] = { id = 26710, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Tiefen verloren", description = "Kieselchen hat es schon wieder geschafft, sich zu verlaufen, irgendwo in den Bruchtiefen.\n\nEr hat Glück, dass er so klein und dadurch für die Schleifwürmer uninteressant ist. Es ist aber nur eine Frage der Zeit, bevor er zu nah an einem von ihnen vorbeikommt und doch aufgefressen wird. Warum auch immer er da unten ist, es kann einfach nicht so wichtig sein.\n\nEr scheint Euch zu mögen. Zieht bitte los, um ihn zu finden, und bringt ihn aus diesen Tunneln zu einem sichereren Spielplatz.", sourceObjective = "Findet Kieselchen in den Bruchtiefen und geleitet ihn sicher aus den Tunneln.", completion = "Das habt Ihr gut gemacht. Nun können diese Felslinge unsere Traditionen erlernen und groß und stark werden.\n\nEines Tages werden wir diese Tunnelgräberplage in unserem Reich auslöschen, damit die Felslinge nicht mehr während ihrer Jugend leiden müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26711] = { id = 26711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ab zur Bank", description = "Jo, Schätzchen. Was geht? Schon bereit für die Party?\n\nNein?! Du weißt doch, dass ich dich heiß und innig liebe, also weiß ich nicht ganz, wie ich es sagen soll, aber… Ich glaube, du solltest mal in der Stadt nach einem neuen Outfit für die Party suchen.\n\nGuck mich nicht so an... Du willst doch klasse für mich aussehen, ooooder? Willst du für mich nicht superschick sein?\n\nSchau erst bei der Bank vorbei und hol dir ausreichend Moneten. Du willst ja schließlich keinen Billigkram kaufen!", sourceObjective = "Sprecht mit dem Kassierer der EBvK in der Ersten Bank von Kezan auf Kezan.", completion = "Oh, Ihr seid es, Madame! Tut mir leid, bei dem ganzen Pöbel, der hier herumschwirrt, habe ich Euch nicht gleich erkannt.\n\nIhr rumlaufenden Leute! Macht mal langsam hier! {name} ist da!\n\nHier sind Eure Moneten, meine Dame. Kommt jederzeit wieder, wenn Ihr mehr braucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26712] = { id = 26712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ab zur Bank", description = "Hey, mein Süßer. Schon bereit für die Party?\n\nNein?! Du weißt doch, dass ich dich heiß und innig liebe, hm? Ich finde, du solltest mal in die Stadt gehen und ein neues Outfit für die Party kaufen.\n\nGuck mich nicht so an... Du willst doch sicher gut aussehen? Willst du nicht gut für mich aussehen? Ich bin schließlich deine Freundin!\n\nSchau unbedingt erst bei der Bank vorbei und hol dir ausreichend Moneten. Kauf' nichts von diesem Billigkram!", sourceObjective = "Sprecht mit dem Kassierer der EBvK in der Ersten Bank von Kezan auf Kezan.", completion = "Oh, Ihr seid es, mein Herr! Tut mir leid, bei dem ganzen Pöbel, der hier herumschwirrt, habe ich Euch nicht gleich erkannt.\n\nIhr rumlaufenden Leute! Macht mal langsam hier! {name} ist da!\n\nHier sind Eure Moneten, mein Herr. Kommt jederzeit wieder, wenn Ihr mehr braucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26713] = { id = 26713, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endkampf in Steinwacht", description = "Es ist nur noch das Oberkommando des Schwarzfels übrig, {name}. Sie haben sich in der Burg Steinwacht verbarrikadiert, unmittelbar südlich unserer Position hier an Keeshans Posten. Begleitet die Kompanie Bravo zur Steinwacht und beendet die Invasion der Schwarzfelsorcs.\n\n{name}, keine Überlebenden.", sourceObjective = "Tötet Tharil'zun und Gath'Ilzogg.", sourceObjectiveStatus = "unverified-source-field" }
quests[26714] = { id = 26714, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkelflamme, Brut des Weltenbrechers", description = "Als Trottmann verstummt, wird die Welt um Euch herum plötzlich unheimlich still. In einiger Entfernung seht Ihr einen ausgewachsenen schwarzen Drachen!", sourceObjective = "Ruft Dunkelflamme mit dem Horn der Beschwörung. Besiegt Dunkelflamme.", completion = "<Eine einzelne Träne rinnt über Trottmans linke Wange.>\n\nSie starben bei der Verteidigung der Allianz. Bei der Verteidigung unseres Königreichs! Es sind Helden, und so wird man sie auch zur letzten Ruhe betten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26715] = { id = 26715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Malfurion Sturmgrimm", description = "Ich habe Malfurion Euer Kommen angekündigt. Er schien sehr daran interessiert zu sein, Euch persönlich zu treffen.\n\nIhr solltet ihn im Tempel des Mondes aufsuchen. Er steht neben unserer geliebten Tyrande Wisperwind. Seit seiner Rückkehr ist er nicht von ihrer Seite gewichen.\n\nAber ich muss Euch warnen... Malfurion hat seine Zweifel. Es könnte sein, dass Euer Volk Euch eine große Last aufgebürdet hat, als es Euch auswählte, sich mit ihm zu treffen.", sourceObjective = "Sprecht mit Malfurion Sturmgrimm im Tempel des Mondes in Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[26717] = { id = 26717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worgen auf Yorgen", description = "Meinesgleichen in Rabenflucht versuchen, die wilden Worgen in diesen Wäldern zu heilen. Der Zustand selbst lässt sich nicht aufheben, doch denjenigen, die sich noch nicht zu sehr verloren haben, kann man den Verstand zurückgeben.\n\nDen meisten kann man zwar nicht mehr helfen, aber wir achten auf die, die noch Überreste ihres Verstandes besitzen... eine Verbindung zu ihrem früheren Leben.\n\nAuf Yorgens Bauernhof habe ich einen einzelnen Worgen gesehen, der in einem Erdhaufen zwischen den Gebäuden grub... könntet Ihr Euch diesen Erdhaufen ansehen? Vielleicht hat er dort etwas zurückgelassen.", sourceObjective = "Untersucht den Haufen lockerer Erde auf Yorgens Bauernhof.", completion = "Scheint ja knapp gewesen zu sein! Aber er lief weg, ohne Euch noch mehr zu verletzen...\n\nVielleicht kämpft er noch dagegen an. Meister Harris muss das erfahren!", sourceObjectiveStatus = "unverified-source-field" }
quests[26718] = { id = 26718, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brotkrumen zum Ödland", description = "Etwas schlimmes ist geschehen." }
quests[26719] = { id = 26719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung an Meister Harris", description = "Meister Harris muss sofort davon erfahren.\n\nHier, bringt dieses Paket mit Leichengras die Straße hinunter zum Lager in Rabenflucht. Erzählt ihm, was wir auf Yorgens Bauernhof gesehen haben.", sourceObjective = "Bringt Oliver Harris in Rabenflucht das Bündel Leichengras.", progress = "Was bringt Euch nach hier draußen, mein Herr?", completion = "Willkommen in unserem bescheidenen Lager. Schön würde ich es nicht nennen, aber es ist zumindest etwas abgeschieden.\n\nWie bitte? Ein {race} auf dem Hof?", sourceObjectiveStatus = "unverified-source-field" }
quests[26720] = { id = 26720, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Fluch, den wir nicht brechen können", description = "Was wir hier machen, bringt keine Heilung. Die Verwandlung kann nach ihrer Vollendung nicht rückgängig gemacht werden.\n\nDoch der Verstand... Die Alchemie kann den Verstand zurückbringen, wenn noch genug davon übrig ist. Der Worgen, dem Ihr begegnet seid, kämpft anscheinend um seinen, {name}. Wir müssen ihn wiederfinden.\n\nEr ist von Yorgens Hof geflohen, also durchsucht Addles Siedlung im Süden; vielleicht lauert er in einem der Gebäude.\n\nInjiziert ihm den Inhalt dieser Ampulle, er wird ihn betäuben. Ihr müsst ziemlich nah herankommen.", sourceObjective = "Durchsucht Addles Siedlung nach dem lauernden Worgen und betäubt ihn mit Harris' Ampulle.", completion = "Ihr habt ihn!\n\nWir haben keine Zeit zu verlieren. Wir werden die Verabreichung des Serums sofort vorbereiten.\n\nBIBBERS! Bereitmachen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26721] = { id = 26721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bibbers Spinnen", description = "M-Meister Harris benötigt viele Reagenzien für seine Seren. Ich muss sie für ihn sammeln.\n\nDie meisten sind nicht so schlimm... Leichengras ist natürlich schlimm, aber nicht halb so schlimm wie Witwengift. Habt Ihr Euch die Witwen hier in der Gegend mal angesehen? Schon die Jungen sind mannsgroß. Selbst mit einem Gewehr halte ich die Jagd auf sie nicht aus!\n\nSie jagen mir zu viel Angst ein. Wenn Ihr sie für mich jagt, werde ich Euch gern dafür bezahlen! Bringt nur etwas Witwengift mit! Ihr findet sie in den Wäldern im Osten, direkt nördlich der Straße.", sourceObjective = "Erbeutet 8 Witwengiftbeutel von schwarzen Witwen.", progress = "Habt Ihr sie? Bitte sagt mir, dass Ihr sie habt...", completion = "Oh danke, vielen Dank! Ihr habt mich vor den Wäldern mit all diesen furchtbaren Kreaturen bewahrt!\n\nZumindest für einen Tag...", sourceObjectiveStatus = "unverified-source-field" }
quests[26722] = { id = 26722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tief vergraben", description = "<Ihr befestigt den Bogen am Stab. Das Artefakt ist fast komplett. Doch es gibt eine große Lücke mitten im Kopf des heiligen Symbols.>\n\n<Erneut scheint es an Eurem Arm zu ziehen und Euch zu einem Loch in der Wand und den verschlungenen Tunneln dahinter zu führen. Dort muss sich das letzte Teil befinden.>", sourceObjective = "Sucht im Tunnel unter den Katakomben des Morgenrotwaldes nach dem lichtgeschmiedeten Wappen.", completion = "<In den dunkelsten Tiefen dieses Lehmtunnels entdeckt ihr ein schwaches Leuchten. Das letzte Teil ist gefunden!>", sourceObjectiveStatus = "unverified-source-field" }
quests[26723] = { id = 26723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal von Morbent Teufel", description = "Der letzte, an den ich mich erinnere, bevor ich mich in den Wäldern verlor, ist Morbent Teufel. Er war ein abscheulicher Totenbeschwörer und der Grund dafür, dass so viele widerwärtige Untote dieses Land heimsuchen.\n\nIch habe einen Abenteurer gebeten, ihm ein Ende zu machen. Ich hatte angenommen, dass das auch geschehen sei! Aber Schwester Elsington hat mir gesagt, das Land sei immer noch voller Ghule und Schreckgespenster, die aus dem Grab gerissen wurden.\n\nMorbent Teufel hätte seinen letzten Atemzug in dem Haus auf dem Verlassenen Gut, nördlich des Friedhofs von Rabenflucht tun sollen. Seht nach, was aus ihm geworden ist...", sourceObjective = "Sucht auf dem Verlassenen Gut nach Hinweisen auf Morbent Teufel.", completion = "Seine Kleidung und Blutflecken? Wenn das keine Tricks sind, dann etwas noch schlimmeres...", sourceObjectiveStatus = "unverified-source-field" }
quests[26724] = { id = 26724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der lauernde Lich", description = "Die anderen teilen meinen Verdacht. Morbent Teufel lebt im Untod weiter... und ist vielleicht noch mächtiger als zuvor. Ein Totenbeschwörer wurde getötet, doch an seine Stelle könnte ein Lich getreten sein. Und er wird dieses Land weiter zerstören.\n\nIch erinnere mich daran, wie der Dämmerwald vor all dem war, {name}. Ich erinnere mich an einen hellen Himmel und friedliche Wälder. Das kann nicht so weitergehen! Morbent Teufel muss endlich gestoppt werden.\n\nSprecht mit Schwester Elsington. Ihre Vision verrät Euch vielleicht, wo sich Morbent Teufel aufhält und wie man ihn besiegen kann.", sourceObjective = "Sprecht mit Schwester Elsington.", completion = "Es ist ermutigend, dass jemand, der sich erst kürzlich erholt hat, von den Nöten anderer berührt wird. Sven erspart sich Leid, weil er nicht über sein eigenes Unglück grübelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26725] = { id = 26725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vom Lichte geführt", description = "Sven hat Recht. Ich fühle etwas Mächtiges und Böses tief unter dem Friedhof von Rabenflucht. Das Böse verbirgt sich in seinen Katakomben. Morbent Teufel könnte die Ursache dafür sein.\n\nIhr werdet die Macht des Lichts brauchen, um ihn zu besiegen, {name}. Sven sagte mir, dass die Helden, die Morbent Teufel ursprünglich töteten, ein Artefakt aus lichtgeschmiedetem Eisen benutzten, das von heiliger Macht erfüllt war. Das Artefakt ist immer noch hier!\n\nIch fühle es ebenfalls. Es ist ein schimmerndes Licht in der Dunkelheit. Sucht in Rabenflucht danach und lasst Euch vom Licht führen.", sourceObjective = "Findet die lichtgeschmiedete Rute auf dem Friedhof von Rabenflucht.", completion = "<Ihr findet einen leuchtenden Metallstab, der in der kalten Erde vergraben wurde. Doch es gibt Löcher darin. Anscheinend fehlen Teile des Artefakts.>", sourceObjectiveStatus = "unverified-source-field" }
quests[26726] = { id = 26726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Triumphale Rückkehr", description = "Kehrt nach Seenhain zurück und meldet Solomon, dass die Invasion des Schwarzfels vereitelt wurde. Sorgt dafür, dass er den Preis für unsere Freiheit begreift - dass wir fünf unserer größten Helden verloren haben, um das Rotkammgebirge und letzten Endes auch Sturmwind zu retten.\n\nIhr seid der letzte Überlebende der Kompanie Bravo, {name}. Sorgt dafür, dass ihr Vermächtnis weiterlebt.\n\nWegtreten.", sourceObjective = "Meldet Euch bei Magistrat Solomon in Seenhain im Rotkammgebirge.", completion = "Man wird sie niemals vergessen, {name}. Die Geschichte von dem, was Ihr und der Rest der Kompanie Bravo geopfert habt, um das Rotkammgebirge zu retten, werden noch viele Generationen hören.\n\nDen Verlust Eurer Freunde kann ich nicht wettmachen, trotzdem möchte ich Euch für eine solch heroische Tat belohnen. Hier sind Keeshans Habseligkeiten - mehr haben wir nicht gefunden, als wir den See nach seiner Leiche absuchten. Trottmann hat mir erklärt, Keeshan hätte sicherlich gewollt, dass der einzige Überlebende der Kompanie Bravo etwas davon nimmt. Vergesst sie nicht, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[26727] = { id = 26727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rache des Einbalsamierers", description = "Ihr seid nicht der erste Narr, der von Calvinius manipuliert wurde! Wir nennen diesen tüdeligen alten Mann den Einbalsamierer. Er ist ein abscheulicher Totenbeschwörer und der Fluch dieser Stadt.\n\nUnd nun nähert sich uns seine schreckliche Schöpfung, die mit den Materialien, die Ihr ihm gebracht habt, zusammengenäht und ins Leben gerufen wurde!\n\nDiese schreckliche Kreatur wird in wenigen Momenten über uns kommen! Wenn Ihr ein Herz habt, {name}, dann werdet Ihr der Nachtwache helfen, diese Monstrosität zu vertreiben und unsere Stadt zu retten!", sourceObjective = "Tötet Kleiner in Dunkelhain.", completion = "Dem Lichte sei Dank, er ist weg...\n\nIhr habt durch Eure Hilfe bei der Rettung der Einwohner Wiedergutmachung geleistet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26728] = { id = 26728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Dämmerwald!", description = "{name}, die Bürger von Dämmerwald benötigen dringend Eure Unterstützung! Ich habe hier einen Brief von Kommandantin Althea Schwarzhaupt, der Anführerin der Nachtwache. Sie bittet um Hilfe.\n\nUm nach Dunkelhain zu kommen, solltet Ihr die Brücke benutzen, die sich in der südwestlichen Ecke des Rotkammgebirges befindet. Auf der anderen Seite der Brücke beginnt Dämmerwald. Dann müsst Ihr nur noch der Straße nach Dunkelhain folgen. Hütet Euch vor den wilden Bestien, die außerhalb der Ortschaften lauern!", sourceObjective = "Reist nach Dämmerwald und meldet Euch bei Kommandantin Althea Schwarzhaupt in Dunkelhain.", completion = "Ihr seid die Hilfe, die wir angefordert haben?\n\n<Althea seufzt.>\n\nDann müsst Ihr uns wohl genügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26729] = { id = 26729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wasserelementare", description = "Ich kam ins Schlingendorntal, um etwas zu untersuchen, das Altar von Naias genannt wird, doch dummerweise widersetzte ich mich Colonel Kurzens Annährungsversuchen, was mir einige Jahre in diesem Käfig dort einbrachte. Jetzt bin ich wieder draußen, also spricht nichts dagegen, meine ursprünglichen Studien fortzusetzen .\n\nDer Altar steht auf einer Insel im Westen, südlich von Zul'Kunda. Besorgt mir einige Armschienen von den Wasserelementaren der Insel.\n\nOh, und Ihr könnt dieses Gerät benutzen, wenn Ihr fertig seid. Dann müsst Ihr den ganzen Weg hierher zurück nicht laufen.", sourceObjective = "Holt 6 Armschienen eines Wasserelementars.", progress = "Ja, {name}?", completion = "Die reichen für meine Zwecke. Allerdings können wir den Altar nicht nur mit Armschienen aktivieren...", sourceObjectiveStatus = "unverified-source-field" }
quests[26730] = { id = 26730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Man kann den Murloc aus dem Ozean holen...", description = "Ich brauche etwas, um an die reine, elementare Kraft dieser Armschienen zu kommen... etwas starkes und abschleifendes, was aber dennoch zum Meer gehört.\n\nDie Murlocs der Düsterkiemen sind vom Meer ins Landesinnere gezogen, tragen aber immer noch Phiolen mit Meersalz bei sich. Ich weiß nicht, wofür sie das Salz benötigen, aber es eignet sich gut für unsere Studien. Ihr findet die Düsterkiemen im Tal südlich des Rebellenlagers und östlich der Ruinen von Bal'lal.", sourceObjective = "Holt 6 Phiolen mit Meersalz von den Murlocs der Düsterkiemen im Nördlichen Schlingendorntal.", progress = "Das Salz?", completion = "Wir haben, was wir brauchen. Seid Ihr bereit dazu, den Altar von Naias zu aktivieren, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[26731] = { id = 26731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Altar von Naias", description = "Das Salz, das Ihr gebracht habt, reichte aus, um die Verzauberungen im Inneren der Armschienen zu aktivieren. Ich habe diese Verzauberungen gesammelt und zu einem Beschwörungsstein zusammengefügt... eine Gabe, könntet Ihr sagen.\n\nKehrt zur Insel Naias zurück und legt die Gabe auf Naias' Altar. Ruft mich, wenn Ihr Naias' Herz habt.", sourceObjective = "Beschwört Naias mit Naias' Gabe und holt das Herz von Naias.", progress = "Ich warte gespannt auf das Ergebnis.", completion = "Meine Kollegen von den Kirin Tor werden sich freuen, dass das Herz nun uns gehört.\n\nDanke für Eure Unterstützung, {name}. Ohne Euch hätte ich das nicht geschafft.", sourceObjectiveStatus = "unverified-source-field" }
quests[26732] = { id = 26732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlechte Medizin", description = "Ich habe den Verdacht, dass Kurzens Medizinmänner nicht nur Medizin verteilen. Kurzen benötigt etwas, um aufkeimenden Ungehorsam zu ersticken. Ein Elixier getarnt als \"Medizin\", wäre dafür sehr gut geeignet.\n\nWir brauchen diese Arzneien für unsere Studien. Durchsucht Kurzens Truppenlager im Südosten - seine Medizinmänner und Dschungelkämpfer sollten die Heilmittel bei sich tragen.", sourceObjective = "Besorgt 7 Dschungelarzneien aus Kurzens Truppenlager.", progress = "In meiner Freizeit beschäftige ich mich ein wenig mit Alchemie.", completion = "Gut gemacht, {name}. Dann wollen wir mal sehen, was in diesem Elixier steckt...", sourceObjectiveStatus = "unverified-source-field" }
quests[26733] = { id = 26733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kontrollprobe", description = "<Bruder Nimetz analysiert die Proben, die Ihr ihm gegeben habt.>\n\nDas... das ist nur Basiliskenblut!\n\nNein, es besteht größtenteils aus Basiliskenblut. Sie haben jedoch etwas hinzugefügt. Für einen vernünftigen Vergleich brauche ich eine Kontrollprobe.\n\nWahrscheinlich stammt das Blut von Kristallrückenbasilisken, die östlich des Truppenlagers vorkommen. Bringt mir einige reine Proben, dann kriege ich schon heraus, was in dem Elixier ist.", sourceObjective = "Besorgt 7 Proben Kristallrückenbasiliskenblut.", progress = "Etwas in diesem Elixier ist nicht gerade gesundheitsförderlich, {name}. Ich habe meine Analyse zwar noch nicht beendet, aber ich kann es spüren.", completion = "Das reicht. Wartet bitte einen Moment, während ich es teste.", sourceObjectiveStatus = "unverified-source-field" }
quests[26734] = { id = 26734, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Quelle des Wahnsinns", description = "Ich habe das Basiliskenblut aus dem Elixier reduziert. Dabei habe ich einen ungewöhnlichen Bestandteil gefunden. Es scheint sich um eine Art blauen Kristall zu handeln...\n\n<Bruder Nimetz betrachtet seine Notizen.>\n\nEs ist kein singender blauer Kristall... und auch kein pulsierender blauer Splitter...\n\n<Er blättert einige Seiten vor.>\n\n... kein Stück des Gedankenauges. Nein, so etwas haben wir in Schlingendorntal noch nie gesehen. Jemand muss doch noch etwas von dieser Substanz besitzen. Ich will sie haben. Seht bei Kurzens hochrangigen Truppen hinten in ihrer Höhle nach.", sourceObjective = "Erbeutet einen flüsternden blauen Stein von Kurzens Truppen im Vorratslager.", progress = "Geht bitte vorsichtig damit um, {name}. Wir wissen nicht, was es ist.", completion = "<Bruder Nimetz öffnet einen Beutel. Ihr legt den Kristall hinein.>\n\nIch wusste, dass jemand noch etwas von dieser Substanz haben würde. Ich werde dies meinen Kontakten in Fort Livingston südlich von hier schicken. Hoffentlich haben sie etwas mehr Glück damit.\n\nDanke für alles, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26735] = { id = 26735, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kurzens Schicksal", description = "Hallo, {class}.\n\nWir sind Soldaten aus Sturmwind und haben in Kurzens Truppenlager rebelliert. Der große Außenposten liegt südöstlich von hier. Wir standen unter dem Kommando von Colonel Kurzen, bis er und seine Vertrauten begannen, den Verstand zu verlieren...\n\nWir lehnten uns auf, errichteten hier unser Lager und wehrten uns gegen Kurzen. Nun habe ich von meinen Kontakten erfahren, dass Kurzen verschwunden ist. Ich traue dieser Quelle, aber ich möchte das noch einmal von einem Außenstehenden hören. Bitte begebt Euch in das Lager und sucht nach Belegen für sein Schicksal.", sourceObjective = "Findet das Gefängnisregister von Kurzens Truppenlager und die Offiziersakten von Kurzens Truppenlager.", progress = "Habt Ihr etwas entdeckt, {name}?", completion = "Sie haben ihn UMGEBRACHT? Dabei dachte ich die ganze Zeit, er würde mit eiserner Hand über sie herrschen...", sourceObjectiveStatus = "unverified-source-field" }
quests[26736] = { id = 26736, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vom Wahnsinn verschont", description = "Kurzens Tod ist eine Erleichterung, aber interessanter und momentan wesentlicher ist, dass dies ein Zeichen dafür sein könnte, dass es potentielle Verbündete im Lager gibt.\n\nMich interessiert nicht, was in dem Gefängnisregister steht. Ich weiß GENAU, weshalb die 3 eingesperrt wurden: weil sie sich weigerten, Befehle zu befolgen. Der Wahnsinn muss sie verschont haben, so wie meine Rebellenkameraden hier. Sie wurden eingesperrt, weil sie aufbegehrten.\n\nFindet sie, {name}. Findet sie und schickt sie hierher.", sourceObjective = "Rettet Berrin Brennfeder, Emerine Junis und Osborn Grausikus aus Kurzens Truppenlager.", completion = "Danke, {name}. Ich lag mit meiner Vermutung anscheinend richtig... die drei Gefangenen scheinen der Krankheit, die Kurzen und den Rest seiner Männer ergriffen hat, entkommen zu sein.\n\nVor Eurer Ankunft teleportierte Emerine sich und die anderen nach Sturmwind, um sich nach all den Entbehrungen zu säubern. Sie haben versprochen, bald zurückzukommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26737] = { id = 26737, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beendet Kurzens Vermächtnis", description = "Unsere Verbündeten wurden aus Kurzens Truppenlager evakuiert, nun müssen wir es ein letztes Mal angreifen. Sie werden nie wieder so schwach sein wie gerade und mit Eurer Hilfe können wir sie vielleicht so weit schwächen, dass sie sich nicht mehr davon erholen.\n\nDiese vier Namen, die in den Offiziersakten erwähnt werden - Anders, Gaulus, Miranda und Esquivel - sind die höchstrangigen übrig gebliebenen Soldaten. Sucht nach ihnen in der Höhle im hinteren Teil des Truppenlagers. Sollten diese vier verschwinden, werden die Konsequenzen für Kurzens Streitkräfte verheerend sein.\n\nGehet mit Ehre, {name}.", sourceObjective = "Tötet Oberstabschef Anders, Oberstabschef Gaulus, Oberstabschef Miranda und Oberstabschef Esquivel im Vorratslager.", completion = "Hervorragend gelöst, {name}. Meine Männer und ich kümmern uns um den Rest.\n\nOhne Kurzen können wir vielleicht die Expedition, die wir im Schlingendorntal geplant hatten, fortsetzen und... ahh...\n\nSpielt keine Rolle. Bitte seht Euch in unseren Rüstungslagern um. Vielleicht findet Ihr etwas passendes.", sourceObjectiveStatus = "unverified-source-field" }
quests[26738] = { id = 26738, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frisch geschlüpft", description = "Als Ihr die Sachen des Soldaten durchsucht, bemerkt Ihr ein frisch geborenes, weibliches Raptorjunges, das zu Euch aufsieht. Ist es Kurzens Milizsoldaten die ganze Zeit über gefolgt?\n\nIhr seht, wie es Euch mustert, sich Euer Gesicht einprägt und Eure Bewegungen beobachtet.\n\nDas Schmetterschwanzjunge geht eine Bindung mit Euch ein.\n\nVielleicht weiß jemand im Rebellenlager etwas mit einem Raptorjungen anzufangen.", sourceObjective = "Bringt das Schmetterschwanzjunge zu Korporal Sethmann im Rebellenlager im Nördlichen Schlingendorntal.\n\nBereitgestellter Gegenstand:", completion = "Ja, die Kleine scheint Euch zu mögen. Ihr habt Glück... in diesem Alter sind Raptoren ruhig, friedlich und leicht auszubilden. Behaltet sie, {name}... sie könnte Euch noch von Nutzen sein.\n\nUm genau zu sein...", sourceObjectiveStatus = "unverified-source-field" }
quests[26739] = { id = 26739, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich glaube, sie hat Hunger", description = "Euer junges Raptorweibchen scheint hungrig zu sein. Wenn Ihr sie behalten wollt, solltet Ihr vielleicht etwas zu fressen für sie finden. Die Schmetterschwänze greifen häufig die Basilisken des Schlingendorntals an. Man findet sie im Osten hinter Kurzens Truppenlager.\n\nWahrscheinlich ist sie noch nicht stark genug, um allein auf die Jagd zu gehen, aber ich bin mir sicher, dass sie frisches Basiliskenfleisch fressen wird.", sourceObjective = "Tötet Kristallrückenbasilisken im Nördlichen Schlingendorntal und lasst Euren Schmetterschwanz 40 Bissen ihres Fleisches fressen.", completion = "Sie wirkt schon größer! Wie Ihr seht, wachsen diese Raptoren schnell. Ihr könnt von Glück sagen, dass Ihr eine so starke Begleiterin gefunden habt.\n\nBehaltet sie bei Euch, so lange es geht, {name}. Sie wird sich bestimmt irgendwann als Gewinn für Euch erweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26740] = { id = 26740, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kochen mit Krazek", description = "Meistens bin ich es, der hier im Lager kocht. Und das war auch immer ganz schön viel Arbeit, bis ich von einem Goblinhändler in Beutebucht einen mechanischen Kochtopf gekauft habe. Der Topf ist einfach unglaublich. Er hat mir unzählige Stunden Arbeit erspart - bis er kaputtgegangen ist!\n\nKönnt Ihr den Topf dem Goblin zurückbringen, damit er ihn mir repariert? Der Händler heißt Krazek. Das letzte, was ich gehört habe, war, dass er bei Nesingwary Unterschlupf gefunden hat, im Jägerlager im Süden.", sourceObjective = "Bringt Krazeks Spezialtopf zu Krazek.", progress = "Hallo! Ihr habt etwas für mich?", completion = "Ah ja, das ist einer von Krazeks Spezialtöpfen! Eine geniale Erfindung, aber bisweilen bricht eine Feder oder das Getriebe gerät aus dem Tritt oder so was in der Art. Lasst mich mal sehen, was mit dem hier los ist...\n\nAha! Die Dampfbeschickungsvorrichtung ist völlig verrostet, die Gelenkdichtung ist rissig und dem Fobulator fehlen Zähne. Es wundert mich, dass der Topf in diesem Zustand überhaupt irgendetwas kochen konnte!\n\nOb ich ihn reparieren kann? Natürlich kann ich ihn reparieren!\n\nAber das kostet. So etwas kostet immer, oh ja...", sourceObjectiveStatus = "unverified-source-field" }
quests[26741] = { id = 26741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE" }
quests[26742] = { id = 26742, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erkenntnisse über die Blutskalpe", description = "Ich habe mich nie richtig bei Euch für meine Rettung bedankt.\n\nDanke, {name}.\n\nIch bin immer noch etwas erschöpft von meiner Gefangenschaft, deshalb dachte ich, Ihr könntet mir vielleicht bei meinen Studien helfen. Als ein Schamane des Wildhammerklans interessiere ich mich natürlich sehr für die schamanistischen Methoden des Blutskalpklans.\n\nIhre Magie scheint sich in eine interessante Richtung entwickelt zu haben. Hätte ich eines der Totems, die ihre Schamanen benutzen, könnte ich mit meinen Studien beginnen. Ihr findet sie in den Ruinen von Bal'lal, an der Küste im Südwesten.", sourceObjective = "Besorgt ein Totem der Blutskalpe von einem Schamanen der Blutskalpe.", progress = "Seid vorsichtig. Sie werden sich wahrscheinlich wehren.", completion = "<Berrin betrachtet die Inschriften auf dem Totem.>\n\nIch glaube, ich kann die Worte lesen... Faszinierend!\n\nTsul'kalu, Mahamba, Pogeyan... was sind das für Namen?", sourceObjectiveStatus = "unverified-source-field" }
quests[26743] = { id = 26743, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Blutskalpen heilig", description = "Ahh... das müssen die Namen ihrer Totemwesen sein - der Tiere, die sie den Geistern zuordnen. Mal sehen... Mahamba als Wasser, Tsul'Kalu als Erde, Pogeyan als... Luft? Feuer? Diesen Teil kann ich nicht entziffern.\n\nIch würde gern mehr über ihre Geister erfahren. Hier in der Nähe, in den Ruinen von Tkashi, haben die Blutskalpe ein Lager errichtet. Vielleicht könnt Ihr dort Einzelheiten herausfinden.", sourceObjective = "Besorgt eine Ikone von Tsul'kalu, eine Ikone von Mahamba und eine Ikone von Pogeyan aus dem Lager der Blutskalptrolle in den Ruinen von Tkashi.", progress = "Wahrscheinlich basieren die Totemwesen auf einigen der fantastischen Kreaturen, die durch diesen Dschungel streifen.", completion = "Erst rettet Ihr mich aus der Zelle des Wahnsinnigen und nun bringt Ihr mir einige der Schlüssel zum Verständnis des Trollschamanismus.\n\nDiese Woche kann sich sehen lassen!\n\nNoch einmal vielen Dank, {name}. Ich werde dafür sorgen, dass der Wildhammerklan Euch unterstützt, wenn Ihr Eure Reise fortsetzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26744] = { id = 26744, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefe Wurzeln", description = "Doch nun zu etwas anderem: Ich stelle gerade eine Sammlung von Trollgeschichten und -legenden für ein... persönliches Projekt zusammen. Vielleicht könntet Ihr mir helfen, einige davon zu finden.\n\nDie Blutskalpe in den Ruinen von Bal'lal, an der Küste im Südwesten, besitzen eine große Schrifttafel, auf der einige ihrer Geschichten festgehalten sind. Ich würde Euch natürlich für die Geschichten, die Ihr mir bringt, entschädigen.", sourceObjective = "Holt die Schrifttafel der Blutskalpe aus den Ruinen von Bal'lal im Nördlichen Schlingendorntal.", progress = "Seid Ihr schon in den Ruinen von Bal'lal gewesen? Habt Ihr die Tafel gefunden?", completion = "Um ehrlich zu sein, schicke ich diese Informationen zu meiner Frau und meinem Sohn zuhause in Sturmwind. Sie möchten wissen, was ich hier draußen im Dschungel mache, aber ich kann sie nur selten besuchen. Jede Kleinigkeit hilft.\n\nDanke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26745] = { id = 26745, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieblingsschädel", description = "Euer zahmes Raptorweibchen scheint ein neues Spielzeug gefunden zu haben: Einen Schädel von einem nahegelegenen Trollschädelhaufen.\n\nIhr wisst nicht, was diesen Schädel von den anderen unterscheidet, aber aus irgendeinem Grund lässt sie ihn nicht wieder fallen.\n\nOsborn Grausikus, der Gnom, den Ihr aus Kurzens Truppenlager gerettet habt, ist ein Experte für Trollgeschichte und Trollphysiologie. Vielleicht weiß er, warum dieser Schädel etwas besonderes ist.", sourceObjective = "Meldet Euch bei Osborn Grausikus im Rebellenlager und zeigt ihm den neuen Schädel Eures Schmetterschwanzjungen.\n\nBereitgestellter Gegenstand:", completion = "Was haben wir denn da? Ein junger Raptor mit seinem Haustier: seinem Hausmensch. Hah!\n\nAber kommen wir zu Wichtigerem: Was für einen Schädel habt Ihr da? Das war kein gewöhnlicher Troll. Er war groß...\n\n<Osborn klopft auf den Schädel.>\n\n... und stark. Wisst Ihr, ich wollte immer schon mal Trollmagie ausprobieren. Kann doch nicht so schwer sein, oder? Wollen wir diesen starken Mann als Versuchskaninchen nehmen?", sourceObjectiveStatus = "unverified-source-field" }
quests[26746] = { id = 26746, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Gespür für solche Dinge", description = "<Osborn wirft noch einen Blick auf den Schädel.>\n\nAls er noch lebte, war er stark und mächtig, ein Fürst der Trolle. Mit unserer Hilfe kann er wieder ein Fürst werden.\n\nDie Strauchdiebe der Blutskalpe, die durch die Ruinen im Südwesten ziehen, sammeln magische Fetische, die wir gebrauchen könnten. Sie vergraben diese Artefakte, um sie zu verstecken. Findet diese Artefakte mit Hilfe Eures Jungen, {name}... und bringt sie dann her.", sourceObjective = "Lasst Euer Schmetterschwanzjunges 8 Tkashifetische erschnüffeln.", progress = "Wie viele Fetische habt Ihr gefunden?", completion = "Die verschaffen uns ein wenig... wie heißt noch gleich dieses Trollwort? Voodoo? Juju? Tiklabang?\n\nIst egal. Wenn wir einen Troll neu erbauen wollen, brauchen wir Trollmagie und diese Fetische sind voll davon.", sourceObjectiveStatus = "unverified-source-field" }
quests[26747] = { id = 26747, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Exemplar aus Fleisch und Blut", description = "Die Seele ist bereit, der Körper jedoch nicht. Für einen Schädel, der so wohlgeformt, so wunderbar und so schön wie dieser ist, brauchen wir einen passenden Körper.\n\nGan'zulah, der Häuptling der Blutskalpe, ist durch brutale Gewalt auf den Thron gekommen. Sollte er noch leben, werdet Ihr ihn in Zul'Kunda im Westen finden.\n\nSeinen Körper zu rauben, wird nicht leicht sein, aber <ein kräftiger/eine kräftige:c> {class} wie Ihr wird das schon schaffen. Bringt ihn hierher, wenn Ihr fertig seid.", sourceObjective = "Holt Gan'zulahs Leiche aus Zul'Kunda.", progress = "Gan'zulah war ein Schläger und Tyrann. Ich spüre, dass dieser Troll anders sein wird. Diese Trollmagie ist leichter als ich dachte!", completion = "Das habt Ihr gut gemacht, {race}. Wir haben einen Kopf, einen Körper und etwas Juju-Voodoo-Mojo-Unsinn. Jetzt noch ein kleiner Elektroschock, um alles in Gang zu bringen...", sourceObjectiveStatus = "unverified-source-field" }
quests[26748] = { id = 26748, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutfürst Mandokir", description = "{race}. Ihr habt gerade euren schlimmsten Alptraum erweckt. Dachtet Ihr etwa, ich wäre ein Freund, {race}? Ah, ha ha haaaa!\n\nIhr habt Euren Zweck erfüllt. Dank Euch bin ich wieder ins Reich der Lebenden zurückgekehrt. Deshalb werde ich Euch nicht töten, sondern Euch einen Handel anbieten.\n\nGebt mir den Raptor.\n\nEuch dürfte bereits klar sein, dass dies kein gewöhnlicher Raptor ist. Ich brauche einen Ersatz für Ohgan. Tut es, sonst werdet Ihr und der Gnom meine Rache zu spüren bekommen.", sourceObjective = "Bringt Blutfürst Mandokir im Rebellenlager das Schmetterschwanzeifragment.", progress = "Ich verlange nur den Raptor, {race}. Gebt ihn mir, dann lebt der Gnom weiter.", completion = "Freut mich, dass Ihr zur Besinnung gekommen seid.\n\nIhr müsst uns mal in Zul'Gurub besuchen, {race}. Ich werde Euch beobachten...", sourceObjectiveStatus = "unverified-source-field" }
quests[26749] = { id = 26749, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Priesterin Thaalia", description = "Danke, {name}. Ich weiß, dass Ihr mein Leben nicht hättet retten müssen.\n\nEs ist schlimm, dass Blutfürst Mandokir zurückgekehrt ist. Er wurde vor einigen Jahren in Zul'Gurub getötet. Wir dachten, wir würden ihn und sein Volk nie wiedersehen. Die Trolle von Zul'Gurub versuchten sich an einem schrecklichen, widerwärtigen Ritual. Wenn Mandokir lebt, dann ist es nur logisch anzunehmen, dass er nicht der einzige ist.\n\nDie Forscher in Fort Livingston, weit im Süden, wissen vielleicht mehr. Sprecht mit ihrer Priesterin.", sourceObjective = "Sprecht mit Priesterin Thaalia in Fort Livingston im Nördlichen Schlingendorntal.", completion = "Mandokir lebt, ja.\n\nIhr tragt die Verantwortung, ja.\n\nVielleicht könnt Ihr ihn noch aufhalten, ja.", sourceObjectiveStatus = "unverified-source-field" }
quests[26750] = { id = 26750, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Geheiß der Steinmutter", description = "Es ist Zeit. Die Steinmutter wird mit Euch sprechen. Ihr findet ihren Thron im Norden Tiefenheims, über dem Geschliffenen Schlund.", sourceObjective = "Sprecht mit Therazane der Steinmutter.", completion = "Ihr seid also gekommen.\n\nFleischlinge wie Ihr haben meine Tochter getötet... meine einzige Tochter - ohne, dass sie etwas getan hätte.\n\nUnd als ob es nicht schon genug wäre, mich meiner Familie zu berauben, haben sich mehr von Euch um Todesschwinge geschart, um ihm dabei zu helfen, mein Heim zu verwüsten.\n\nWie vermessen von Euch, vor mir zu erscheinen und um MEINE Hilfe zu bitten. Ich bin dazu verleitet, Euch an Ort und Stelle zu vernichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26751] = { id = 26751, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bevölkerungskon-Trolle", description = "Ich habe vernommen, dass Ihr bald nach Zul'Kunda aufbrechen werdet. Ich habe eine kleine Aufgabe, die Ihr dort erfüllen könntet.\n\nDie Trolle werden zu zahlreich für das Schlingendorntal. Die Blutskalpe im Westen, die Schädelspalter im Osten... sie ergießen sich aus ihren Ruinen in den Dschungel und zerstören das natürliche Gleichgewicht der Region. Es wird Zeit, dass wir dieses Gleichgewicht wiederherstellen.\n\nZul'Kunda ist die Hauptstadt der Blutskalpe. Dort werdet Ihr die höchstrangigen Blutskalpe finden. Reduziert ihre Anzahl und kehrt zu mir zurück.", sourceObjective = "Tötet 7 Mystiker der Blutskalpe, 7 Jäger der Blutskalpe, 7 Späher der Blutskalpe und 1 Bestienmeister der Blutskalpe.", completion = "Das Gleichgewicht ist wiederhergestellt - erst einmal. Vielleicht werden wir Euch in Zukunft noch einmal rufen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26752] = { id = 26752, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Audienz bei der Steinmutter", description = "Bleibt wo Ihr seid, Champion. Ich habe noch nicht entschieden, was ich mit Euch und Eurem Irdenen Ring anstelle.", sourceObjective = "Nehmt an der Audienz bei der Steinmutter teil.", completion = "Gut gemacht, Bruder. Die Steinmutter hört zu, und die Weltensäule ist fast zum Greifen nah.", sourceObjectiveStatus = "unverified-source-field" }
quests[26753] = { id = 26753, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hallen der Toten", description = "<Vor Euch neigt sich die nackte Erde dem dunklen Eingang zu den Grüften entgegen.>\n\n<Ihr spürt, wie das lichtgeschmiedete Artefakt Euch darauf zuzieht. Ist das andere Teil vielleicht dort unten?>", sourceObjective = "Findet den lichtgeschmiedeten Bogen in den Katakomben des Morgenrotwaldes.", completion = "<Im Dreck dieser Nische funkelt helles Metall. Ihr habt einen weiteren Teil des Artefakts gefunden!>", sourceObjectiveStatus = "unverified-source-field" }
quests[26754] = { id = 26754, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morbents Bann", description = "<Die Teile passen. Ihr habt das geheiligte Artefakt zusammengesetzt. Es strahlt ein heiliges Licht aus. Damit solltet Ihr in der Lage sein, Morbent Teufels dunkle Magie zu besiegen.>\n\n<Tiefer im Tunnel, entgegengesetzt der Richtung, aus der Ihr gekommen seid, ertönt ein verstörendes Kichern. Es ist das rasselnde Lachen eines Lich. Morbent Teufel ist direkt vor Euch!>", sourceObjective = "Schwächt Morbent Teufel mit Morbents Bann und besiegt ihn.", completion = "Möge das widerliche Ungeheuer dieses Mal tot bleiben!\n\nIch werde nach unten gehen und seine Asche in die Winde verstreuen, {name}. Ihr habt Großes vollbracht. Vielleicht wird in Dämmerwald mit der Zeit wieder Frieden einkehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[26755] = { id = 26755, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg von der Front", description = "Oh, gut! Ihr habt noch ein Katapult mitgebracht! Klei mag älter als Staub sein, aber er weiß, wie man eine schreckliche Kriegsmaschine baut.\n\nNun, Ihr habt es sicher nicht den weiten Weg bis hierher gebracht, weil Ihr ein wenig Bewegung wolltet, Fleischsack. Schwingt Euch in eines dieser Dinger und bombardiert die Fungusschrecken und ihre Verstärkung, die aus Nadelfelsbruch herausströmen.\n\nWir müssen sie von der Front fernhalten!", sourceObjective = "Bombardiert 30 Fungusschrecken und/oder Mitglieder der Verstärkung der Steintroggs.", completion = "Das ist ein guter Anfang, {name}, aber Ihr müsst in die Stadt fliegen und dort ein wenig Aufruhr verursachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26760] = { id = 26760, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Unmögliche möglich machen", description = "Ich bin optimistisch, aber wir sollten professionell bleiben. Wir behandeln ihn wie alle anderen.\n\nAb in die Guillotine mit ihm... und wenn die Alchemie nicht wirkt, kommt er nicht wieder heraus.\n\nBibbers und ich kümmern uns darum. Bitte bleibt zurück und seht aus sicherer Entfernung zu.", sourceObjective = "Seht zu, wie Oliver Harris und Bibbers versuchen, den lauernden Worgen zu heilen.", completion = "Geschafft... Endlich! Ich kann Euch gar nicht genug für die Gelegenheit danken, die Heilung selbst auszuprobieren.\n\nUnser neuer Freund könnte wahrscheinlich ebenfalls Hilfe gebrauchen. Wieso sprecht Ihr nicht mal mit ihm?", sourceObjectiveStatus = "unverified-source-field" }
